/* 平成29年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h29.committeeSessions.push(...[{"id":"h29-20170926-9","meetingId":"h29-cm09","date":"2017年9月26日","dateIso":"2017-09-26","committee":"文教委員会","time":"午前１０時００分～午後 ２時５８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を57件整理しています。","topics":[{"id":"topic-01","title":"学校改築事業の進捗","agenda":"学校改築事業の進捗","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"１階のところで、左側に広場門というのがあると思うのですが、改築したときにこの広場門は生徒が使えるものになるのかどうか伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"かなり広いスペースを体育館が占有するということになりますので、教室を入れることができないということになります。教員がすぐ飛び出していってすぐ対応するなど、それと同じような形で保健室等を１階に置くことで、教室等については２階以上に設計しているものです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、生徒の通学の際に正門と北門からだけになるという考えでいいのか、改めてお聞かせほしいと求めました。これはそうするとどういった活用の仕方になっていくのか、イメージが湧かないものでご説明ほしいと求めました。","respondent":"篠田学校計画担当課長","answer":"これからの検討課題ではあるのですけれども、そういった形で命名をしまして、子どもたちに親しみを持って使ってもらう。運用面については学校の中でさまざまなあろうかと思うのですけれども、こちらのほうは今後学校運営の中で検討していくことを想定しているものです。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"今計画として、４校を示していただいたわけですけれども、今後の計画がどうなっているのかという学校改築の全体像を伺いたいと思います。今ある小中一貫校６校でしたけれども、何か私的には施設見学させていただいたときも、そういうことも含めて伺っておきたいと思います。","respondent":"篠田学校計画担当課長","answer":"そういった部分でどういった対応ができるかということを考えたときに、そういうことも踏まえまして、今回１８クラス規模としたものです。対応できるものに関してはエコスクールの設備をできるだけ入れていくことを考えてありますので、一応方向性としては想定しているものです。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"もちろん保育園もそういうスタンスでやっていただきたいと思っていますけれども、学校の対応というのは、よろしくお願いしたいと思います。そういうのがちょっと心配かなと思って取り上げて質問したので、ぜひ安全性が担保されるようにお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"こんの委員","kind":"質問","question":"普通は校舎と別にというのでしょうか、その際、ここの空調というのはどういうふうに考えていらっしゃるのか。後地ステップの上がそうなるのですか、この図面でどう見たらいいのかというの説明を求めました。","respondent":"篠田学校計画担当課長","answer":"現在のところ、当初から冷暖房の設置というのは今のところ学校の仕様にはございませんので、当初から冷暖房を入れる予定は今のところございません。","id":"exchange-005"},{"speaker":"こんの委員","kind":"確認","question":"確認です。今後もそういう考え方で区の改築される学校を整備していくということでいいのか、３点確認ですが、お願いいたします。","respondent":"篠田学校計画担当課長","answer":"ご説明申し上げたとおり配管だけは通しておくという状況ですので、状況によってはその配管を活かして冷暖房が設置できるように設計しております。それから、最後の体育館の風の吹き抜けにつきましては、説明が不足しておりまして申しわけありません。","id":"exchange-006"},{"speaker":"こんの委員","kind":"確認","question":"参考までに進捗状況を一つだけお伺いしたいのですけれども、今、いつ頃完成になるのでしょうか。ちょっとこれだけ確認したいと求めました。","respondent":"品川庶務課長","answer":"大井第一小学校の人工芝ですけれども、秋ごろを今予定しております。","id":"exchange-007"},{"speaker":"こんの委員","kind":"質問","question":"もう間もなくということで、例えば、校庭で行う授業は全部体育館でやっていたということだったのでしょうか。その辺の説明を求めました。","respondent":"品川庶務課長","answer":"人口芝の工事をしている期間ですけれども、基本的には体育館等を利用しておりまして学校内でいろいろな工夫をしながら体育等を行っているものと考えております。","id":"exchange-008"},{"speaker":"渡部委員","kind":"質問","question":"城南小学校で出た埋蔵文化財は、学校の中で展示室みたいなものをつくって、今後展示するということでよかったのでしょうか。同様に、鮫浜小学校はこれからプロポーザルということですけれども、想定としては何クラスと考えているのかというところもあわせての説明を求めました。","respondent":"篠田学校計画担当課長","answer":"今後なかなか現在の形での説明会、今のところ想定していないものです。鮫浜小学校の学区域内で多数の大きな建物が建つ見込みはないのですけれども、再開発等があるとそちらのほうの選択がなかなかできない。","id":"exchange-009"},{"speaker":"渡部委員","kind":"質問","question":"区内の児童などにも機会があれば見てほしいなという思いで質問をしまして、それがその学区域、さまざまな地域で起こり出しています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"高橋（し）委員","kind":"質問","question":"特別支援教室が２階ですけれども、教室をここに置いたお考えを伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"後地小学校の特別支援教室につきましては、こちらの図面では２階の真ん中あたりに今、実施設計において考えているところです。特別支援教室ですけれども、基本的に設置に関しましては他の学校もそうなのですけれども、普通教室の並びの中でと考えているところです。","id":"exchange-011"},{"speaker":"高橋（し）委員","kind":"意見","question":"ちょっと外れる場所にあったりする所もあるので、今お話になったようなコンセプトで他の児童と交流できるような形でつくっていただくのは大変ありがたいので、ぜひそのお考えで進めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"４階にないと思いますが、実際どうなのかということ、どういったものになるのか伺いたいと思います。今回場所がちょっと変わりますけれども、前回と比べて広くなるのかどうかということと、運用上の変更点があるのかどうか伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"申し訳ありません。スペースが２階にあるけれども、３階にないというのは。","id":"exchange-013"},{"speaker":"松永委員","kind":"確認","question":"１点だけちょっとお伺いしたいのですけれども、確認でトイレについてなのですが、その他は全部洋式化という話をされておりました。そこで、その割合と誰でもトイレのような設備はあるのか、確認したいと求めました。","respondent":"篠田学校計画担当課長","answer":"基本的には和式に関しまして、必ず学校に最低一つは和式を置くような形で、今回も基本的に一つ設置するような方向で考えているところです。それから、誰でもトイレですけれども、逆に言うとバリアフリーのトイレを設置することを予定しているものです。","id":"exchange-014"},{"speaker":"松永委員","kind":"質問・要望","question":"特別支援教室の前にはなく、１階だけということですか。和式については、フロアごとに全部一つずつつけられるのか、再度質問させてほしいと求めました。","respondent":"篠田学校計画担当課長","answer":"ハンディキャップがある子どもたちに対応することもあるのですけれども、そういうことを想定して１階に設置しているものです。１階に一つ入れるということを考えてありますけれども、今実施設計の段階ですので、まだ最終的な確定ではないです。","id":"exchange-015"},{"speaker":"南委員","kind":"質問","question":"５・６年生から家庭科なのか、それとも３年生でもあるのか、特別教室の配置との関係性についての考え方を伺いたいなと思います。そういう徒競走をするときに、運動会のシーズンですからあれですけれども、１・２年生ぐらいは５０ｍ走を一生懸命走っていいかなと思います。","respondent":"篠田学校計画担当課長、大関教育総合支援センター長","answer":"特別教室の配置の考え方です。場合によっては３階等に上げたほうが使いやすいため、いずれにしても、その辺の動線等も含めまして今後検討させていただければと思います。３階でいいのかなという状況もありますし、学級ではなく、それぞれの学年が使いやすい場所ということで今の形になるような状況です。","id":"exchange-016"}]},{"id":"topic-02","title":"学事制度審議会第１０回～１２回の報告","agenda":"学事制度審議会第１０回～１２回の報告","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今、第１２回目のところで学校選択制についてどういった意見があったのか、もう少し詳しくご説明ほしいと求めました。やはりできるだけ長く、例えば１カ月ぐらいはとったほうがいいのかなと思うのですが、これから１カ月間の延長ができるのか伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"委員から２週間では短いというお話をいただいたのですが、その後できるだけ速やかにホームページ等にはその報告書をアップしていく予定です。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問・要望","question":"子どもと教育を充実させていくというためにも、学校選択制というのは中止したほうがいいと思いますけれども、改めて伺いたいと思います。多くの方に意見を求めていただければと思うのですけれども、説明会の開催をぜひやっていただきたいと思うのですが、いかがか尋ねました。","respondent":"篠田学校計画担当課長","answer":"中間答申に関しての説明会ですけれども、そういった部分を含めまして、できるだけわかりやすいような形で中間答申を作成しているつもりです。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"あわせて、わかりやすく記載するというお話でしたけれども、読んで理解するというのはなかなか難しいところがあると思います。説明会をやったほうがいろいろ質疑もできて理解が深まると思いますので、ぜひ検討してほしいと求めましたが、改めて伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"繰り返しになってしまいますけれども、わかりやすくつくりつつ、またリーフレット等も作成して、皆様方にお配りしたいと考えておりますので、説明会については今のところ開催する考えはございません。","id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、少なくとも要旨でしか出せないのであれば、最低限そこは準備をしていただきたいと思っています。制限するという方向性が出てきているのは事実かどうか、その辺について伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"最初に議事録の公開のタイミングなのですけれども、もともと学事制度審議会に関しても非公開で出していただいてありますので、議事録の公開も要旨で行なわせていただいております。","id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"いろいろなやりとりの中で、そういう制限はしない方向で今までどおりということになっていくということで了解していいわけですか。そういう状況が今あると思うのですけれども、そのあたりの認識というのはどうか尋ねました。","respondent":"篠田学校計画担当課長","answer":"制度自体にそごがあって変えるといった考え方をしているものではございません。そういったことは今申し上げたような形にもつながっているところですので、きちんと対応されているものと考えているものです。","id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっと最後のところがよくわからなかったのでもう一度伺いたいのですけれども、そういうふうな捉え方をしているのか、もう一回お願いします。ですから、２０年やってきた中で、そういう事実があるのではないか。","respondent":"篠田学校計画担当課長","answer":"前回の学事制度審議会では、各ブロックを代表して町会長の４名の方に、今までよりも多い形でご参加をいただいているところです。それから、そういったブロック制によって遠くの学校に通うようなことがないような形での見直し等の考え方が整理されてくるものと認識しております。","id":"exchange-022"},{"speaker":"南委員","kind":"質問","question":"詳しくホームページに載せるから、品川区の目玉としての学校選択制ですから、品川区の教育行政を高めていくのだと思ってやっておられると思うのです。","respondent":"篠田学校計画担当課長","answer":"さまざまな形で区民の方へのアプローチというのはあると思います。パンフレット、リーフレット等によってわかりやすくご説明することで区民の皆様方にはご理解いただけるものというふうに考えているところです。","id":"exchange-023"},{"speaker":"南委員","kind":"意見","question":"私は反対だからやめてもらいたいと思うけれども、やっていくというのであれば、もっと堂々と区民に説明をするべきです。ぜひ説明会をやるべきだということを強調して終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"渡部委員","kind":"質問・要望","question":"さあどうぞで、何の説明会ですかという話になるので、そういう人を惑わすようなことは一切やらないほうがいいです。最終答申が若干の変更となり、何らかの変更が加わることがあるかもしれないというのは、その確認だけ一つとらせてほしいと求めました。","respondent":"篠田学校計画担当課長","answer":"説明会の関係ですけれども、今委員からご指摘があったとおり、審議会の答申を受けるというのは事務局の立場として受けるものです。","id":"exchange-025"},{"speaker":"渡部委員","kind":"確認","question":"確認いたしました。町会の総務部長としても、そういう話は毎回していますので、そこはしっかりと申し伝えします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]},{"id":"topic-03","title":"平成２９年度全国学力・学習状況調査の結果","agenda":"平成２９年度全国学力・学習状況調査の結果","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"やはり過度な競争教育につながるのではないかという懸念があるのですけれども、その点、どうされているのか。そして、この調査が実際どのように活かされていくのかというのがなかなか見えにくいのですけれども、今後の活用について伺いたいと思います。","respondent":"熊谷指導課長","answer":"あえて今年度からは整数で８０％ですとか、７８％のように過度な競争をあおるというようなことはしないということをうたっているところです。算数、数学部会等でこれらを活用して、次の教育要領に活かしていくということを今進めているところです。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問","question":"その中で、その上で全国学力テストをやっていくという意味がよく見えないので、そのところを伺いたいと思います。学び合いの教育によって教育効果があるというところでやっていくことが私はいいと思っているのですけれども、その点の考え方も伺いたいと思います。","respondent":"熊谷指導課長","answer":"６年生、９年生、普段の小テストとは異なる部分であろうかと思います。そういったことも確認することができますし、改善につなげていけるということで、乖離しているものではないと考えます。","id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"それから、５番のところで、東京都も全国もさらにそれよりも下回るこのパーセンテージをどういうふうに評価して見ていいかわからないのです。","respondent":"熊谷指導課長","answer":"それから、決してそうではなくて、学習指導要領に基づいてきちんと適正に示された授業時数で行ったときに１００％とれるであろうという問題なのです。","id":"exchange-029"},{"speaker":"南委員","kind":"質問・要望","question":"算数Ａと算数Ｂがどういうふうに違いがあるのかちょっとよくわからない中での質問なので、算数Ｂが５３％、数学Ｂが５１％。先生方としてつかんで、具体的に指導に活かすということはどういうことなのかなというのがちょっとわからないので教えてほしいと求めました。","respondent":"熊谷指導課長","answer":"８月に返ってきているのですけれども、例えば６年の問題では、１年から５年までの問題が満遍なく出ているのです。中学校の場合は９年間、１週間前の問題ではなくて、十分活かせると考えています。","id":"exchange-030"},{"speaker":"南委員","kind":"質問・要望","question":"秋田県も含めて、どういうふうに理解していいかわからないし、そういう意識を持っていける子どもを育てていくことが大事なのではないかと思います。以上、意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"渡部委員","kind":"質問","question":"ですから、あまり数字がどうこうというのではなくて、今後の品川区の教育にどう活かしていくかだと思うのです。物差しにして何か考えていったりすることがあるのかどうか、そこだけの説明を求めました。","respondent":"熊谷指導課長","answer":"今年度、区の学力調査を導入いたしましたけれども、これはまさに今委員ご指摘のとおり経年で追っていくということを重視したものであります。それからどのように改善したのか、また課題は残ったのか、見取っていきたいと思います。","id":"exchange-032"},{"speaker":"こんの委員","kind":"質問・要望","question":"確認を含めてですけれども、それと同時に、家庭の親御さんがしっかりこの結果を知っていくということも大事なのかなと思います。","respondent":"熊谷指導課長","answer":"各学校には個人面談の際ですとか、また保護者会では個別に説明はしないのですけれども、全体で説明した上で。読んでいますと答えた子どもと学力の相関を見ますと、確かに読みますと答えた子どもの解答率が高いということが言えます。","id":"exchange-033"},{"speaker":"こんの委員","kind":"質問・要望","question":"読書についてですが、朝読、たしか朝１０分の読書時間というのは、今この活動はどうなっているのでしょうか。その何でもいいのは、たしか漫画系も含まれて、図書に触れる朝読という活動をたしかやっていたかと思うのですが、今どのような状況か尋ねました。","respondent":"大関教育総合支援センター長、熊谷指導課長","answer":"ボランティアの協力を得て、読み聞かせの会を月に１回から２回設けている小学校も多くなっております。その他、例えば、とにかく読書習慣が身につくよう子どもたちに対する働きかけを全校で引き続き続けているところです。例えば個人面談等で丁寧に説明していくということもありますし、それから態度表明ということで、そういったもので保護者の方に丁寧に説明をしながら。","id":"exchange-034"},{"speaker":"松永委員","kind":"質問・要望","question":"学校質問紙調査の結果概要についてちょっと伺いたいと思うのですけれども、３番、この差というのをちょっと教えていただきたいというのがあります。４番の「全く行っていない」という回答はあったのか伺いたいと思います。","respondent":"熊谷指導課長","answer":"校長先生が回答しているものですが、どうやって回答しているかと、副校長が確認してという教育課程の管理があります。ですので、小学校でほぼ１００％近くやっていますというふうに答えているわけなのですけれども、まだまだではないかなという校長の見取りであります。","id":"exchange-035"},{"speaker":"高橋（し）委員","kind":"質問","question":"算数の中でも、数学の中でも、そういうものがあると思うのです。そういった点、そういう指導のやり方を、ここはこういうふうにしたほうがいいという指導はどのような形で先生方にしているのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"月１回教科ごとに全教員が所属しております教育会の部会のほうでも今回の結果の分析は進めております。やはりどちらかというと、例えば若手の３年以内の教員が苦手としそうな課題は、研究授業の形で日々指導力を高めているような努力をしている最中です。","id":"exchange-036"},{"speaker":"高橋（し）委員","kind":"質問","question":"区独自でそのようにやられているのでしたら、そういう積み重ねがきっとあると思うので、そういうものをリストアップしていく考えはあるのでしょうか。なければ、つくってほしいと求めました。","respondent":"熊谷指導課長、大関教育総合支援センター長","answer":"子どもたちはもっと伸びるのではないかということを、具体的なところを含めて、その教育要領の中にも示していこうということで動いているところです。年間、各教科部会で協議内容を冊子にいたしまして、全校に配付して参考にするようにしております。その他、教育総合支援センターのほうで集めて、教員が教育総合支援センターで閲覧をできるようになっております。","id":"exchange-037"}]},{"id":"topic-04","title":"平成２８年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"平成２８年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"毎年のように課題になっている原因は何だと考えているのか伺いたいと思います。これは今回新たにそうなったのか、またこれがもし移行された場合、変更される部分というのはどういったものがあるのか伺いたいと思います。","respondent":"横山品川図書館長、廣田子ども家庭支援課長、吉田保育施設調整担当課長","answer":"こちらの能力として、知識や資格があるだけではなくて、かなりの経験を要するという点があります。先ほどのご説明でも若干盛り込ませていただいたのですが、提供会員の募集の取り組みの評価というところを指摘されたところです。管理運営費が上がったところで説明を申し上げたところですが、こちらのほうの委託料等で対応いたしまして、処遇改善に取り組んでいる次第です。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろ昨年改善点として示された部分についてやられているということですので、しっかり改善できるようにしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"南委員","kind":"質問・要望","question":"そして、図書館でも置いていて、こういうところにそういうものを置いておくということの考え方がどうなのかをちょっと改めて伺いたいと思います。","respondent":"廣田子ども家庭支援課長、横山品川図書館長","answer":"３年に一度の定期点検がありまして、工事の金額で差が出るところで、主にひまわり荘の部分と施設全体の管理で差が出るものです。図書館においては地域事業に力を入れておりますので、地域とともにある図書館としてこのような施設のご紹介という形でやらせていただいております。","id":"exchange-040"},{"speaker":"南委員","kind":"確認","question":"臨床心理士についてですけれども、指定管理が福栄会ということなので、当然福栄会のほうからそういう業務に携わる方を派遣するという形になるのだろうと思っているのですけれども、ちょっとそこだけ確認して終わりたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"今現在、福栄会が任用した臨床心理士が来ているのですけれども、非常勤で毎日いないというところで、そのあたりをもう少し手厚くしたらいいというようなご意見をいただいておりますので、福栄会にはそのあたりについて派遣してもらうように申し入れをしています。","id":"exchange-041"},{"speaker":"こんの委員","kind":"確認","question":"南委員の質問と少し重なる点もありますが、確認を含めてお聞きしたいと思います。スーパーバイザーが要するにサポートする側のサポートというふうに今後なっていくのか、この辺のところの説明を求めました。","respondent":"廣田子ども家庭支援課長","answer":"年間１００件近くなってしまうのですけれども、時間の集中ということが多くて、相談内容でお断りするということは現時点では把握をしておりません。福栄会の中のことですので、相談に乗ることはできると認識しております。","id":"exchange-042"},{"speaker":"こんの委員","kind":"質問","question":"なので、ファミリー・サポートの提供会員が利用者の提供してほしいところに行ったときに、いろいろな家庭の状況が見えるではないですか。見てどうすることもできない、その辺というのは、そういったときの何か対応というのは今までされたケースというのはあるのか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"実際に１対１でやることなので、意見、お話を聞くことはできるかと思います。そこでちょっとどんな意見が上がってきているのかというところは区のほうで把握しておりませんので確認しようかと思います。","id":"exchange-043"},{"speaker":"こんの委員","kind":"質問","question":"提供会員と利用者とも人間関係というか対応はどうですかとアドバイザーから聞かれることはあっても。子育て支援センターのほうは、そこに行く前の段階の方々をより早く見つけるという意味では大事かなと思うのですが、その点いかがか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"一歩踏み込んでどんなことがありますかということが聞けるような場面ができないかというところを２カ所ファミリー・サポート・センターの拠点がありますので、どうやったらできるかについては、検討したいと思います。","id":"exchange-044"},{"speaker":"松永委員","kind":"質問","question":"他にはそういったことを受けられているのかということもお伺いいたします。大井図書館に関しては、１年目はトラブルが多いということで、現状普通どおりに営業されているということなのかについても伺いたいと思います。","respondent":"横山品川図書館長","answer":"２年目以降、指定管理者になれていただいたということで、大分落ち着いてきているという状況です。防火訓練、避難訓練につきましても、たまたま会社が全部１階ですので、その計画に基づきまして一定の水準に基づいて各館で動いているものです。","id":"exchange-045"},{"speaker":"松永委員","kind":"意見","question":"その防火訓練というのはどういうものなのかということを聞いたのですが、図書館に関しても各館によって多分独自のマニュアルが必要ではないかと思うのですが、そういうものはあるのかどうかとの意見を述べました。","respondent":"横山品川図書館長","answer":"地域センターのほうで防火のマニュアル等をつくって、消防署にご協力いただいて毎年訓練を行うような状況があります。マニュアルにつきましても、簡易なものから詳細なものまでレベルは違うのですけれども、各館でそろえて運営をしているような状況です。","id":"exchange-046"},{"speaker":"のだて委員","kind":"質問","question":"図書館についても選書などは長年の経験が必要だということですとか、家庭あんしんセンターでは会員の方の負担が重いというようなお話がありました。","respondent":"横山品川図書館長、廣田子ども家庭支援課長","answer":"先ほど申し上げましたように１０年、２０年の経験というようなキャリアを積むこともなかなか難しい状況ということがあります。母子生活支援施設であるひまわり荘を抱えておりますので、トワイライトステイと同時にやっているので、指定管理制度のほうが望ましいと考えています。","id":"exchange-047"}]},{"id":"topic-05","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"本会議の場で待機児ゼロに向けて、平成３０年度４月の待機児ゼロの見通しがつきそうだという話がありまして、その具体的な数字、需要見込みですとか、認可保育園が何園何人分など、また施設についても、それでゼロになるという具体的なところを教えてほしいと求めました。","respondent":"大澤待機児童対策担当課長","answer":"平成３０年４月の申込み予測ですが、０歳から２歳児の人数でご説明します。認証保育所の入園者等が６４１人で、この計算ですと待機児童は２人となりますので、０人の見通しがたちつつあるです。","id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"しかし、２人の待機児童が出る可能性があるということで、そこはゼロにしていってほしいと求めました。その姿勢を伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"今の数字はあくまでも予測ですので、想定外の人数の増加とまた申込者数の偏り等がある可能性もありますので、今現在だけの計画ではなく、他の対応を含めて今後も検討して、平成３０年４月にはゼロを目指していきたいと考えています。","id":"exchange-049"},{"speaker":"南委員","kind":"確認","question":"確認なのですけれども、それを確認したいのと、入所申請数が来年４月にかけて２,９４４人という数字でよろしいでしょうか。数字の確認を先にお願いします。","respondent":"大澤待機児童対策担当課長","answer":"今委員がおっしゃったとおりの数字です。","id":"exchange-050"},{"speaker":"南委員","kind":"質問・要望","question":"来年４月にかけて入所申請数が２,９４４人というのは、減っていると認識していいのか、ちょっとそのあたりを教えてほしいと求めました。","respondent":"大澤待機児童対策担当課長","answer":"最新の申込者数の増加率が４.４％ですので、その４.４％を受けまして平成２９年度の申込者数に４.４％を足した数で出しております。","id":"exchange-051"},{"speaker":"南委員","kind":"確認","question":"ということは、過去は５％で、入所申請が横ばいあるいは若干微減気味というふうに認識しているということなのでしょうか。１,４０４人という数が見込まれるので、２,９４４人というふうに考えているということでいいのかどうか、その辺を改めて確認したいと思っています。","respondent":"大澤待機児童対策担当課長","answer":"平成３０年度につきましては、なくなるであろうということから、今０歳から２歳の人数についてご説明をしています。年齢別の詳細な分析を今している最中ですので、それが出た時点で足りないところがあれば、また新たな対応について検討するです。","id":"exchange-052"},{"speaker":"南委員","kind":"質問・要望","question":"４月時点で認可保育園１６園というところの中には、ちょっと確認したいのと、そういう対応をとっていくということで受けとめていいのですか。この２点です。","respondent":"大澤待機児童対策担当課長","answer":"昨日の話の続きとして、引き続き住民の方とは調整を図って、何とか４月にはご納得いただければというふうに考えております。そして、この他対応ですけれども、もちろん４月に間に合うように何らかの対策を講じてまいります。","id":"exchange-053"},{"speaker":"南委員","kind":"質問・要望","question":"さらなるご努力をお願いしたいのですけれども、そこには、そういうことも覚悟して取り組んでいただきたいということを思っています。その点についての決意、それを伺って終わりにしたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"平成３０年４月にゼロを目指して今後とも努力をしてまいります。","id":"exchange-054"},{"speaker":"南委員","kind":"質問・要望","question":"どのくらいの距離のところにあるのかとか、また何人ぐらいの方がそういう状況に該当されるのかとか、その辺がわかったら教えてほしいと求めました。","respondent":"大澤待機児童対策担当課長","answer":"その方たちには、できれば認可保育園等への編入を進めているということで、近くでは大田区の馬込に１園あります。そのほか、都内に６園ありますので、会社等の都合でそちらのほうが都合がいいという方はそちらに優先的に転園されることもあろうかと思います。","id":"exchange-055"},{"speaker":"南委員","kind":"確認","question":"建物の契約が満期になったことだということなのですけれども、契約の満期を理由にされるというのは、何か特別な事情とかがあるのですか。当初から平成３１年３月で終わりですよと言っていたわけではないのではと思っているので、その辺の確認をしたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"当園は平成１４年の開園ですので、平成３１年では１７年が経過することとなります。近隣に代替地を探したけれども、どうしても見つからなくて、閉園せざるを得なくなったという事情です。","id":"exchange-056"},{"speaker":"南委員","kind":"質問・要望","question":"そういう点で、そういう点でも強調して主張してきているところなので、やはり厳しく受けとめていただきたいなというふうに思っております。区はどういうふうに思っているのですか、そこを伺って終わりにしたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"区として気を配らなければいけないのは、やはり今入っている方がどこにも行き場がなくなることだと思いますので、それについては東京都とともにきちんと転園先を確保できるように事業者のほうにも働きかけていきたいと考えています。","id":"exchange-057"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/203794?Template=document&Id=4924#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":75669,"voices":169}},{"id":"h29-20170926-5","meetingId":"h29-cm09","date":"2017年9月26日","dateIso":"2017-09-26","committee":"総務委員会","time":"午前１０時００分～午後 ２時５０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件整理しています。","topics":[{"id":"topic-01","title":"「議案審査」を行います。 第５９号議案 平成２９年度品川区一般会計補正予算","agenda":"「議案審査」を行います。 第５９号議案 平成２９年度品川区一般会計補正予算","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"今さら伺うのは大変お恥ずかしいのですけれども、改めて、当初予算と補正予算の考え方をもう一度、きちんと伺いたいのです。当初予算と、それに対して、どういうときに、どういう考え方で補正を組んでいくのか。","respondent":"秋山財政課長","answer":"先ほどもご説明させていただきましたけれども、それに対応する必要があったときに、ご議決いただいて執行するという考えです。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１３ページの情報システム運営費追加分についてお伺いします。２０１６年にスタートして、どういったところで、いろいろな分野に広がっていくのかという大もとのところを教えていただきたい。","respondent":"仁平情報推進課長","answer":"この実施時期につきましては、いつからというのは、国から説明されていないところです。今回の旧姓併記の対応ということで、大きくその連携にかかわる部分としましては、こちらの連携の必要性が出てくるということです。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"ちょっと前は３億円という答弁をいただいているのですが、多分、この辺の費用がどんどん膨れ上がっていくと思うのですが、この辺の費用について。区内で漏えいとか個人情報が守られなかった、エラーがあったところがあったらの説明を求めました。","respondent":"仁平情報推進課長","answer":"それと、エラーの件ですけれども、今のところ、情報連携等とマイナンバー関係のシステム、いろいろと改修しましたが、エラーは出てきていません。中には、例えば桁が１つずれてしまったということで、そういう情報は全国的に共有されている状況になっております。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今年の４月に総務省の統計局のサイトがサイバー攻撃に遭って、まだ、その辺も原因究明がしっかりされていないということを私たちは聞いているのです。","respondent":"仁平情報推進課長","answer":"国の行政機関と地方自治体の間で行うシステム自体は、閉塞した世界でやっておりまして、一般の方はそこにアクセスできない。この辺の取り扱いにつきましても、職員研修等を行うなど、職員の教育に努めているところです。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"所管のところで運用ができる部分もあると思うので、補正を出すにあたっては、予算的な基準が何かあるのかどうか。そこのところの説明を求めました。","respondent":"秋山財政課長","answer":"額も考慮はしますけれども、そのときの補正の目的で判断をして、一律に何万円以下だから補正はしないということは考えておりません。","id":"exchange-005"},{"speaker":"須貝委員","kind":"意見","question":"それからあと、地域資源活性化事業補助２,２００万円、根本的には観光地とか観光資源の整備や管理に予算を集中すべきではないかと私は思うのです。ちょっと違和感を覚えるのですが、その辺について、ご見解の説明を求めました。","respondent":"秋山財政課長","answer":"法人に対するということで、全ての法人ということではないのですが、私どもとしては、できるところは先に行っていくという考えです。経常的に今まで行われていたもののＰＲの経費ということで出しているものではないとご理解いただければと思います。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"これからも、私立の保育園でも幼稚園でも、申請をすれば２分の１が補助になるという考え方でいいのでしょうか。その辺、もう一回だけの説明を求めました。","respondent":"秋山財政課長","answer":"今回については障害者・児の施設を対象にした設置費を入れるということですので、障害者の施設についてはほぼ網羅できると考えています。その事業、イベント全体が活性化して、区の観光資源化に資するものという観点で補助をしています。","id":"exchange-007"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"２点お伺いします。決まっている範囲で、わかれば教えてほしいと求めました。","respondent":"安井選挙管理委員会事務局長、仁平情報推進課長","answer":"１８歳に選挙権年齢が下がったので、実際の記載台を６台ほど買って、１６校ぐらいでやったのです。さらに拡充して、多くの学校でやっていこうということで、それ専用の記載台を購入する予定です。ほかの部分もそうなのですけれども、法改正によってシステム改修等が必要になってまいりますと、各自治体で契約しているベンダーに改修を依頼する。","id":"exchange-008"},{"speaker":"石田（し）委員","kind":"質問","question":"それとも、一定のシステムの改修に関しては、もともとの契約の中に、例えばこういう軽微なものに関しては大枠の中に入っているのか。その辺の契約の内容もの説明を求めました。","respondent":"仁平情報推進課長","answer":"パッケージ型の導入で対応できるのであれば、なるべく中身をユーザーに合わせた改造をしない、経費を抑えての導入を考えております。そうなると、最初につくった時点では想定されない部分、法の改正等に対応するのは年間の固定経費に入れていくのは難しくなります。","id":"exchange-009"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"私が時代遅れなのかもしれませんけれども、旧姓を併記しないことによって何か起きるデメリット、何かその事例とか、これによってどう解消できるのか。そこを区民に説明するのに、こういうことが改善されるということを教えてほしいと求めました。","respondent":"仁平情報推進課長","answer":"区もそういう対応をとっておりますけれども、かなり広がってまいりました。うちの会社は対応していないとか、結婚すると口座名義が変更になってくるわけですけれども、旧姓でも対応してくれる銀行が増えてきました。","id":"exchange-010"},{"speaker":"あくつ副委員長","kind":"質問","question":"マイナンバーカードに旧姓を併記するということ。今度は、希望すれば交換してくれるという話になると思うのですが、それはいつぐらいからスタートする予定なのか尋ねました。","respondent":"仁平情報推進課長","answer":"ただ、平成３０年何月からを目指しているというところは、まだ国から示されておりません。それはまだこれからですので、今のところ、確定の時期は示されていないところです。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"この間の経費で８億円余、大事な税金を使って、区民の情報が守られないということにおいて、さらなるシステム改修はやめるべきであります。ほかの所管のところについては賛成をしておりますけれども、この情報システムの運営費、１点で反対をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"それに対して補正が２,２００万円ということで、当初予算と補正の関係はどうなのかということで、冒頭に質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-02","title":"品川区総合戦略の取組状況","agenda":"品川区総合戦略の取組状況","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"２ページ目のところの基本目標２の５のところの項目で、品川区内の企業の付加価値額はどういう意味だか、よくわからない。この額を算定するというあたりは、どのようにされるのかの説明を求めました。","respondent":"柏原企画調整課長","answer":"経済産業省からの特定の調査が定期的にあって、一番下の欄外のところに付加価値額ということで、説明を書かせていただいてあります。例えば人がどれだけ雇われているかとか、給与の関係、品川区の経済力をあらわす１つの重要な統計値であると認識しています。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"これを毎年、国に報告をすると最初、ご説明があったのですけれども、報告をした後は、何か具体的にコメントとかが来るのか。先ほどは平成２９年度、平成３０年度に、今後、活かしていきますということだったのですが、国から何かコメントとかが来るのか尋ねました。","respondent":"柏原企画調整課長","answer":"３ページのところ、国際化への対応をさらに進めつつ…という、ここがこの事業に対して国の交付金をいただいています。現段階では、このことについても、何か国からコメントがあったりとかというところはございません。","id":"exchange-015"},{"speaker":"吉田委員","kind":"意見","question":"それをどういうふうに今後、考えていくのかということ。何か具体的に、こういうふうに力を入れていくというようなことを考えられるのかどうか、お示しくださいとの意見を述べました。","respondent":"柏原企画調整課長","answer":"今の観光客、それから実際の宿泊者数の動きを見ながら、この辺は変更する必要があるのではないかというような捉え方をしております。","id":"exchange-016"},{"speaker":"石田（し）委員","kind":"質問","question":"平成３１年度に向けてのステップアップとして予算を組んでいくのか、現状があって、そこに合わせて来年度予算というのを組んでいくのか。その予算の組み方は、特にどこを基準にしてやられているのか、まず１点、の説明を求めました。","respondent":"柏原企画調整課長","answer":"実際のところは、総合実施計画の事業をこの形でカテゴリー別にまとめたものが、この総合戦略ということになります。総合実施計画は、その平成３０年度に向けて、予算の考え方を持ちながら実施計画をつくっております。","id":"exchange-017"},{"speaker":"石田（し）委員","kind":"質問","question":"例えば、これだけ事業があって、これだけの人が利用してといったら、普通に考えたら、それだけ予算がかかってくるわけではないですか。平成３１年度目標数値を見る限り、予算になっていくと思うのですけれども、その辺はどのように考えているのか尋ねました。","respondent":"柏原企画調整課長","answer":"今ご指摘いただいたように、総合戦略、実施計画も含めてなのですが、大分、チャレンジングな数字だとは思っております。総合実施計画の中での予算の考え方というのを、６年後にはこうなる、想定できる範囲内には動いていると思っているのです。","id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"これはこういう仕組みでいいのですか。学識経験者の方たちが話し合う場、また、取り組んだことの成果だけをただ出せばいいということなのか尋ねました。","respondent":"柏原企画調整課長","answer":"例えば、こういった表示の仕方であるとか、皆様にお示しするときなどに、どういった形がいいのかというのは、検討は必要なのだろうと思ってあります。ですので、この表記の仕方、それからＫＰＩの持ち方というのは、これからの検討といいますか、研究は必要なのだと考えています。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問","question":"今のところ、平成３１年度の目標として定めたところまでは、今のＫＰＩだけでやっていくということなのか。とりあえず今回はこの数値目標だけを点検しながら、平成３１年度までやっていくということなのか、その辺だけの説明を求めました。","respondent":"柏原企画調整課長","answer":"違うＫＰＩをプラスするだとか、そういった可能性、考え方は当然出てくると思います。もう少し事業進捗を見ながら、その辺は改めて検討しながらと思います。","id":"exchange-020"},{"speaker":"吉田委員","kind":"質問・要望","question":"３年たっていく中で、ぜひ検討してほしいと求めましたので、そういうふうによろしくお願いします。これは要望でとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"平成２８年度、１１事業というところで、こういう事業をされたということなのでしょうか。急激に数が増えているのですけれども、全国自治体との連携事業数というところでとっていると思うのですが、そこの認識を教えていただきたい。","respondent":"柏原企画調整課長","answer":"そのほかには、２３区の区長会でやっている東北の六魂祭というプロジェクトがありましたけれども、それについてのＰＲ活動、参画というのがあります。","id":"exchange-022"},{"speaker":"あくつ副委員長","kind":"質問","question":"もともと国が言っている総合戦略の目的に沿うべきというところもあるだろうとも思うのです。最後にそこだけ、お考えをお聞きしたいと思います。","respondent":"柏原企画調整課長","answer":"地方創生であったりとか、その主な自治体といろいろなところでの事業連携であったりとか関係性を強化していくというのは今後必要だと考えています。こういったところで、どんなことができるかも考えながら進めていきたいと思ってあります。","id":"exchange-023"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"３ページの基本目標、品川区内で宿泊施設というのは限られると思うのです。施設が限られている中で、どういうふうに目標数値を上げていくのかどうか、お聞かせほしいと求めました。","respondent":"柏原企画調整課長","answer":"キャパシティーの考え方、そういったところも見ながら、この値というのは考えていくべきだと思ってあります。ですので、もう既に目標値は超えているのですけれども、単純に増やせばいいというところではないというところで検討をしています。","id":"exchange-024"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"最後の３ページの一番下、もう平成２８年度、おそらく２０万人に到達するであろうと考えているのです。今現在、わかっている時点でどれぐらいを目標にしているのかを教えてほしいと求めました。","respondent":"柏原企画調整課長","answer":"このバスターミナルの部分につきましては、正直に申し上げて、今ご指摘いただいたとおり、想定以上の動きになっている部分があります。これも今後の数字の動向を見ながら、平成２９年度の動向が多分中心になると思いますけれども、数値は決めていきたいと思ってあります。","id":"exchange-025"}]},{"id":"topic-03","title":"新公会計制度導入に伴う予算書の新様式","agenda":"新公会計制度導入に伴う予算書の新様式","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"最初の資料、原則１課１目に組み替えるということで、この辺はわかりやすくなると思うのですが、原則とありますけれども、例外はどんなものがあるのか尋ねました。","respondent":"秋山財政課長","answer":"健康課から、同じ事業が３カ所にばらばらになって出てくるということもありますので、複数課１目という形でやろうと今のところ考えています。小学校という横軸で事業を行っていますので、その辺については、複数課１目的な形になると考えています。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問","question":"それと、複数課１目というと、現行の表記の仕方と変わるのか変わらないのか。その辺もの説明を求めました。","respondent":"秋山財政課長","answer":"これは新しく組み替えている最中ですので、これ以外がないのかと言われると断定はできないのですけれども、あまり増やしたくないとは思っています。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問","question":"複数課１目だった場合の表記についてはいかがか尋ねました。","respondent":"秋山財政課長","answer":"基本的には、新しい方式で表記はします。各事業の後ろに所管課の名称が入るということは変わらず、見た目は１課１目と同じ形になろうかと思います。","id":"exchange-028"}]},{"id":"topic-04","title":"全国シティプロモーションサミット","agenda":"全国シティプロモーションサミット","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"プログラムが示されたということですが、時間などはまだ決まっていないのかということと、それから、今後のこれらについての広報の仕方、それから、２日目の先進事例講演、セミナーの内容というのはまだ決まっていないのか、その辺の説明を求めました。","respondent":"木村報道・プロモーション担当課長","answer":"キーワードで全国シティプロモーションサミット２０１７、それをキーワードに検索をしていただきまして、一番上に出てまいります。それを機に、実際にこの時間帯、このセミナーという形でご案内ができると考えておりますので、そちらでご案内をしてまいりたいと考えております。","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問・要望","question":"もう９月末ですので、求めている人に情報が届きにくいと思いますので、その辺のスケジュールをもう少し詳しく教えていただけますか。もう９月末の段階ですので、教えてほしいと求めました。","respondent":"木村報道・プロモーション担当課長","answer":"実際に広報につきましては、その広報が出る時点では明らかになっている形の想定です。今、それから、１２時１５分から１３時までの時間を各区長のパネルディスカッションという形で設定をさせていただいているところです。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問","question":"それから、もう一つ、連携企業等のＰＲブース、それから、それぞれの自治体からも募ると伺っていますが、今の申し込み状況などがわかればの説明を求めました。","respondent":"木村報道・プロモーション担当課長","answer":"現在、ブースに関しましては、企業、それから参加自治体でもう固まっているような状態でございまして、これから、どこをどこに配置という具体的な話に入ってまいりたいと考えています。","id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"きっと品川区でこういうブースが持てるということについては、結構、期待していらっしゃると考えています。都外の自治体の人たちにも来ていただくような仕掛けをしてほしいと求めましたので、これは要望にとどめしますが、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"１カ月前になったということで、幾つか伺いたいのですけれども、どれぐらい申し込みがあるのかどうか。もう一点、区内見学ですけれども、ホームページで拝見すると有料になっていたのですが、この全５回の中で、有料でやったところはあるのか尋ねました。","respondent":"木村報道・プロモーション担当課長","answer":"それから、特別区の全国連携プロジェクトにつきましても、具体的な展開事例という形で、全国の皆様にご紹介をするような考えとなっております。多岐にわたりますので、この場でご説明は割愛しますけれども、いろいろと企画しています。","id":"exchange-033"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"せっかく遠くから来ていただくわけですから。ここをお伺いしたいと思います。","respondent":"木村報道・プロモーション担当課長","answer":"広報の予定についてですけれども、これから実際に、私どもから直接ご案内をするという形。それから、前回の坂井市に参加された自治体であるとか近隣の自治体を対象に、スピーディーに展開をしてまいりたいと考えております。","id":"exchange-034"},{"speaker":"石田（し）委員","kind":"質問","question":"今のに関連してなのですが、そもそもシティプロモーションサミットの企画をいつまでに決めるという計画があったのかと、その案内もいつごろまでに出すという、もともとどういうスケジュールがあったのかの説明を求めました。","respondent":"木村報道・プロモーション担当課長","answer":"もともとはお盆明けごろに周知、ご案内をスタートという形で考えておりました。ただ、実際に講座の中身の調整の部分で、なかなか調整がつかなかった部分もございまして、今になってしまったです。","id":"exchange-035"},{"speaker":"石田（し）委員","kind":"質問","question":"１カ月を切っている中で、１カ月先の日程は、固まってしまうではないですか。どうやって、１カ月半の遅れを取り戻して、なかなか厳しいのではないかと思うのです。","respondent":"木村報道・プロモーション担当課長","answer":"直接ご案内するのですけれども、ご案内、プッシュをしていくという形の部分。実際に２３区内でも、そういうつながりがありますので、そういう部分でお願いをしてまいりたいと考えているところであります。","id":"exchange-036"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"予定も決まっているかもしれないではないですか。いろいろと工夫をしていただいて、１つでも多くの自治体の方たちに参加してもらえるような工夫をぜひやっていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-05","title":"庁舎型勤務職員の勤務時間の弾力化の実施","agenda":"庁舎型勤務職員の勤務時間の弾力化の実施","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"目的のところに勤務時間内に恒常的な業務が発生している職場等とあるのですが、窓口の延長はわかるのですが、あと地域センターとかにおいて、恒常的に超勤になってしまう職場は、どういった職場で、どんな業務があるのか、もうちょっと丁寧にの説明を求めました。","respondent":"黒田人事課長","answer":"先ほどご説明しましたとおり、地域センター等の地域の会議も基本的には６時とか７時から開始で、９時というようなところもあります。朝、遅目に出てくることによりまして、１日の勤務時間をできる限り正規の勤務時間に近づけたいと考えているものです。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問","question":"実情に合った勤務体系を設定していくところにおいては、職場の意見で、それぞれ職場に合った組み立てを職場の皆様の総意で組み立てていくのかどうか。そこのところの説明を求めました。","respondent":"黒田人事課長","answer":"シフトの考え方の設定ですが、わかりやすいようにということで、遅出は１時間ということに設定するという形で計画しております。そういった意味では、各職場の実情を勘案して、制度として運用するものですので、少しわかりやすい形に整理するものです。","id":"exchange-039"},{"speaker":"飯沼委員","kind":"意見","question":"そこを心配しているのが１点。多分、組合と協議がされていると思うのですが、組合から出されている意見があったら聞かせてくださいとの意見を述べました。","respondent":"黒田人事課長","answer":"庁内に実施の周知をしておりますが、少数職場ではシフトを組まずに、超過勤務で会議に対応するというようなことも今後もあろうかと思います。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１つの勤務形態で済むのだったら人員は十分だと思うけれども、後ろに引っ張ってきたりしたら、必ずどこかが手薄になるのです。だから、ぜひ、その点においては、必要なところには職員の配置もしていくといった考えを持っていただきたいのですが、いかがか尋ねました。","respondent":"黒田人事課長","answer":"１０月からは試行という形で、年度末は繁忙期ですので、なかなか繁忙期にシフトを組むと支障が出るというところもあります。シフトの時間を変更したら、労働時間を縮減して、労働時間の適正化を図っていくところにまず取り組んでいきたいと思っているところです。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１０月試行ということなので、十分、具体的な職場の意見を聞いていただきたい。その姿勢がないと、職員の健康を守るというところにはならないと私は思うのですが、いかがか尋ねました。","respondent":"黒田人事課長","answer":"区民サービスや要望への対応を所管しているところでは、こういった勤務時間の弾力化も使いつつ、さまざまな工夫を図って長時間労働を縮減していくというところに取り組んでまいりたいと考えてところです。","id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問・要望","question":"しっかり仕事をきちんと認めて、足りないところは人手を配置するという考えをぜひ持ってほしいと求めました。最後ですが、いかがか尋ねました。","respondent":"黒田人事課長","answer":"平成２９年度は定数の中で３人増ということで、超過勤務時間が月間８０時間を超えるような場合については、健康管理も適切に行っております。","id":"exchange-043"},{"speaker":"須貝委員","kind":"質問","question":"ですから、そういう時間帯もある意味で増えるのではないかという期待も見えますので、私はいいのではないかと思います。その中で、また問題点があれば改善して、また考えて、運用していけばいいのではないかと考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"石田（し）委員","kind":"質問","question":"弾力化を実施するということで、目的のところで、恒常的な業務が発生する職場等においてと書いてある。目的を見る限り、それはできないと感じてしまったのですが、その辺はどうなっているのかの説明を求めました。","respondent":"黒田人事課長","answer":"個人の都合を広く認めると、都でフレックスタイムの試行はしたみたいなのですが、なかなか服務管理が難しいという課題もあります。この弾力化の中では、効果をどう見るかというところをしっかりこれから見ていくところです。","id":"exchange-045"},{"speaker":"石田（し）委員","kind":"提案","question":"ただ単に、そういった環境の人たちが働きやすい環境を行政にはしっかりとつくっていただきたいという意味で、時差出勤を提案しているわけです。これは要望で終わりますけれども、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"}]},{"id":"topic-06","title":"南大井文化センター他１施設外壁改修その他工事請負契約","agenda":"南大井文化センター他１施設外壁改修その他工事請負契約","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"工事内容を見たら、壁の塗り替えが入っていないのですが、外壁と床だけで、壁はそのままなのでしょうか。ちょっと気になったのでの説明を求めました。","respondent":"小林施設整備課長","answer":"１点目、築４３年です。防音は、今回、要求はなかったものですから、床のフローリングの張り替えだけです。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問","question":"築４３年ということですが、建物はしっかりしていて、耐震は大丈夫ということです。防音をやってほしいという声を私は聞いたのと、まあまあきれいだから、そのままでいいということなのか尋ねました。","respondent":"小林施設整備課長","answer":"外壁の改修というのが、いわゆる外壁の塗り替えです。耐震は済んでおりますので、構造的には大丈夫です。","id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問・要望","question":"なぜ、セットになってきれいにならないのかが、私は不思議というか、壁だけ塗り替えないで残していくのはなぜかという疑問なのです。よほどの理由がない限り、セットで一緒にやっていただきたいという思いで質問をしております。","respondent":"小林施設整備課長","answer":"今回のフローリングの床の改修というのは、全部で３カ所程度やりますけれども、一つ一つ、その部屋の使用をとめて工事をします。利用を再開したいという一番の目的もありましたので、今回、そういう工事内容になっているということです。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問","question":"最後になりますけれども、館の判断もそうだと思いますけれども、所管のところにおいても、壁は今回、塗り直さなくてもいいのではないかという判断のもとに計画が立てられたという理解でよろしいのか尋ねました。","respondent":"小林施設整備課長","answer":"そのとおりです。","id":"exchange-050"},{"speaker":"石田（し）委員","kind":"意見","question":"差が出てしまって、飯沼委員が言ったみたいに逆に目立ってしまって、もったいないと思うのです。その時々に本当に必要なものなのかどうかという判断も、今後、１つの判断基準として持ってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"吉田委員","kind":"意見","question":"今の壁については、まだ、そこまで至っていないという判断をされたということですが、一方で、建具については改修工事が３１カ所ということなのです。建具の３１カ所というのは、事例を挙げていただけるとイメージしやすいのですがとの意見を述べました。","respondent":"小林施設整備課長","answer":"こちらは、外壁に面しているアルミサッシなのですけれども、開閉にちょっと支障があるところが３１カ所ありましたので、そちらについては取り替えをする予定で、外壁と一緒に工事をするのがメリットが大きいものですから、今回入っているところです。","id":"exchange-052"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういう柔軟な判断というのは、私としても、ぜひ今後、求めていきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"}]},{"id":"topic-07","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"２３区における採用実績例だけ見ていたのですが、もし、何か具体的に、こういう採用をした結果、こういうような成果が上げられたというような事例がわかれば、１つでも２つでも、教えていただけますか。","respondent":"黒田人事課長","answer":"報道等でも取り上げられて、広告代理店での知見を活かして、いろいろな広報戦略に取り組んでいると伺っております。それが直接、こういった方を採用することで報道等に取り上げられる側面はあると感じてあります。","id":"exchange-054"},{"speaker":"吉田委員","kind":"質問・要望","question":"これはぜひ、このように進めてほしいと求めました。その辺だけの説明を求めました。","respondent":"黒田人事課長","answer":"都の実施状況を伺ったところでは、比較的、パソコンで簡単にできる業務だけに限ったものだと。この辺は、技術的に難しい面もありますし、職員１人が行う業務の成果も求められると思いますので、今後も研究が必要だと思っているところです。","id":"exchange-055"},{"speaker":"吉田委員","kind":"質問・要望","question":"４条の任期付職員のところでは、結果的にどうなのかとか、これからも丁寧にやってほしいと求めました。これは要望にとどめますが、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"今は例えば安定を求めている方、そういう人気が担保できるかといったら、僕は微妙だと思うのです。積極的にこういうことに関しても検討を進めていってほしいと求めましたけれども、改めて、その辺についてもお考えの説明を求めました。","respondent":"黒田人事課長","answer":"それにつきましては、内容によっては、いろいろ対応の仕方があると考えていますので、課題解決のために制度の活用ができればと考えています。技術的に対応できるかという部分に加えて、今後、研究してまいりたいと考えています。","id":"exchange-057"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"１つの企業の方のノウハウをと言いますが、電通のノウハウで物事が進んでいっているわけであって、それは一緒ではないですか。これは要望で終わりますけれども、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問・要望","question":"３のところに採用実績例があるのですが、品川区の場合は、このお２人だけということなのでしょうか。そこが大もとの基本であると思うのですが、まず、そこのところはいかがか尋ねました。","respondent":"黒田人事課長","answer":"どういった形で課題を解決していくかという中の、これもツールと申しましょうか、手法の１つではないかと考えています。さまざまな課題を解決するためにどうやった手法を活用するかという視点で、さまざまな工夫を図ることが必要ではないかと考えているものです。","id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これは要望ですけれども、規制緩和だからといって、短期間の職員を雇用して、首を切るようなことはあまりしていただきたくない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"あくつ副委員長","kind":"提案","question":"ＣＩＯ補佐官という、首長の補佐官みたいなものを杉並区は導入しているということで、提案をさせていただいたこともあります。法制度があるのですから、選択肢に入れてほしいと思うのですけれども、いかがか尋ねました。","respondent":"黒田人事課長","answer":"１人の弁護士を雇用することがいいのか、同じ分野でも、さまざまな切り口があろうと思ってあります。例えば、こういった任期付職員の採用ということも検討したほうが課題解決の手段として有効になるかということも含めて、そういった観点で。","id":"exchange-061"},{"speaker":"須貝委員","kind":"意見","question":"その事業に協力してもらう、一緒にやっていくというのも、さまざまな手法があると思います。取り入れるのかどうか、場面で適切な判断をして、採用する云々を考えていけばいいのではないかと私は思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/762881?Template=document&Id=2088#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":67777,"voices":165}},{"id":"h29-20170927-14","meetingId":"h29-cm09","date":"2017年9月27日","dateIso":"2017-09-27","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 ０時２４分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件整理しています。","topics":[{"id":"topic-01","title":"平成２９年請願第９号、羽田空港機能強化による新低空飛行ルート","agenda":"平成２９年請願第９号、羽田空港機能強化による新低空飛行ルート","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"しっかり出させるべきではないかと思うのですけれど、それは可能ということですか、というのが２点目。あるいは２０１９年１２月３１日までやるのかなと思っていたのですけれど、そこら辺はどうなのか、お伺いします。","respondent":"中村都市計画課長","answer":"ただ、いずれにしても騒音に対する対応はしっかりしていただきたいと考えております。一般的に考えるには、国のほうへ情報を提供してくださいと強く申し入れをしておりますけれども、いまだに示されていないです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"機種とか、天候とか、今は１本の線しか引いていませんが、これは十分に幅があるものだというふうに捉えたほうがいいのかどうか、伺いたいです。平成２９年の春ごろから帯が出ていまして、平成３０年の頭をちょっと超すぐらいまであるのですけれども、伺いたいと思います。","respondent":"中村都市計画課長","answer":"そして現在２７施設につきまして、国のほうで防音対応をする予定ということで、さらにその内容について詰めているところです。区としても、具体的に対応する場所については早急に示すよう、お願いしています。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"後ろの気流の問題なのでしょうか、次の飛行機は全く同じところでなく、この直線下の人たちだけではない影響があるというところを確認したので。","respondent":"中村都市計画課長","answer":"法律上は対応の必要がないというところで、国のほうでは法の弾力的な運用の中で対応するというふうに言っているところです。調査したところが本当に飛行経路の中で影響があるところなのかどうか、まだ決定することができないということで、公表できないです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺ったのは区内のどこの施設で、何日から何日にかけて行ったのかということを伺ったので、しっかりとお答えほしいと求めました。いかがか尋ねました。","respondent":"中村都市計画課長","answer":"飛行経路が案という段階では、実際に調査はしたけれども、対応しないというところも発生する場合もあり得るということで、現在まだ公表できないです。いずれにしましてもこの案というものが決定しないと、なかなか難しいのかなというのは、区としても受けとめているところです。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"伺います。どう見ても世界でも異常な計画なのですけれど、やはりやめるべきだと思うのですけれど、そのようにお感じにならないか尋ねました。","respondent":"中村都市計画課長","answer":"やはり墜落したり、落下物が起きたときの被害に対する対応もしっかりやっていかなければいけないという前提で、飛行するです。ですので、区といたしましては事後の対応も大切ですけれども、この案を提案していただきたいというふうに考えているところです。","id":"exchange-005"},{"speaker":"安藤委員","kind":"確認","question":"午前８時前、右のエンジンから火のようなものが出たのを後ろにいた全日空機が確認したため、離陸を中止したということもあります。ですから、これまで海上ルートでやってきたわけですから、もう一度お伺いしたいと思います。","respondent":"中村都市計画課長","answer":"いずれにしましても未然に防げているところが多いというのは、やはり日ごろの取り組みの成果だというふうには考えております。あらゆる事態に対する未然防止に生かしてもらうという、ここら辺は厳重に国に実施していただくよう、求めていきたいと考えております。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後にお伺いしたいのは、丁寧な説明を求めていくのだとこれまでも品川区はおっしゃっていましたが、お伺いしたいと思います。","respondent":"中村都市計画課長","answer":"現在、事故のほうは原因究明中ということで、それに対する対応をしっかり、二度と起こさないような措置、対応をしっかり構築していただくように、区として願っておりますし、またそれを求めてまいります。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"この資料に沿ってお伺いしたのですが、大阪市のような事例は防げるのかということをお伺いしたので、ご答弁お願いします。","respondent":"中村都市計画課長","answer":"さまざまな角度から、未然防止策を徹底していただくという意味で、このチャネルを通じた未然防止策を徹底するということだと考えます。区としても、これは同じ考えです。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"全然答えになっていないので、やめられないのですが。落下物が車を直撃してしまった大阪市のような事例を防げると考えるのですか、というふうに聞いているので、ぜひお答えほしいと求めました。","respondent":"中村都市計画課長","answer":"今回のこの事例につきましては、原因が究明されれば、その未然防止策が施されるというふうに考えております。区のほうでは判断できませんけれども、しっかりと起こらないようにしていただくよう、国に求めていくしかないと考えています。","id":"exchange-009"},{"speaker":"筒井委員","kind":"質問・要望","question":"航路ですからこれから何回も通るということになるのですけれども、そうした落下物の事故の可能性は非常に高まると考えられます。も国土交通省は本当に飛行する気なのですかということを、品川区としても国土交通省に確認していただきたいのですけれども、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"区としてもしっかり対応していただくようお願いをするという過程の中で、国際空港の機能強化に取り組んでいくというところで、進めていくというような考えを聞いているところです。","id":"exchange-010"},{"speaker":"筒井委員","kind":"質問・要望","question":"区としても本当にこのままでいいのかということを、頻繁に確認していったほうがいいと思うのです。国土交通省の意思確認、ぜひとも意向を確認していっていただきたいのですけれども、その点については区としてはどのようにお考えか尋ねました。","respondent":"中村都市計画課長","answer":"区といたしましても、区民の皆様からいただいた声ですとか、あるいは区として必要な情報提供、こういったものを求めていく中で、国のほうではその辺の声をしっかり受けとめて、必要な措置を全力で講じていくというところで、回答してもらっているところです。","id":"exchange-011"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひとも区としてもそうしたことを受けとめて、国土交通省に撤回の余地はないのかということを、確認していっていただきたいと考えております。それと、２７施設は大井町より東側のものなのか、それとも品川区全域なのかということを確認したいと思います。","respondent":"中村都市計画課長","answer":"大井町から東側です。福祉施設、高齢者施設、こういったところです。","id":"exchange-012"},{"speaker":"筒井委員","kind":"質問・要望","question":"最も騒音被害が予想される品川区ですから、住宅の防音工事、対策をやっていただきたいと考えております。ぜひとも国土交通省に対して、そのように要請していただきたいと考えておりますけれども、区としてはどのようにお考えか尋ねました。","respondent":"中村都市計画課長","answer":"今、影響がある経路の全建物についてやっていただきたいというのは、国のほうにかねてから申し入れていたところです。ただ住宅といったところは、引き続き最大限の対応がなされるように、国に求めていきたいと考えております。","id":"exchange-013"},{"speaker":"渡部委員","kind":"質問・要望","question":"この請願第９号は、確認のためお伺いしたいのですけれど、とりわけ昨年の意見書には「教室型を含む多様な説明会」ということで求めておりまして。","respondent":"中村都市計画課長","answer":"これは、区もこの説明会、第１フェーズを国が行うと言っていた当時から、教室型説明会を求めているところです。これについては引き続き、求めてまいります。","id":"exchange-014"},{"speaker":"渡部委員","kind":"質問・要望","question":"多様な形での説明会を求めていくということで、今後もそれは続けていくということで、よろしいという認識なのか。今一度そこだけの説明を求めました。","respondent":"中村都市計画課長","answer":"このオープンハウス型だけでなく、教室型説明会も常に、これからも継続して求めてまいります。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この請願でも教室型説明会というのを求められているわけですけれども、それでもやはり今回示されている第４フェーズは、オープンハウス型説明会と。伺いたいと思います。","respondent":"中村都市計画課長","answer":"現に今、大阪市で起きた事故に対しまして、当然不安の払拭にはならないと、逆に不安が大きくなると考えております。区としてもこの事故だけでなく、いかなる事象の事故についても起きないよう、国に強く引き続き求めてまいります。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"万が一あったらどうですかでなく、今、ゼロなのですから、このままゼロで行っていただかないと困るのです。それでぜひ、やはり反対表明を一緒にしていきたいと思うのですけれど、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"直接部品が落下して、民間の車に落ちるというようなことにつきましては、特に重要なことだと認識しております。区としてはこういった取り組みをずっと継続していっていただかなければいけないので、その点について強く申し入れをしていきたいと考えております。","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"求めても、求め続けていることが実現されない中で、住民も本当に強く求めているのに一向に実現されないというところでは。これを実現してくださいということなので、実現させていくめどというのは、見通しというのはあるのか尋ねました。","respondent":"中村都市計画課長","answer":"最善な周知の方法はどういったものかという検討がなされた中で、広く皆様にお知らせすることができるという、そんな中で決定した説明会です。区としましても、オープンハウス型説明会をやってはいけないということではなくて、さまざまな説明の方法があっていいと考えております。","id":"exchange-018"},{"speaker":"筒井委員","kind":"質問・要望","question":"教室型を含む多様な手法での説明をしていただくよう求めましたので、区としても要望していっていただきたいと考えております。土日、休日の開催をぜひとも行っていただきたいと考えておりますが、区としてはどのようにお考えか尋ねました。","respondent":"中村都市計画課長","answer":"したがいまして、これが最後ということではなく、この後も継続して説明していただくことになると考えております。１９時までということで、今回は平日ですが、こういった曜日の設定についても国にお願いしてまいりたいと考えております。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"今回、第４フェーズで、最終直線部分の飛行高度を約２０メートル引き上げといった、新しい、比較的重要な情報が出てきていますので、ぜひとも１１月２９日だけと言わず、もう１日程度、土日、休日開催をぜひとも国土交通省にお願いしていただければと思うのですけれど。","respondent":"中村都市計画課長","answer":"１日でも多い開催を、国のほうへ求めてまいります。","id":"exchange-020"},{"speaker":"塚本委員","kind":"質問・要望","question":"品川区の各地域での「教室型」説明会開催に関する請願ということで、きめ細かく教室型説明会を開くようということでの請願です。一点確認させていただきたいのですけれども、どういう考えのもとに国交省に対して教室型説明会を求めているのか、確認したいと求めました。","respondent":"中村都市計画課長","answer":"国のほうで行っているオープンハウス型の説明会、一日でも多い説明会を、そして教室型説明会につきましても開催していただきたい。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから国に情報提供や対策を施すよう求めていくのだという話ですけれども、その対策を求めていくというのでなく、区のやるべきことではないですか。現状は姿勢として私は間違っていると思うのですが、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"しっかりと説明をする義務が国にあると思いますし、また今回こういった１１月に説明会も行われますので、国が区民あるいは国民に対して説明をするということについて。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"求め続けてもそうした対策が出ない、もともとあり得ないわけですから出ないと思うのですけれど、飛行機が飛んだ後でも求め続けるということですか。それは中止を求めないということになると思うのですけれど、飛んだ後でも求め続ける、そういうお答えか尋ねました。","respondent":"中村都市計画課長","answer":"今、国のほうではあくまで案ということで、まだ決定ではないです。仮にという話でございましたら、やはり不安の払拭あるいは必要な情報提供、こういったものは常に求めていく必要があると考えております。","id":"exchange-023"},{"speaker":"安藤委員","kind":"提案","question":"Ｄ滑走路が供用直前の２００９年９月には、突然国が深夜早朝の飛行を提案してきて、事実の証明だと思うのです。自治体の長が反対すれば、計画はとめられるという認識はお持ちかどうか、伺いたいと思いますとの意見を述べました。","respondent":"中村都市計画課長","answer":"もう設置されております滑走路を利用して、便数を増やす運用ができるかという検討の中で、国としてはさまざまな検討をしたという説明です。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"これは重大な問題ですから質問しているのですけれど、変な言葉で言うと、大田区と品川区はプツンとなったわけです。だから今の答弁は、全く私は今回の計画に反対しない理由にならないと思いますけど、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"今現在４つの滑走路があると、こういった条件の中での検討の結果だですので、国がこういった検討をしましたという資料も示されておりますけれども。","id":"exchange-025"},{"speaker":"安藤委員","kind":"提案","question":"ですから、国はさまざまなリスクがある中で提案してきているのだと、経済成長とか機能強化に取り組むために提案しているのだということで。お伺いしたいのは、濱野区長はどうなのですかということを、私はお伺いしたいと思いますとの意見を述べました。","respondent":"中村都市計画課長","answer":"それを一番最初に考えるべきだと考えております。区としても必要な情報を、引き続き求めてまいりたいと考えております。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"国に求めているのはわかりますけれど、国の責任ですから、しかし品川区としてできることをやっているのですかということですよね。","respondent":"中村都市計画課長","answer":"現段階においては、国からの説明がまだ十分具体的なものとなっていないというふうに、区としては考えております。そういった意味からいたしまして、オープンハウス型の説明会とともに教室型の説明会を、今まで求めてきたところです。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"国の情報がまだ不十分だから、出せる情報もないということですか。ですから今出ている情報を使って、広報を、この問題を知らしめてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員長","kind":"質問・要望","question":"皆さんからのご意見は終わりということなので、委員長の私から１点だけ確認させていただきたいのですけれど、よろしいか尋ねました。","respondent":"中村都市計画課長","answer":"今回のオープンハウス型の説明会に対しまして、その中で国交省としても品川区はやはり影響が大きい自治体であるということは認識しているという中で。今回１１月は１回の開催ですけれども、よい方法がないかどうか、今検討しているといった説明はございました。","id":"exchange-029"},{"speaker":"渡部委員","kind":"質問・要望","question":"先ほども確認させていただきました教室型説明会を求めて、区もずっと求め続けているということで、これは私どもの考え方とは異なります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"若林委員","kind":"質問・要望","question":"多様な手法、具体的な説明を引き続き尽くしてもらいたいというふうに、主張をまずさせてほしいと求めました。したがいまして本請願については、意見書を提出した立場から、不採択でいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"議会としましても区が求め続けているということもありますので、国の態度を改めていただくためにも、採択をすべきだと思います。それは相手が決めることですから、議会としてどういう要請をしていくかということと思いますので、私は矛盾はしないのかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"大倉委員","kind":"質問・要望","question":"説明をきめ細かくしていただきたい、できるだけ多い日数で開催していただきたいというふうに国のほうに求めているというご説明もいただきましたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問・要望","question":"採択、賛成です。教室型を含む説明会を開くよう求める意見書を採択して、ぜひとも教室型説明会を開いていただきたいという考えのもと、採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"}]},{"id":"topic-02","title":"金沢市児童相談所の視察","agenda":"金沢市児童相談所の視察","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"職員も５０名ほど必要になってくるとおっしゃっていたので、こうした児童福祉司や児童心理司という方がどれぐらい必要になってくるのかということ。","respondent":"高山児童相談所移管担当課長","answer":"虐待の件数なども加算要素ということになってまいりますので、今申し上げたのが最低基準になってくるかと思います。そして３点目、子ども家庭支援センターの機能を担うところに心理職を配置するほか、教育の意味も含めまして配置しています。","id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問","question":"一時保護所というのも設置していくという考えだと思うのですけれど、どちらも区の職員で運営されるものと考えているのかということ。児童福祉司や児童心理司の配置の基準は、一時保護所の方にもあるのかどうか、伺いたいと思います。","respondent":"高山児童相談所移管担当課長","answer":"職員の配置の考え方ですけれども、児童相談所に附帯する機能というふうになっておりまして、切り離すことができないという法令上の解釈です。","id":"exchange-036"},{"speaker":"石田（ち）委員","kind":"質問","question":"現在の品川区の虐待とか相談の件数というのは、どのぐらいになっているのか。一時保護が必要になった品川の子というのはどこに行くのか、伺いたいと思います。","respondent":"高山児童相談所移管担当課長","answer":"２点目の北品川は、委員ご案内のとおり相談機能しか持ち合わせておりません。前回の事務事業概要の中で少し説明させていただきましたが、特別区内には４つの一時保護所がございまして、保護をするという形になります。","id":"exchange-037"},{"speaker":"横山委員","kind":"質問","question":"金沢市でどのようなところが参考になったのか、今どのように考えていらっしゃるのかということをお聞きしたいと思います。もう１点、今、現時点でどのように捉えているかというところをお願いいたします。","respondent":"高山児童相談所移管担当課長","answer":"放課後対策など先進的な取り組みをしているということで、品川区の強みであり、特性であると考えております。お話伺ったことを精査しながら、品川区に取り込めるものはできるだけ多く、取り込んでいきたいと考えております。","id":"exchange-038"},{"speaker":"横山委員","kind":"質問・要望","question":"今、次の質問と絡めてお答えいただければと思うのですが、品川区はどのように考えていらっしゃるのかというところをお聞かせほしいと求めました。区はこちらの金沢市の視察を行って、どのように感じられたのか、ハード面の部分教えてほしいと求めました。","respondent":"高山児童相談所移管担当課長","answer":"２点目としまして、子どもと家庭への支援は一番生活が営まれている、果敢に取り組むことができるのではないかと考えております。その上で、なおのこと事前の調査を綿密に行いまして、盛り込めるものについては当初の段階から進めていきたいと考えております。","id":"exchange-039"},{"speaker":"横山委員","kind":"質問・要望","question":"これは要望だけでと思っているのですが、内装面を重視していただいて、これからご検討を進めていただきたいというところをお願いできればと思います。","respondent":"高山児童相談所移管担当課長","answer":"少しご説明しています児童福祉司、そして児童心理司という、これまで特別区が持ち合わせていない特別な専門職が必要となってまいります。ただ、単に専門性を持ち合わせているだけではレベルの高いケース管理はできませんので、そのような配慮が必要だと考えているところです。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問","question":"質問したいのですけれど、開設まで３年のタイムラグが金沢市の場合あったということですが、どのような課題があったのかお伺いしたいのと。先ほど虐待の件数を伺ったのですけれども、一時保護件数というのをお伺いしたいのと、お伺いします。","respondent":"高山児童相談所移管担当課長","answer":"先ほどご説明の中で不十分だったかもしれませんが、そして施設建設後、その部分でタイムラグが生じたというふうにお伺いしております。個室も視野に、そういった保護などのケースにも対応できるような、そういった居室設定が必要になっていくかと思います。","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問・要望","question":"もともと県に２カ所あって、結果的に県を３つのエリアで分けるということだったのですが、改めてわかる範囲で教えていただきたいのが１点です。本当に人が大事だと思っているのですけれども、そこら辺ぜひお願いしたいのですが、いかがか尋ねました。","respondent":"高山児童相談所移管担当課長","answer":"昨年度の一時保護の件数を４２件と申しましたが、申しわけありません、４７件の誤りでした。２３区共通の専門性にかかわる研修につきましては、現在検討を進めてもらっているところですので、育成を図ってまいりたいと考えております。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/172349?Template=document&Id=6036#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":40133,"voices":100}},{"id":"h29-20170928-18","meetingId":"h29-cm09","date":"2017年9月28日","dateIso":"2017-09-28","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午後 ３時３０分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"やはり品川区のことをよく知っているのは品川区民だと思いますし、どういう位置づけで、例えばボランティアのユニフォームというのですか。どういうかかわり方をしていくのかというのを１点お伺いします。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"２３区共通にいろいろ関わり方がありますので、東京都と連携をして、ボランティアについてのＰＴも立ち上がったところです。青写真も示されていないところですので、区は区として、気運醸成に向けて取り組んでいこうと考えているところです。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"品川区もいち早く招致をやってきたわけですから、東京都に呼びかけをして、連携をとってほしいと求めました。もちろんオリンピック・パラリンピック準備課との連携も必要であろうかと思いますので、その辺を課としてどう考えているか、の説明を求めました。","respondent":"遠藤協働・国際担当課長","answer":"商店街の数ですが、１２の商店街にやっていただきました。今後は、さらに、観光協会などとも連携して、うまくそういうことをできればなというふうに、今進んでいるところです。","id":"exchange-002"},{"speaker":"いながわ委員","kind":"質問・要望","question":"語学ボランティアの講座なのですけれども、ここで品川区として９月３日現在で４６３名ですか。それをしっかりやっていただきたいのですが、その辺どうお考えなのかの説明を求めました。","respondent":"遠藤協働・国際担当課長","answer":"今後も商店街連合会とかを通じまして、引き続き気運醸成に努めさせていただければと考えています。やるものによって、大会ボランティアや組織ボランティアとは違うような形でうまく参加できるような形にできればなというふうには思っております。","id":"exchange-003"},{"speaker":"いながわ委員","kind":"質問・要望","question":"普通に道の案内をすればいいだけですから。やはりリオ行ったときも、一番期待されるのは東京オリンピックだと言っていたわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"最終的に今の話で、人数的なものもおわかりだったら教えていただきたい。この何点かお伺いしたけれども、まずそれの説明を求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"２０％は外国人で、アメリカ、イギリス、ロシア、中国、アルゼンチン等の各国から来ていたというふうにうかがいました。このボランティアの戦略にも出ておりますが、はっきりと書かれておりますが、宿泊に関する情報提供について検討をするというふうに書かれてあります。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"提案","question":"東京は治安もいいし、目指して１０倍ぐらいの人が来るのではないですかと言ったら、そこでもう１０万人になってしまうわけではないですか。そういうことを仕掛けていくならあと３年しかないから、そういう提案を受けて、今からこういう事業も実施してはどうかとの意見を述べました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"区の施設を使うのか。そういったことで、区としても十分認識しておりますので、今後とも検討してまいりたいと考えています。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"提案","question":"私はもう来年度それを準備して、区としてこういうところがあって、こういう提案をしてください。いろいろな提案をしてもらうというのは、私は来年にはそういう部分の行動は起こすべきだと思っているので、それはぜひとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこをしっかり構築していただきたいと思うのですけれどもいかがですかというのが１つです。まだスキームがはっきりしないからそこは示せないのかについてもお伺いしたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"これは当然今後もいろいろな区のイベント等に活躍していただきたいと思っているところです。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"３年ですから、今から示していくことが必要だと思うのですけれども、その辺についても改めて伺いたいと思います。こうした区と関係の強い法人や団体や組織との連携というのも、あわせて必要だと思いますけれども、いかがか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"あくまでも区の２０２０年に向けた気運醸成の取り組みのイベントにご協力をしてくださいということで、協力をしていただいているところです。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"そうはいっても、また日本の文化や観光も楽しみに来るわけですから、品川区としてボランティアの募集や周知をしっかりしていく必要があると思います。","respondent":"鈴木文化観光課長","answer":"区のほうでも、今、観光に関するところでは、語学のボランティア。区内のどこででもオリンピックの観戦者でも旅行の方でもいろいろな方に対応できるような区内の状況というのは、整備を進めているです。","id":"exchange-010"},{"speaker":"本多委員","kind":"質問","question":"当然会場は品川区ではないのですが、こういったところを２０２０年を充実させるために品川区が率先して２０１９年のラグビーに参画をしていく。ただ、それが一番２０２０年をスムーズに迎えるためのプレになるのではないかなと思うのですが、どういうお考えか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"東京都組織委員会のほうでも、まずラグビーワールドカップ２０１９での経験を大会につなげたいという思いがあるようです。具体的にはもう少し待ってくれというようなお話がありますので、そういった経緯を見つつ、品川区としても動いていきたいというふうに考えてあります。","id":"exchange-011"},{"speaker":"本多委員","kind":"質問・要望","question":"２０２０年と２０１９年、品川区が担う役割というのは、イメージとしてはどんな感じなのでしょうか。同じようなイメージなのか、その辺の臨むに当たってのイメージというか、戦略というか、教えていただければと思うのですが。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"観戦客の動きも大会のときとは違うのだろうというふうに考えてあります。委員ご指摘のとおり積極的に手を挙げるなどして、２０２０年に備えて少しでも経験則としてつなげられるように工夫をしてまいりたいと考えています。","id":"exchange-012"},{"speaker":"本多委員","kind":"質問・要望","question":"質問の内容は、要するに２０２０年を充実させるためのプレをやってくれということなのです。イメージを教えていただきたいのです。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"当然会場周辺の観光客、観戦客へのご案内と、都市ボランティアが編成されて活躍するものだというふうに考えてあります。今回の東京都の考え方ですので、どういったことで区民の方たちが携われるのかというのは、今後推移を見て考えていきたいと思います。","id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だけれども、全国自治体に会場があるわけであって、そうすると、組織委員会に対して物事を言っていく必要があるのではないでしょうか。何か１つの共通の基準を持って募集していくなり、複数の区、そういうことをしていくことのほうが私はいいと思うのですがいかがか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"例えば都市ボランティア、会場周辺の案内員につきましては、少なくとも品川区民がご案内できるのが一番望ましい形であろうか考えてあります。","id":"exchange-014"},{"speaker":"伊藤委員","kind":"意見","question":"だから、お願いしたいのはこういう他の地方自治体との連携をしながら、やはりこのことについては共通の課題だと思うのです。お願いいたしますとの意見を述べました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"東京都と組織委員会は競技会場を有する自治体をはじめとする関係団体と十分に連携し、大会の成功を日本全体で実現できるよう一体的な取り組みの推進を検討していくというふうにはっきり書かれてありますので、はっきりともの申してまいりたいと考えています。","id":"exchange-015"},{"speaker":"たけうち委員","kind":"確認","question":"確認ですが、このボランティア戦略の中の２番の戦略の主な内容の(2)の多様な参加者の活動促進で、小学生については体験できる仕組みを検討と。その辺がもしわかれば教えてもらいたい。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"大会ボランティア、都市ボランティアの募集要項はこういった年齢ですので、あくまで別枠だと考えます。東京都、競技運営をサポートしてもらうとかいうようなことを現在考えているようではありますが、戦略ではここまでしか表現されてございません。","id":"exchange-016"},{"speaker":"たけうち委員","kind":"質問・要望","question":"わかりました。それを将来に活かしていただきたいという思いがありますので、ぜひそういう要望をもしできる場がありましたら、要望してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"つる委員","kind":"質問","question":"観光先に来られるかどうかというのは、特にホームステイなども直前でやってもどう対応していいかわからないということもあると思うのです。１９６４年のときもそうだったと思うのですが、具体的に取り組み始めて４年の中で、そこの部分の説明を求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"品川区では、会場ではなくなってしまいましたが、今現在ブライドサッカーを応援しています。大会が終わった後も、また障害者スポーツの振興がさらに発展するということ、今現在はそういった手応えを感じているところです。","id":"exchange-018"},{"speaker":"つる委員","kind":"質問・要望","question":"そういった部分の見方の感触というところで先ほど伺ったわけですけれども、品川区で一生懸命、それはそれで寂しさが残る部分があるかと思うのです。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"研修の部分につきましては、大会ボランティア、都市ボランティアにおいてそれぞれの研修等がございまして、そうした部分でやっていくです。研修につきましては、まだこれからいろいろ国や関係機関と連携をとりながら検討していくというふうに書かれてあります。","id":"exchange-019"},{"speaker":"つる委員","kind":"質問","question":"先ほど、こういう品川区で一生懸命つくり上げた物だけれども、何か連携させる仕組みというのが今後可能性としてあるということですよね。そういう細かい内容は当然これからなのだけれども、そういう可能性があるかということか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"競技会場を有する自治体との連携という部分につきまして、接遇や大会情報などの研修の一部を共有化するなどが書かれてあります。ボランティアによる案内の質的向上を目指していくというような指摘がありますので、そうした情報を区としては率先して捉えていきたいと思います。","id":"exchange-020"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１点だけいいですか。最後にそれだけお聞きしたい。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"当然組織委員会から示されておりますそういったガイドラインというものは、各自治体にもう既に送られてありますので、そういった資料につきましては許す限りご提供していきたいと考えています。","id":"exchange-021"},{"speaker":"いながわ委員","kind":"質問・要望","question":"これはボランティアだけではなくて、２年前にこういう動きがあるということは、ホスピタリティハウスしかり、先ほど言ったボランティアの施設か尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長、木村委員長","answer":"今年度予算で調査委託等もついているようなことでございまして、さまざまなノウハウを使って動いているところです。まだ明確なことは言えませんけれども、さまざまなところで動いているということだけご理解いただければと思います。現時点において、東京都より要望項目に関して回答を得られていないことを鑑み、重複した項目で要望書を提出することを問題ないと考えております。ご意見等につきまして、ご発言を願います。","id":"exchange-022"},{"speaker":"いながわ委員","kind":"質問","question":"少し外れてしまうかもしれないのですけれども、西側にある公園は、あそこは大井ふ頭中央海浜公園ではなかったのでしょうか。全部か尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"たけうち委員","kind":"質問・要望","question":"あえて言うならば３番のその他になるかと思うのですが、もちろん品川区でできる、ぜひ東京都でも考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"伊藤委員","kind":"提案","question":"何を求めんとされているのかなと。ただこの表現だと、例えば誰でもトイレの複数設置にその内容を込めていくとか、もう少し文言を整理したらいいのではないでしょうかという提案ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"ＬＧＢＴの施設整備についてですが、ずばり言うと、トイレですよね。もちろんトイレ限定ではないでしょうから、トイレなどの施設整備という感じにすると趣旨が伝わるのかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"いながわ委員","kind":"質問・要望","question":"公園の整備関係で追加というか、当然当たり前のように東京都の港湾局なのか公園関係の部署なのか。アルゼンチンアリなどさまざまなそういった虫もいるので、感染症対策をしっかりやっていただきたいという表現をお願いしたいと思います。","respondent":"木村委員長","answer":"次回東京都オリンピック・パラリンピック準備局にて意見交換などを実施する予定でございまして、どうぞよろしくお願いをいたします。以上で、特定事件調査を終了いたします。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/645888?Template=document&Id=6522#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":27307,"voices":71}},{"id":"h29-20170929-5","meetingId":"h29-cm09","date":"2017年9月29日","dateIso":"2017-09-29","committee":"総務委員会","time":"午後 １時２１分～午後 １時４５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を6件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田（し）委員","kind":"質問","question":"今まで３区だけだったのが、２つの開票作業がどうしても生じてしまう中で、どのように開票されるのか。特に期日前投票は全ての投票所で投票が可能だと思うので、その辺の変更する部分はどのようになっているのかの説明を求めました。","respondent":"安井選挙管理委員会事務局長","answer":"チラシについても今回の７区についての説明、そちらのほうにも、なるべく周知ができるような形で作成するということを予定しておりまして。","id":"exchange-001"},{"speaker":"石田（し）委員","kind":"質問","question":"３区の人は基本的に変わらないので、７区部分の人たちに、そういうものは封入できないですか。その辺だけ最後の説明を求めました。","respondent":"安井選挙管理委員会事務局長","answer":"７区の方については、７区は今までの３区から移行しましたというチラシを入れるような形でお送りする予定です。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どの辺で予算が増えているのか教えていただきたいのと、都議会議員選挙の投票率の内訳を教えていただいて、いかがか尋ねました。","respondent":"安井選挙管理委員会事務局長","answer":"とにかくその方たちが２０代、まずは１８歳の方たちからということで、ちょっと長めのスパンで見ていかなければいけないところがあります。特にそこだけというのはなかなか難しいところが現実です。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"というのは、ぱっと開けて、行こうかといつもの場所に行ってしまうではないですか。ただ、日数ももうないので何とも言えないのですが、一応その日に開けるという人がいるということを気にかけてやっていただくよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"松澤委員","kind":"質問","question":"これは投票だから仕方ないという形でやられるのでしょうか。その辺はいかがか尋ねました。","respondent":"安井選挙管理委員会事務局長","answer":"基本的には国から委託されてやるものなので、その辺は補償等はできないということになります。","id":"exchange-005"},{"speaker":"あくつ副委員長","kind":"意見","question":"１つだけ。何か事前にそこを知らせる、今回アトレはありませんというところ、そこは何か工夫されるのかとの意見を述べました。","respondent":"安井選挙管理委員会事務局長","answer":"今回急遽こういうことだったので、後々の関係を友好にやっていかないと困ると思いまして、その辺も働きかけをしていきたいと思っています。","id":"exchange-006"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/762881?Template=document&Id=2090#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":6721,"voices":32}},{"id":"h29-20170929-10","meetingId":"h29-cm09","date":"2017年9月29日","dateIso":"2017-09-29","committee":"議会運営委員会","time":"午後 ２時０５分～午後 ２時０９分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/706163?Template=document&Id=5242#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":1563,"voices":12}},{"id":"h29-20171002-4","meetingId":"h29-c-settlement","date":"2017年10月2日","dateIso":"2017-10-02","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時４３分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を151件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"つる副委員長","kind":"質問・要望","question":"終了時間のお知らせにつきましては、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても直ちに取りやめていただきます。第６項、５階の理事者控室に当委員会の模様を放送いたしますので、そちらでお聞きいただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"以上で、決算統計上の数値および財政健全化法に基づく各指標についての説明が終わりました。 それでは、平成２８年度品川区一般会計歳入歳出決算","agenda":"以上で、決算統計上の数値および財政健全化法に基づく各指標についての説明が終わりました。 それでは、平成２８年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"ページ数は成果報告書ですと７２ページ以降、歳入全般の中で少しお伺いさせてほしいと求めましたが、さまざまありました。私も少し確認していたのですが、基本的に平成２８年度予算の編成時におおむね、少し教えてほしいと求めました。","respondent":"秋山財政課長","answer":"こちらは平成２８年度、２万円を前後しておりますけれども、低調な部分がそのまま入ってきたです。特別区民税の２５億円余のプラスですけれども、その分、納税義務者が増えているというのが一番の原因であると評価しているものです。","id":"exchange-002"},{"speaker":"渡部委員","kind":"質問・要望","question":"納税率、納税額が増えてきたのではなどという判断をしていましたので、その辺についてお伺いさせていただきました。たばこに関する考え方を区のほうにお伺いしていきたいのですが、先進的な条例ではあるものの、子どものいる家庭に対しての条例ができました。","respondent":"川島健康課長","answer":"国のほうは、ご存じのとおり、さきの通常国会で法案の提出を予定してございましたが、見送られたというところです。こちらの動きを見させていただいて、それに沿ってすぐ対応できるように動くというのが、私どもの考え方です。","id":"exchange-003"},{"speaker":"渡部委員","kind":"意見","question":"この先どうなるかはわかりません。しっかりその時々に見合った対応をこれからもしていきたいと考えていますので、行政の方々もともに注視のほうをとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"新妻委員","kind":"質問・要望","question":"私から２点、確認と要望をします。１点目に、集会所の利用数が、平成２７年、平成２８年と減少傾向にありますが、どのような要因だとお考えか尋ねました。","respondent":"伊崎地域活動課長、有馬学務課長","answer":"利用率で見ますと約２％の減少となっておりまして、こちら、さまざま確認したところ、特段大きな理由というのは、今、見つからないところです。この就学援助に書かれております２３７万９,０００円の内訳は大きく２つございまして、１つは要保護者に対する修学旅行費の補助です。保守点検日を日曜日に設定している理由ですが、先ほど申し上げたように、清掃、工事などあります。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"今年の予算特別委員会で、いわゆる前倒し、入学前の３月に支給をという要望をさせていただきました。しかし、区でこの制度を変えないと、前倒しはできないという状況ですので、この点をどうお考えかということをお聞かせほしいと求めました。","respondent":"伊崎地域活動課長、有馬学務課長","answer":"集会所の予約受付開始時間のずれについて修正できないかですが、今現在、その中で改善の方法を考えていきたいと考えています。要保護児童生徒援助費補助金及び特別支援教育就学奨励費補助金交付要綱が改正されまして、児童ではない、対象となるようにする改正もございました。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"ぜひ、利用しやすい集会所として検討をお願いいたします。就学援助費の前倒しにつきましても、やはり対象の方が安心して４月に入学ができる体制について、前向きな検討を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"私からは、成果報告書７６ページの民生費負担金より保育園保育料、８４ページの情報公開手数料について、それぞれ伺いたいと思います。子ども１人あたりの平均月額保育料、それと平均的な家庭における０歳児と３歳児の月額保育料は幾らなのかお伺いしたいと思います。","respondent":"佐藤保育課長","answer":"保育園保育料の平均額です。第１子ですけれども、０歳児に関しましては３万７,００４円、３歳児ですと大体２万６４２円、全年齢の平均ですと２万５,７２６円になっております。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"お子さんが保育園にお世話になっている方から話を伺いましたが、毎月の保育料の負担が重く、何とかしてほしいと話しておりました。保育園はもちろん幼稚園も含めて、保育料の無償化を目指してほしいと求めましたけれども、いかがか尋ねました。","respondent":"佐藤保育課長","answer":"この家計に与える影響の考慮という部分について、国が多子軽減の考え方を示しまして、区では適切に保育料に反映しているところです。保育園保育料の無料化の考えですが、基本的な考え方といたしまして、こちらのほうに関しても適切に対応していきたいと考えております。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"こうした子育て世代の貯金の難しさや生活のやりくりについて、品川区に実感はあるのか、お伺いしたいと思います。第１子の軽減ができない理由というのは何なのか、お伺いしたいと思います。","respondent":"佐藤保育課長","answer":"０から２歳児の乳幼児人口に占める保育園の利用率は３５％です。在宅子育て世帯との公平、各世帯の信頼をいただきつつ、持続可能な負担の仕組みを行政として考えていかなければならないと考えております。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問","question":"この中で、毎月の保育料の負担が、０歳児で３万７,０００円です。重過ぎる負担だと思いますが、０歳で毎月３万７,０００円の負担について、区は家計にかかる負担が重いとは思わないのか伺いたいと思います。","respondent":"佐藤保育課長","answer":"引き続き、保育料の負担の考え方ですが、繰り返す部分もありますけれども、０から２歳児等の乳幼児人口に占める保育園の利用率は３５％です。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"私は、０歳児の３万７,０００円という負担が重いとは思わないのかと伺いました。ご答弁ほしいと求めました。","respondent":"佐藤保育課長","answer":"正確な数字は今出てこないのですけれども、０歳児に対する年間の運営費は、たしか１人当たり７０万円を超える負担が必要になっております。そういった中で、国が決めました保育料の基準額もありますので、それらについてバランスよく今後も徴収をしていきたいと考えております。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"ここに新たな子育て世代の負担軽減の検討を追加してほしいと求めましたけれども、いかがでしょうか。思い切った子育て世代の経済的支援の充実を、長期基本計画の改訂にしっかりと位置づけて進めてほしいと求めましたけれども、いかがか尋ねました。","respondent":"佐藤保育課長","answer":"引き続き保育料の無償化の関係ですが、区といたしましては、これまでも幼児教育の無償化ということで、一定の負担軽減に努めております。平成２７年度子ども・子育て支援新制度に基づきまして応能負担というものも取り入れるところで、適切に対応していきたいと考えております。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"長期基本計画の位置づけを伺ったので、その点もご答弁ほしいと求めました。先ほども伺ったのですが、第３子目を無料としておりますが、なぜ第１子目の負担軽減ができないのかについても改めて伺いたいと思います。","respondent":"佐藤保育課長","answer":"国や都の動向を見て、それぞれ判断していくところですので、計画にのせるためには一定の検討が必要だと考えております。第１子の関係ですが、国との検討会議の中で、第１子よりも多子のほうが基本的に大変だという考え方に基づいて対応していきたいと考えております。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"第３子目の無料はわかるのですが、それがなぜ第１子目の負担軽減をしない理由になるのか、そこがよくわかりません。そうした第１子目の負担軽減を、なぜ多子軽減をやっていることをもってやらないと考えるのか、ご答弁ほしいと求めました。","respondent":"佐藤保育課長","answer":"繰り返しになりますが、在宅子育てでお子さんの保育をしている方もいらっしゃいますし、また区といたしましては限られた財源を適切に使っていくということもありますので、その辺も含めて総合的に考えていきたいと考えております。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"２３区の状況を伺いますが、品川区の他に情報公開手数料が有料の区はどこなのか伺います。ぜひ品川区もこれを機に無料化を進めてほしいと思いますけれども、なぜできないのか、お伺いしたいと思います。","respondent":"中元広報広聴課長","answer":"東京都が情報公開手数料を無料にした趣旨ですが、都政の透明化・見える化の推進策を検討する中で、閲覧手数料を廃止したということで聞いております。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ無料化を検討してほしいと求めましたけれども、いかがでしょうか。この区民憲章の理念からも情報公開の手数料を無料化する検討を今から始めるべきだと思いますが、いかがか尋ねました。","respondent":"中元広報広聴課長","answer":"情報公開の手続によらず、情報提供に切りかえられるものは切りかえていくということで、今後も情報公開の推進をしてまいりたいです。区の窓口かホームページでの情報提供を、今後も推進してまいりたいです。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"住民自治の確立には積極的な情報公開が必要だと思います。その情報公開に手数料を取る姿勢は改めていただきたいと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"いながわ委員","kind":"質問・要望","question":"４,９００万円減ということですが、低税率というのですか、そして今後の見通しをお願いします。これは教えていただきたいのですが、過誤納金というのですか、例えば多く区民の方に交付してしまった。","respondent":"伊東税務課長、池田スポーツ推進課長、溝口公園課長、今井土木管理課長、提坂戸籍住民課長、秋山財政課長","answer":"税制の改正ということが今、検討されていると聞いてありますので、その動向を注視していこうかと考えています。私からは、しながわ区民公園の水泳場のニーズについてご説明します。私からは、プールと関連しまして、しながわ水族館といったところの、公園全体としての連携について答えします。ＮＴＴを合わせて約１万３,０００本ほど電柱がありますけれども、所有者等と十分協議を重ねつつ、またその取り組みを進めていきたいと考えています。","id":"exchange-019"},{"speaker":"いながわ委員","kind":"質問・要望","question":"進めているところで、こういうところでお金を取って解決するかどうかは別ですけれど、その辺はしっかりやってほしいと求めました。公園に関しては、通年、しっかり区民の皆様が憩える公園にしてほしいと求めました。","respondent":"秋山財政課長","answer":"税や、その辺の公金収納については、どのようなことができるのか、今のところ制度上の制約というのもあって、こういう形をとっているということでありますので、その辺は、できれば研究はしたいと思ってあります。","id":"exchange-020"},{"speaker":"藤原委員","kind":"確認","question":"初めに９２ページの国民健康保険についてお伺いしますが、まず質問する前に、今日が初めての質問です。職員の皆様の日々の努力を積み重ねた結果であり、大変うれしく思います」とありましたが、具体的にこれはどういうことか尋ねました。","respondent":"三ッ橋国保医療年金課長","answer":"そして滞納繰越分４９.７８％で２３区中１位、そして総合が８５.４３％で２３区中１位、トータルも１位となっております。こちらは職員の日々の努力が実を結んだと考えております。","id":"exchange-021"},{"speaker":"藤原委員","kind":"質問","question":"この数字が落ちるというのは、あまり評価されることではないと思うので、その意気込みをお伺いします。この辺についてはいかがか尋ねました。","respondent":"三ッ橋国保医療年金課長、中元広報広聴課長","answer":"この宝物を守る制度として国民皆保険制度があります。引き続き、国保につきましても、職員一丸となって取り組んでまいりたいと思います。全国サミットに取り組むということで意思を表明して以来、熱心に取り組まれておりますので、そこのところは申しわけございません。あくまで広報広聴課の機材の調整の問題でございました。","id":"exchange-022"},{"speaker":"藤原委員","kind":"質問","question":"これはどうしてでしょうか。、答えるよう求めました。","respondent":"秋山財政課長","answer":"単年度収支ですけれども、こちらは実質収支額の前年度との差というのをあらわしています。それで、平成２７年度は実質収支が４６億円、今年が４４億円ということで、実質収支額が減っておりますため、単年度収支がマイナスです。","id":"exchange-023"},{"speaker":"藤原委員","kind":"確認","question":"それも確認です。その辺についていかがか尋ねました。","respondent":"秋山財政課長","answer":"平成２７年度が非常に景気がよかったというのもございまして、特別区の区民税を含めて歳入が非常に伸びた。平成２８年度決算につきましては、実質収支が前年より減少していると私どもとしては捉えておりまして、結果としてマイナスです。","id":"exchange-024"},{"speaker":"藤原委員","kind":"質問","question":"その辺についてはいかがですかということと、人件費の構成比が、平成２８年度は１５.６％です。前年度の１７.２％から１.６％も下がっているのですが、これは２３区中で何位で、またどういう利点があるのかもの説明を求めました。","respondent":"秋山財政課長","answer":"ですので、それをもって歳出の事業を進めていくという財政運営を品川区はずっとやってきた、こういう形になっていると理解しているものです。それから人件費の比率ですが、高いほうから見て１８位なので、低いほうから見ると６位です。","id":"exchange-025"},{"speaker":"藤原委員","kind":"質問・要望","question":"それで、どういう利点があるのかとお伺いしたので、それも答弁してください。中でも投資的経費が１４０億円増えていますが、国庫支出金と都支出金あわせて約１００億円増えていますが、改めてこの理由をお伺いします。","respondent":"秋山財政課長","answer":"これは投資的経費の１４０億円余は、先ほどもご説明させていただきましたけれど、基本的には土木費の再開発事業です。概して品川区が２３区の中で低いというか高いというか、上から数えたほうが早いというところにいる理由は、そういうことだと考えています。","id":"exchange-026"},{"speaker":"藤原委員","kind":"意見","question":"果たしてこういう状況で人件費比率は正確な意味を表現しているのかどうか。この辺についてはどういうお考えを持っていますかとの意見を述べました。","respondent":"秋山財政課長","answer":"そうはいっても、基本的に、そこの人件費比率が分母の大きさによって変わるという割合がどのぐらいかということになるかと思うのです。昨年度も品川区の２３区中の順位というのも、分母も含めて財政運営の結果と考えていただくというのがよろしいかとは思ってあります。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"もう少し工夫というのか、あらわしていったほうがいいと思うのですけれど、改めてその辺についてお伺いします。５ページのところに「緩やかな回復基調」と書かれていますが、私自身は実感を得ていないのですけれども、この辺についてはいかがか尋ねました。","respondent":"秋山財政課長","answer":"基本的なトレンドとしては人件費比率は下がっているという形で考えておりまして、排除してということは、特に考えているものではございません。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"１世帯、年収１,０００万円以上の方が、たしか３３％以上いらっしゃる。この辺も私は考えながら、これからまた質問していきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問・要望","question":"先ほどご答弁の中に、９５％が営利の事業者ということでしたが、明らかに営利とわかる場合のみ有料にすることは可能なのかということを１点伺います。情報公開は無料にすべきと思っていますが、せめて表記をわかりやすくすべきではないかと思いますが、ご見解を伺います。","respondent":"中元広報広聴課長","answer":"やはり個人のお名前で請求されたりした場合に、なかなかその判断が難しいところがあると思っているところです。おそらく閲覧から写しの交付になった場合は、それを通して３００円という形で設定していますので、書式の表記を今後工夫してまいりたいと思います。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"それからもう一点、非公開だった場合、先ほどの不服申し立てや反論書には９０日の提出期限があります。やはり処分庁のほうにも、いついつまでには必ず出すという期限があってしかるべきではないかと思うのですが、その辺についても、答えるよう求めました。","respondent":"中元広報広聴課長","answer":"きめ細かく対応させていただきたいと考えていますので、今後、事務上どうなのかという確認をして進めてまいりたいと思います。こちらの担当からもいろいろご相談をしているところなのですが、ただ、やはり状況によって難しい場合もあったというところかと思います。","id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"基本的には情報公開を求める以前に情報公開を進めるという趣旨のご答弁をいただきましたので、ぜひそちらを強めていってほしいと求めました。ニーズはあると考えているのですけれども、この数字の意味を伺いたいと思います。","respondent":"矢木生活福祉課長","answer":"私から、家計相談５件の件数についてご説明申し上げます。こちらの件数につきましては、平成２８年度に新たに家計相談支援事業のプランを作成した件数です。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"では、新たに始まったのが５件ということで、例えばその前の２０１５年の２１件が継続してずっと今年度も続いていると理解していいのか尋ねました。","respondent":"矢木生活福祉課長","answer":"こちらの家計相談支援事業につきましては平成２７年度からスタートしてございまして、こちらの２１件の方のうち支援が３カ月。こちらにつきましては、例えば相談件数でありますとか自立支援人数でありますとか、よりわかりやすい報告をさせていただければと思ってあります。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問","question":"２０１５年の決算特別委員会でも、私は生活困窮者向けの相談事業について質問しております。国からの補助事業ということで、品川区として今後も力を入れていってほしいと思うのですけれども、どのような方向性をお考えかの説明を求めました。","respondent":"矢木生活福祉課長","answer":"現在、こちらの相談員は６名体制で行っておりまして、主な資格といたしましては、社会福祉士、精神保健福祉士、福祉事務所のケースワーカー等々です。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"今後もこの件については追っていきたいと思いますが、今日のところは次の質問に移ります。平成２４年度から段階的に拡大し、２０１６年度の段階で結構ですので、対象となる障害児の何％の相談支援を行えているのか伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"例えば平成２７年度は大体２５０人ぐらいの方が、この障害児の福祉サービスを使われていました。区のほうでも相談支援のところには力を入れているところではありますが、６５％ぐらいの方に計画相談を導入でき、モニタリングを行っているです。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問","question":"それで、支給決定を行う障害者福祉課の中に、この障害児の相談支援事業所があるというのは、どういうふうに理解したらよろしいのでしょうか。厚生労働省の言う独立性の確保をどうやって担保しているのか伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"まず地域の相談実績をつくることが大事かと考えていますので、それから障害児のほうに移っていければ、そういう連携ができればと考えております。相談支援センターの役割のところで、支給決定のところは、メンバーを切り分けて適正にできるようにしています。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問","question":"来年度中には何とか１００％までということだと思うのですけれども、１００％、少し厳しいのかと思います。それをどう考えていらっしゃるのかというのが１点と、それぞれ何人ぐらいずつの配置でそれを行っていらっしゃるのか、もう一度の説明を求めました。","respondent":"中山障害者福祉課長","answer":"区の役割、それから地域の相談支援事業所としての障害児の計画相談の役割というところについて独立性の担保をしていきたいと考えております。この４人の体制で行っているのですが、おおむね１人当たり１００から１５０件ぐらいのプランをつくっているような状況です。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"それで、その人数を考えると、平成３１年度からも品川児童学園１カ所では結構厳しいかと思います。特に障害児の場合、丁寧な相談というのを求めると思いますので、やはりそれは増やす方向で考えていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"横山委員","kind":"質問","question":"８８ページ、９３ページ、高次脳機能障害者支援促進事業についてお伺いいたします。１点目に、高次脳機能障害者支援促進事業についてお伺いいたします。","respondent":"中山障害者福祉課長","answer":"利用者やその家族の相談だけではなく、例えばケアマネジャーですとか就労支援事業所といったところの相談も行っているところです。より専門的な分野については、品川区だけではなく、大田区、目黒区という中で、荏原病院と連携を図り、協力を得ながらやっているところです。","id":"exchange-039"},{"speaker":"横山委員","kind":"意見","question":"家族の方も、ご相談内容は多岐にわたってくるかと思いますので、今後もきめ細やかな相談機能の充実をお願いしたいと思います。こちら、最後に一言お願いいたしますとの意見を述べました。","respondent":"中山障害者福祉課長","answer":"高次脳機能障害の支援というところでは、福祉の現場だけではなく、医療現場との連携が大変重要だと考えておりますので、三区中心としながら医療連携も進めていきたいと考えております。","id":"exchange-040"},{"speaker":"横山委員","kind":"質問","question":"２点目は、私立幼稚園就園奨励費についてお伺いいたします。気づきの段階から保護者と子どもたちをスムーズにサポートするための支援対象者の捉え方について、現在の区の考え方の説明を求めました。","respondent":"佐藤保育課長","answer":"２点目、私立幼稚園に対する支援と相談の関係ですが、平成２８年度から学校心理士による巡回相談を行っております。３点目、私立幼稚園の保育料には反映はしないのですが、就園奨励費補助金への反映について考えているところです。","id":"exchange-041"},{"speaker":"横山委員","kind":"質問","question":"公立保育園・幼稚園での特別支援教育の支援体制なのですが、こちらはどのようになっていますでしょうか。私立園への支援体制と違い等、何かそれぞれの特徴などございましたら、現時点における課題等を含めての説明を求めました。","respondent":"佐藤保育課長","answer":"公立保育園は、平成２８年の実績ですと、特別支援児２５０名、私立保育園は２３名、私立幼稚園は２５名と増加傾向にあります。今後もさらに、特別支援児の教育相談、巡回等に向けて力を入れていきたいと考えております。","id":"exchange-042"},{"speaker":"横山委員","kind":"質問・要望","question":"３点目なのですけれども、高齢者多世代交流支援施設使用料、保育所等整備交付金についてお伺いいたします。平成２７年にさいたま市の公共施設マネジメント推進担当の方より、さいたま市の公共施設マネジメント計画についてお話をお伺いする機会がありました。","respondent":"松山高齢者地域支援課長、吉田保育施設調整担当課長、高山子ども育成課長","answer":"平成２８年５月開始以降、平塚橋ゆうゆうプラザが延べで３万８,０００人ほどと、現在も増加傾向です。委員ご質問の保育園建て替え計画について回答いたします。児童センターにつきましては、区内２５カ所に存するわけなのですが、この中で築５０年を超えるものが４カ所ほどあります。シルバーセンターのバリアフリー化を進めるとともに、老朽化の度合い、改築の際にはゆうゆうプラザへの転換を進めてまいりたいと思ってあります。","id":"exchange-043"},{"speaker":"横山委員","kind":"質問・要望","question":"品川区公共施設等総合計画に基づきまして、それぞれ改築計画を明確にしていただきたいということを要望させていただきたいと考えています。将来世代への負担が不公平にならないように工夫できる点がありましたら、あわせてお伺いいたします。","respondent":"柏原企画調整課長","answer":"施設のいろいろな複合化であったり集約化であったり、ソフトの面も含めて有効的に活用できるようにということで進めてまいりたいと思ってあります。","id":"exchange-044"},{"speaker":"横山委員","kind":"意見","question":"将来世代への負担の部分について、不公平にならないように、もし工夫できる点がありましたらお聞かせいただきたかったのですけれども。適正配置のあり方という部分もあるかと思うのですけれども、そのあたりの進め方、考え方についての説明を求めました。","respondent":"柏原企画調整課長","answer":"使えたりしますので、そういったところをうまく活用しながら、将来の負担に対しても公平になるようにと考えています。どういった機能が必要かというのも、所管部門と調整等々しながら、公平性を保てるような形で進めていきたいと思ってあります。","id":"exchange-045"},{"speaker":"あくつ委員","kind":"確認","question":"皆様ご存じなので、確認なのですけれども、学校教育法第１９条の規定に基づいて、学用品、就学用品、修学旅行費等を援助する。確認ですけれども、つまり母数が減ったから、人数と割合も比例して減ったという結果なのかどうかの説明を求めました。","respondent":"有馬学務課長","answer":"就学援助受給者の母数の件ですけれども、まず平成２６年度は１万８,４９４名です。平成２８年度が１万９,３９８名ということでございまして、この２年間で、おおよそで９００名増えているという状況です。","id":"exchange-046"},{"speaker":"あくつ委員","kind":"質問","question":"その上で、６歳から１５歳までのいわゆる就学人口全体で見たときの割合というのはどれぐらいなのですかというお話をさせていただいたところ。","respondent":"有馬学務課長","answer":"基本的に、１年生から９年生まで、国立・私立を含めた児童生徒を母数にした割合というものを一応参考に出しています。平成２７年度は２０.７％、平成２８年度は１９.３％ということで、この率も下がっているというような状況です。","id":"exchange-047"},{"speaker":"あくつ委員","kind":"質問","question":"株価は２倍となりまして、有効求人倍率も上がって、可処分所得が実際に増えてきたことの裏返しである。ですから、後でまた述べますけれども、こう考えざるを得ないのですけれども、品川区としてどう分析されるのかご見解を伺います。","respondent":"有馬学務課長","answer":"金額の上限が、ある程度あるのですけれども、大体どこに分布しているかというのもあわせて見ております。大体、相対的に収入は上がっている家庭が多くなっているというふうに、今のところ分析しています。","id":"exchange-048"},{"speaker":"あくつ委員","kind":"質問","question":"１７歳以下人口約２,０００万人ですから、約４８万人の子どもたちが、この３年間で貧困状態から脱却できたことになります。私も出入りさせていただいている子ども食堂もありますが、区内における現状について、大体で結構なのですけれども、の説明を求めました。","respondent":"廣田子ども家庭支援課長","answer":"子ども食堂のネットワーク等を実施しておりまして、調査を集約しているところなのですが、まだ合わせても１２カ所ほどになっております。支援の物資などが必要だというようなご意見を聞いているので、それを品川区としてどう支援していって、模索しています。","id":"exchange-049"},{"speaker":"あくつ委員","kind":"質問・要望","question":"その講演会で私も駒崎さんに、就学支援が品川区で４,０００人もいるのですけれど、品川区でできるのでしょうかという質問をさせていただきました。","respondent":"廣田子ども家庭支援課長","answer":"宅食サービスにつきましては、地域活動課主催の講演会の内容についても、情報提供はリアルタイムでいただいているところです。品川区につきましては宅食というよりも子ども食堂の支援から政策を進めているというところから、物の集め方や支援金の集め方でありますとか。","id":"exchange-050"},{"speaker":"あくつ委員","kind":"質問","question":"品川区に合わせた形で、支援が届かないところにぜひ届けていってほしいという思いで質問させていただきました。その点についてのお考えを伺いたいと思います。","respondent":"伊東税務課長","answer":"最高額で１０万円、そして一番少ない額は１万円というような中身で、件数的には２３件です。予定まで見込めるかどうか等、いろいろな部分で検討が必要なのかと考えていますので、この流れの中でどう考えるかです。","id":"exchange-051"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今年の「ふれあい」９月号に、どのような課題があったのかというところを、ぜひ教えてほしいと求めました。沢口靖子さんなど、例えばお昼のロケ弁等の手配といったこともフィルムコミッション事業として行われたのかどうかをお聞きしたいと思います。","respondent":"鈴木文化観光課長","answer":"この件につきましては、まずはテレビ局のほうから、庁舎をロケ場所として使用できないかというご相談をいただきました。フィルムコミッション事業を区としてどこまで取り組めるのか、区としてどこまで誘致や支援に力を入れるかというのを、検討しています。","id":"exchange-052"},{"speaker":"あくつ委員","kind":"確認","question":"もう１つ確認なのですけれども、最後、エンディングロールにどういう形で品川区の名前が表記されたのか。私の希望としては、「品川フィルムコミッション」という名前で出てほしいという部分があったのですけれども、その点について確認いたします。","respondent":"鈴木文化観光課長","answer":"事前のＰＲにつきましては、撮影内容、それから番組の予告上の関係で、区での情報提供は差し控えてほしいというのがご希望でございました。基本的には区の取り組みですので、協力の名義表記は品川区というのが基本だというふうに、現在なっているところです。","id":"exchange-053"},{"speaker":"あくつ委員","kind":"質問","question":"前々から伺っておりますけれども、品川区がこういうフィルムコミッション活動に力を入れているという大変重要なメッセージになると思います。シティプロモーションの一環にもなりますので、表記についてもぜひご検討ほしいと求めましたが、いかがか尋ねました。","respondent":"鈴木文化観光課長","answer":"現在、体制を整備する中で、区のフィルムコミッションの協力体制や、それから撮影可能なスポット等についてホームページでお知らせするようなことも考えていますので、その特設サイトには、ぜひ品川区のフィルムコミッションというような表現を入れられればと考えております。","id":"exchange-054"},{"speaker":"南委員","kind":"質問","question":"７８ページの使用料、８３ページの自転車駐車場使用料の２つから伺いたいと思います。最近、昨年度との比較しかしていないのですけれども、利用が少し増えていると考えていますけれども、その点、どんな状況かをまず伺いたいと思います。","respondent":"伊崎地域活動課長、鈴木文化観光課長","answer":"区民集会所の利用状況です。平成２８年度の利用率が６２.２％、平成２７年度の利用率が６４.４％で、２％の減少となっております。毎年３万８,０００件程度のご利用をいただいておりまして、６０％から７０％ぐらいが、通常の集会などに使える部屋の利用率になっております。","id":"exchange-055"},{"speaker":"南委員","kind":"質問・要望","question":"利用率も増えているのかと思って伺ったのですけれども、マイナス２％と受けとめていいのかどうか、後でいいですから教えてください。第１に区民集会所ですが、これからそこの整備も進めていくのかどうか、そこを確認したいと思います。","respondent":"伊崎地域活動課長、鈴木文化観光課長","answer":"そういった声は特にいただいてはおりませんが、必要に応じて区民の皆様が使いやすいものに変更していきたいと考えております。いろんな制約がありますので、現状、なかなか難しいのではないかと捉えております。これは、設置した当時はそういう需要があまりなかったものですので、今後の改修に合わせて必要な設備は整えたいと考えております。","id":"exchange-056"},{"speaker":"南委員","kind":"質問・要望","question":"やはり数年かかるわけですから、改修ではなくても、できるところは整備をしていく。なかなか解消しないと思っているので、そういうふうにしていただきたいと思っているのですけれども、ぜひその点についての考え方を伺います。","respondent":"桑波田交通安全担当課長","answer":"民間のほうは短時間で２時間等、また課金されていきまして、１時間ごとにまた１００円とか５０円がかかっていくような状況になっております。やはり１日使って１５０円と現在進めさせていただいている形で行っていきたいと考えているところです。","id":"exchange-057"},{"speaker":"南委員","kind":"質問","question":"私は、品川区としても放置自転車をなくすということで、やはり無料で提供できるような方向で取り組むべきだと考えています。その考え方は、ぜひどうなのか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"無料となりますと、それだけ利用者も増えてしまい、やはりとめるべき方がとめられなくなってしまう、あふれてしまうのではないかという考えもありますので、そういったところで考えております。","id":"exchange-058"},{"speaker":"松永委員","kind":"質問","question":"私からは、２つ目が１０２ページの歩行喫煙防止過料、３番目に１００ページの地所賃貸料について伺いたいと思います。これについてですが、定期利用と一時利用の増減の理由について伺いたいと思います。","respondent":"桑波田交通安全担当課長","answer":"決められた方が自分の場所に、当日利用につきましてはそういった決めがございませんので、空いているところは誰でも使えるようになっております。","id":"exchange-059"},{"speaker":"松永委員","kind":"質問","question":"それですと、効率化を図るために、定期利用より一時利用のほうを多くしたというふうに感じました。そうしたバイク利用、自転車も含めて、定期利用を待っている方たちというのはどのぐらいおられるのか伺いたいと思います。","respondent":"桑波田交通安全担当課長","answer":"１６％程度が待っているという状況にありますけれども、こちらは今年の４月１日に条例改正いたしまして、区民優先制を導入しています。よって、お使いいただくというような取り組みもしておりますので、そういったところからも解消していくものと考えております。","id":"exchange-060"},{"speaker":"松永委員","kind":"質問・要望","question":"この過料について、１６件の内容について伺いたいのですけれども、過料を取った方の中に外国人の方はいらっしゃったのか伺いたいと思います。品川区におかれましては、加熱式たばこもたばこの一種ということで昨年伺っていると思うのですけれども、伺いたいと思います。","respondent":"菅生活安全担当課長","answer":"なお、この中に外国人が含まれているのかどうかは、今、手元に資料がありませんのでわかりません。加熱式たばこにつきましては去年の過料の中には入っておらず、徴収まではしていません。","id":"exchange-061"},{"speaker":"松永委員","kind":"質問・要望","question":"なぜこういう質問をしたかというと、たしか３区のみ、加熱式たばこはたばこの一種であるということで伺っていると聞いております。それで、約２億２,０００万円の差について、どのような形でこのような結果になったのか伺いたいと思います。","respondent":"立川経理課長","answer":"この説明欄につきましては、一番金額が大きいものを載せるということでございまして、今年度につきましては大崎ブライトコア５・６階等です。そして、２億２,０００万円の増ですけれども、こちらはブライトコアの貸付料について通年で家賃が入ってきましたものです。","id":"exchange-062"},{"speaker":"松永委員","kind":"質問","question":"いろいろ種類があり、主なところを載せるということでございました。では、この地所賃貸料に関しては大体何カ所ぐらいあるのか、少し伺いたいと思います。","respondent":"立川経理課長","answer":"電柱等で貸し付ける部分もございまして、件数では約４０件となっております。","id":"exchange-063"},{"speaker":"松永委員","kind":"質問","question":"地域の方から伺ったのですが、１００円という単位ではなぜできないのか、少しその辺について伺って終わりにしたいと思います。","respondent":"立川経理課長","answer":"駐車料金の設定の考え方ですけれども、区の財産を駐車場として貸し付ける場合は、民業を圧迫しないという大原則がありまして、大井町駅周辺につきましては、イトーヨーカ堂も阪急大井につきましても３０分２００円という設定ですので、それに合わせているです。","id":"exchange-064"},{"speaker":"鈴木（博）委員","kind":"質問","question":"任意予防接種ほか６事業に関連して、１０５ページの１９款諸収入、一般質問に引き続きお尋ねいたします。病後児保育事業の現状を区はどのように把握・分析されているのか尋ねました。","respondent":"佐藤保育課長","answer":"病後児保育の関係ですが、平成２８年度実績は５９０件で、前年度から２３９件減っております。医療機関併設型の病児保育を希望する保護者が増えているという影響から、病後児の利用が減っているという認識です。","id":"exchange-065"},{"speaker":"鈴木（博）委員","kind":"提案","question":"そのために、病後児保育所を廃止し、思い切って病児保育所に転用するという提案をさきの一般質問で行いました。今後の病後児保育事業について、区はどのようにお考えか尋ねました。","respondent":"佐藤保育課長","answer":"委員ご指摘のとおり、病後児保育のほうの需要は減少傾向にありますので、今後の事業展開につきましては、子ども・子育て会議の中で十分検討してまいりたいと考えております。","id":"exchange-066"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"病児保育所の新設は、かねてから我が会派が繰り返し熱烈に要望してきたものです。早速、９月２３日の日経新聞でも「品川区に病児保育」と報道されていましたが、新しい病児保育所開設に至る経緯についてご説明をお願いします。","respondent":"佐藤保育課長","answer":"最初のご相談は平成２９年２月にございまして、区の姿勢と、ぜひ区内にというお話をさせていただきました。６月に、補助金の目途が立ちましたので、補正予算で計上させていただいたところです。","id":"exchange-067"},{"speaker":"鈴木（博）委員","kind":"意見","question":"新たに１施設が開設されることになり、病気の子どもに対する品川区の保育行政の取り組みを高く評価いたします。子ども・子育て計画の検討を踏まえて、今後の病児保育所の増設計画についてご説明をお願いいたしますとの意見を述べました。","respondent":"佐藤保育課長","answer":"今後の増設の関係ですが、現在の子ども・子育て計画では、約２,５００ほど枠がまだ足りない状況であります。平成３０年４月から１施設開設いたしますが、まだ足りませんので、地域バランスを考えて計画達成に向けて努力していきたいと考えております。","id":"exchange-068"},{"speaker":"鈴木（博）委員","kind":"質問","question":"さまざまな医療機関とも協議しながら、今後も病児保育の増設に向けてご努力をお願いしたいと思います。直接的には委託施設と利用者の間の問題になると思いますが、区はどこまでかかわるのか、あるいはかかわることができるとお考えか尋ねました。","respondent":"佐藤保育課長","answer":"施設開設の前の段階では、これまでの医師の経歴や熱意、動機等を確認させていただき、医師会等と情報を共有します。意見交換をさせていただき、よりよい制度に向けて、見直しできるところは見直していきたいと考えております。","id":"exchange-069"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次に、おたふく風邪ワクチンについて再度お尋ねいたします。そのムンプス難聴について簡単にご説明をお願いします。","respondent":"舟木保健予防課長","answer":"このムンプス難聴は急性に発症しまして、感音難聴で不可逆性のものなので、治療の効果が認められません。難聴の程度としては高度のものが多く、一側性の場合がほとんどなのですが、両側に発症する場合もあると言われています。","id":"exchange-070"},{"speaker":"鈴木（博）委員","kind":"質問","question":"一般質問でも紹介したように、この２年間で３３６人がムンプス難聴と診断され、約８０％が高度難聴だったそうです。おたふく風邪に対するワクチンの効果と、ワクチン１回接種、２回接種での予防効果の違いについて、簡単にご説明をお願いします。","respondent":"舟木保健予防課長","answer":"他国のデータでは、１回の定期接種で患者数自体は９０％、２回定期接種することで患者数が９９％減少したとも言われています。そのように、ムンプスワクチンについては、病気の発症予防だけではなく、合併症を予防する効果もあるということが言われています。","id":"exchange-071"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ムンプス難聴はおたふく風邪ワクチンを２回接種することにより、おたふく風邪の発病を防げれば起こらない病気です。１回接種より２回接種のほうがより確実に防げると思いますが、品川区のお考えはいかがか尋ねました。","respondent":"舟木保健予防課長","answer":"国において定期接種化に向けて、より安全性の高いワクチンの開発を進めていることは、こちらも存じております。区としましても、国の動向等を見ながら検討してまいりたいと思います。","id":"exchange-072"},{"speaker":"塚本委員","kind":"質問・要望","question":"私からは、あと１０６ページの品川産業支援交流施設運営収入についてお伺いしたいと思います。投資的経費が、平成２８年度は前年に比べて大変増えておりますけれども、投資的経費の増えた原因について最初にお伺いしたいと思います。","respondent":"秋山財政課長","answer":"投資的経費ですけれども、こちらの主な原因は再開発等の補助金です。","id":"exchange-073"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういう意味では、経常収支比率が高くなるというか、パーセントとしては低くなるということですか。今、なかなか見えにくいのかなという思いがしておりまして、少しその現状を今どのように捉えていらっしゃるか教えてほしいと求めました。","respondent":"秋山財政課長","answer":"それを考えますと、即、弾力性が落ちているとは考えづらいのかと思います。２３区の場合、そういうところからも義務的経費が減っているというところがありまして、そういうことが言えるのかと思ってあります。","id":"exchange-074"},{"speaker":"塚本委員","kind":"意見","question":"今どういう状況に品川区があるのかというのを見るときに、こういった政策をぜひお願いしたいというような判断にも使えると思いますので、何かお考えがあるかの説明を求めました。","respondent":"秋山財政課長","answer":"必要な経費等が出てくることになりますので、そういうものを見ながら、健全性をあらわす指標というのを考えていきたいと考えています。しかしながら今の時点で新しい指標を品川区独自で考えるというのは、なかなか、これは難しいのではないかとは思っております。","id":"exchange-075"},{"speaker":"塚本委員","kind":"確認","question":"できるだけ、そういったことについてもわかりやすくできるようにしていただければという思いもありますので、研究のほどよろしくお願いします。これは当初、これは平成２９年度に予算化されていたのかの確認も含めて、どういうものなのかご説明をお願いいたします。","respondent":"山崎商業・ものづくり課長","answer":"なので当初、平成２８年度予算では、１,１００万円ほどの指定管理料を予算計上して、実際に支出しています。ただ、結果としまして、かつこちらの歳入のほうで運営収入として５,６００万円余をさらに歳入として計上させていただいたというような流れです。","id":"exchange-076"},{"speaker":"塚本委員","kind":"質問","question":"決算にこういうものが出てくるのは、少し先の話ではありますが、そういったことについてのお考えは品川区としていかがでしょうか。お伺いいたします。","respondent":"柏原企画調整課長","answer":"指定管理のチェックといいますか、その部分です。新公会計制度が来年度の稼働であったり、それから今、その中で検討していきたいと思ってあります。","id":"exchange-077"},{"speaker":"筒井委員","kind":"質問","question":"そして８３ページのロケーション・写真撮影等、そして時間があれば１０６ページ、品川産業支援交流施設運営収入についてお伺いいたします。それに対しての評価はどのようにお考えになっているのかをお伺いいたします。","respondent":"鈴木文化観光課長","answer":"ほぼ回数の上限に近いところで使用しており、入場者の方も安定してきておりますことから、比較的有効な活用ができていると考えているところです。有料の興行のような使用は少し少ないのですが、区内団体の方の使用、特に音楽団体の使用が好調だというのが近年の経緯です。","id":"exchange-078"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひとも音楽ホール、せっかくある施設ですから、有効活用をさらに進めていっていただきたいと考えております。東京オリンピック・パラリンピックを契機とした文化事業の推進の観点から、その点、どうお考えか尋ねました。","respondent":"鈴木文化観光課長","answer":"建物、文化センターはご存じのように改修をしてまだ比較的新しい施設ですので、大規模改修は近いうちに予定しておりません。ただ、必要な音響設備等については、老朽化も含め、適切に対応していきたいと考えております。","id":"exchange-079"},{"speaker":"筒井委員","kind":"質問・要望","question":"これは要望といたします。すなわち撮影業者が自発的に区に申し込まれている形なのか、また区が積極的に撮影業者に売り込みをかけているのか、そうした状況をお伺いいたします。","respondent":"鈴木文化観光課長","answer":"どこまで積極的にＰＲするかというようなところの調査をしていますので、現時点では、撮影サイドからの問い合わせに応じて支援するというのが基本となっているところです。","id":"exchange-080"},{"speaker":"筒井委員","kind":"質問","question":"今、どこの公園が人気なのでしょうか。すなわち撮影で多く使用されている公園というのは、何公園なのか尋ねました。","respondent":"今井土木管理課長","answer":"写真撮影の多かった公園ですが、平成２８年度はやはり水辺で、天王洲アイルの第二水辺広場ですとか第三水辺広場、第一水辺広場です。ロケーションもやはり天王洲アイルの第二水辺広場、東品川海上公園、そして第一水辺広場ということで、水辺です。","id":"exchange-081"},{"speaker":"筒井委員","kind":"質問","question":"そして、品川産業支援交流施設運営収入なのですけれども、５,６００万円、先ほどご答弁がありましたとおり、黒字です。すなわち収入をホール貸し以外で増やす方策の可能性というのはいかがお考えでしょうかということと、五反田バレーなど、いかがお考えか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"歳入が実は２億３,０００万円ほどありまして、３階ホールは、そのうち１億６,０００万円というような内訳になっているものです。","id":"exchange-082"},{"speaker":"飯沼委員","kind":"質問・要望","question":"過去最高の９０５億円にまで基金が膨れ上がっていますけれども、やめるべきであると思いますが、ここの見解を伺います。割合が３２.６％ということでしたが、ここがどう動いているのかの説明を求めました。","respondent":"秋山財政課長、伊東税務課長","answer":"予算を立てられないということは仕事ができないということです。決して基金を増やしたいがために予算を立てているとか、そういうことではないというのはご理解いただければと思います。４.７％ほど伸びておりまして、１１万４,０９５円という形になっており、平成２８年度が伸びている形になってあります。","id":"exchange-083"},{"speaker":"飯沼委員","kind":"質問・要望","question":"所得階層でどこの層が増えているのかと伺ったのですが、後で数字をほしいと求めましたので、よろしくお願いいたします。品川区の宝物と言える中小企業、この辺の見解をお聞かせいただきたいのと、予算の配分について総量規制というのを行われているのか尋ねました。","respondent":"秋山財政課長","answer":"この間、必要なものはやっているという、その結果だと認識しておるものです。その財源として基金を使って事業をするというのが私どもの考えですので、全く考えてもございませんし、これからもやるつもりはございません。","id":"exchange-084"},{"speaker":"大沢委員","kind":"質問","question":"７８ページから８１ページにかかる公の施設の使用料ということで質問させてもらいます。公の施設は区民の福祉に資するという大前提がありますけれども、この使用料について、基本的な算出の方法、考え方をまずの説明を求めました。","respondent":"柏原企画調整課長","answer":"公の施設、使用料の関係ですけれども、それぞれの施設は、条例に基づいて目的を持ってつくっているわけです。その中で、１平米当たり幾らというような基本的な単価を出しつつ、使用する側と運用する側の両方をあわせながら考えていくのが基本的なところです。","id":"exchange-085"},{"speaker":"大沢委員","kind":"質問・要望","question":"聞かせてほしいと求めましたが、なぜ手数料条例がありながら、の説明を求めました。","respondent":"柏原企画調整課長","answer":"使用料の考え方は、先ほど若干触れさせていただいたのですが、それぞれの施設は、個々の施設の目的といったものがあってでき上がっていると。ですので、使用料をひとまとまりにした形での条例ではないというところの違いというものです。","id":"exchange-086"},{"speaker":"大沢委員","kind":"質問","question":"なぜ規則で定めているのか。やはり社会情勢に応じながら、規則でそれをるる定めているのではないかと考えますけれども、それについてご答弁をお願いします。","respondent":"柏原企画調整課長","answer":"基本的な施設の使用料の考え方ですが、まず条例で基本的な部分を捉えてつくってあるです。例えば今おっしゃっていただいたようないろいろな変動があったり、そういったところも鑑みて、規則のほうで運用できる部分については委ねているです。","id":"exchange-087"},{"speaker":"大沢委員","kind":"質問","question":"見たところでは、７項目にわたって、減免することができる旨の規定が書いてあります。本来であれば条例に入れるべきだと私は思うのですけれど、なぜ条例に入っていないのかの説明を求めました。","respondent":"柏原企画調整課長","answer":"先ほどの減免等の考え方です。そういったところがありますので、その減免の考え方については規則のほうに委ねているという判断だです。","id":"exchange-088"},{"speaker":"大沢委員","kind":"意見","question":"時間があまりありませんが、仮にこの減免、免除までは結構ですけれども、ある程度、減免対象の範囲を狭める、規則を厳格化するとなった場合に、区としてはどのぐらい収入が増えるかについて見積もられていらっしゃるか、あくまでも仮にの話ですけれども、お答えくださいとの意見を述べました。","respondent":"柏原企画調整課長","answer":"今ちょっと手元に正確な数字はないのですが、一定程度の金額は確かに増えるというのは、その際に確認しています。全体を大きく変化させるような金額ではなかったと思いますが、減免の多い施設につきましては、ある程度の金額が増えるというのは記憶しています。","id":"exchange-089"},{"speaker":"大沢委員","kind":"質問","question":"確かに公の施設ですから、福祉的な要素は一番大事です。多少なりとも考えなければいけないところがあると思うのですけれども、そのあたりを区はどのように思っていらっしゃるのか、答えるよう求めました。","respondent":"柏原企画調整課長","answer":"ただ、同じ部屋を使うというところの受益者負担の考え方に立ったとき、施設ごとによって減免の考え方が違うというような部分があります。","id":"exchange-090"},{"speaker":"大沢委員","kind":"質問・要望","question":"使う場所については、同じ場所、スポットとしか見られない部分がある。あくまでも行政側の考えであって、一般の区民は、なぜ中小企業センターは使用料がこんなに高いのか教えてほしいと求めました。","respondent":"柏原企画調整課長","answer":"そういった理由に鑑みまして、使用料を設定させていただいている。使う方の考えもありますので、これはトータルの中で、どういうことができるかというのは検討したいと思います。","id":"exchange-091"},{"speaker":"浅野委員","kind":"質問","question":"７４ページの自動車取得税交付金、７５ページの交通安全対策特別交付金、それと時間があれば８４ページの住民基本台帳証明手数料について質問します。","respondent":"秋山財政課長","answer":"これは自動車の取得者に対する都税ということで、区市町村道の延長および面積で案分して区に交付されるというものです。自動車取得税交付金につきましては、一般財源扱いということで、使用の目的というのは一般財源に充当させていただいているというものです。","id":"exchange-092"},{"speaker":"浅野委員","kind":"質問・要望","question":"他区については少なめだとか、そのような差があるのかどうか、教えてほしいと求めました。品川区の全体からみた位置というのでしょうか、それについて教えてほしいと求めました。","respondent":"秋山財政課長","answer":"こちらは委員ご紹介のとおり、交通事故の発生件数等を指標に配分されるというもので、品川区は２３区中の１３番目という形になってあります。平成２７年度は１５番目、平成２６年度も１５番目で、そういう形で交付されているものです。","id":"exchange-093"},{"speaker":"浅野委員","kind":"質問・要望","question":"この８００円の原価といいましょうか、価格というのでしょうか、それについての考え方を教えてください。全体から言いまして何％ぐらいの方がカードを取得されているのか、教えてほしいと求めました。","respondent":"提坂戸籍住民課長","answer":"それから通知カードの再交付手数料５００円の考え方ですけれど、通知カードともに、紛失して再交付というケースが圧倒的に多くあります。現在のマイナンバーカードの交付件数ですけれども、８月末で４万７,０００余となっており、交付率は約１２％です。","id":"exchange-094"},{"speaker":"浅野委員","kind":"意見","question":"８月末で４万７,０００件、全体で１２％ということで、まだまだ少ないのかということかと思います。メリットが多いということもありますので、ぜひとも区民の皆さんにいい意味での宣伝をしていただいて、広めていってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-095"},{"speaker":"木村委員","kind":"質問","question":"先ほども、いながわ委員や松永委員のご質問にもありましたので、重複するかもわかりませんが、どうぞお許しください。もちろんこれは売り上げが落ちたことが原因ですけれども、なぜこの売り上げが落ちたのか、主な理由があればの説明を求めました。","respondent":"伊東税務課長","answer":"平成２７年度と比較しますと、売り渡し本数で言いますと約１,１２７万本ほど減少してございまして、収入に関しては先ほど委員のご指摘のとおりです。さまざま喫煙環境が厳しい状況だということで、減っているのかと考えています。","id":"exchange-096"},{"speaker":"木村委員","kind":"質問・要望","question":"せっかく品川区内で買っていただくのですから、喫煙できる場所というものを提供してあげるべきだと考えています。税収の一部を目的税として使うべきと考えますけれども、お答えをほしいと求めました。","respondent":"秋山財政課長","answer":"たばこ税につきましては、これは一般財源充当ということで、何度かご説明しています。ですので、施策の必要性の中で判断させていただいて、つくるかつくらないかを考えていくというところが基本だと考えております。","id":"exchange-097"},{"speaker":"木村委員","kind":"質問","question":"お聞きいたします。歯どめをかけるには、これからが一番よいタイミングだと思いますけれども、いかがか尋ねました。","respondent":"秋山財政課長","answer":"区としましても、そういうたばこに対する区民の皆様の認識というのをどういうふうに施策にあらわしていくかと考えているところです。そういう区民の方々のご要望ですとか社会的な状況というのを考えると、現状ではこういう施策を進めていこうです。","id":"exchange-098"},{"speaker":"木村委員","kind":"意見","question":"これから約３年後には東京２０２０大会が行われ、路上喫煙やポイ捨てをなくす努力をすべきだと考えています。最後でありますけれども、本区の所見の説明を求めました。","respondent":"秋山財政課長","answer":"どこかで折り合いをつけていただくというのが一番いいのですけれども、なかなか現状はそういうふうになっていないです。オリンピック・パラリンピック等により、どの方も気持ちよく過ごしていただけるよう、今後も努力してまいりたいと考えています。","id":"exchange-099"},{"speaker":"西本委員","kind":"質問","question":"あわせて基金のやりくりについてお聞きしますけれども、増額とする基金の決め方、目標値の設定というのはどうなっているのでしょうか。今、消費税についていろいろ議論があるようですけれども、その影響をどういうふうに考えていくのでしょうかということ。","respondent":"秋山財政課長","answer":"こちらで一緒にご説明しますと、公共施設の整備であれば、特別養護老人ホーム等で使っております。平成２７年度に入ってきてしまったので、平成２８年度は相対して見ると６.何％減っているという、東京都もそういうふうな説明をしているものです。","id":"exchange-100"},{"speaker":"西本委員","kind":"質問","question":"消費税が今後どうなるかわからないという状況においては、その方向性といいますか、品川区の手当てはどんなふうにしていくのでしょうか。そういう見立てがどこまでできているのか尋ねました。","respondent":"秋山財政課長","answer":"歳入が足りなくなるということで、歳出の額を落とさなければいけないということになりますので、そういうことはしたくないと考えています。東京都が出す、出さないにかかわらず、やっていきたいと考えています。","id":"exchange-101"},{"speaker":"たけうち委員","kind":"質問","question":"１０７ページの歳出の議会費についてお願いいたします。今期のメンバーで２年ということになりますが、それを教えていただくのと同時に、この間の取り組みの所管について伺いたいと思います。","respondent":"久保田区議会事務局長","answer":"続きまして、議会改革に対して事務局として意見等ですけれども、私も昨年の議会報告会は、前職の総務課長として会場にお邪魔させていただきました。","id":"exchange-102"},{"speaker":"たけうち委員","kind":"質問","question":"全国でいくと残念ながら２９３位と、この辺のところを事務局から教えていただいたわけですが、なかなか議会であまり褒められたことがないですから。","respondent":"久保田区議会事務局長","answer":"これはそれぞれの分科会の取り組みが評価されたものと私どもは認識しています。平成２３年から議会改革検討会のあり方検討、事務局として支えていきながら、さらに前に進めていければと思ってあります。","id":"exchange-103"},{"speaker":"たけうち委員","kind":"質問","question":"住民参加分科会を主体として、それでこれは同じ分科会に所属していた高橋しんじ委員から伺ったのですけれども、５つぐらいの自治体の一つに選ばれた。","respondent":"久保田区議会事務局長","answer":"そうした中で、そういった改革の成果等につきましては、やはり広く区民にＰＲしていかなければならないと考えています。第４回定例会の区議会だよりから、そういった区議会だよりなどの編集の中で、事務局としてもそういったことを支えていきたいと考えております。","id":"exchange-104"},{"speaker":"伊藤委員","kind":"確認","question":"成果報告書８７ページ、それから１０６ページ、それから平成２８年度歳入歳出決算の数字について質問します。先日、発行件数が品川区はたしか現在４万６,０００人と記憶しているのですけれども、非常に少ないということを確認しました。","respondent":"提坂戸籍住民課長","answer":"今週末の、しながわ夢さん橋でも配って、大いにＰＲをしていきたいと考えております。その辺は２３区の他の自治体と共同して、あと東京都にも入ってもらって、国にもＰＲをお願いしていきたいと考えています。","id":"exchange-105"},{"speaker":"伊藤委員","kind":"質問・要望","question":"この法律自体は国の全ての国民が対象でしょうから、１億１,０００万人、２,０００万人の方々が対象の事業ですから。品川区の災害対策やさまざまな場面で活かしていくところまで昇華していかないと、非常にもったいない気がするのですが、いかがか尋ねました。","respondent":"黒田人事課長","answer":"それで、派遣が終了しますと区に戻ってまいります。そういった経験を活かして、品川区の災害対策、それぞれの担当している仕事の中で活かしていると認識しているものです。","id":"exchange-106"},{"speaker":"伊藤委員","kind":"質問","question":"体験してきたわけですから、それを危機管理や、いろいろな分野に活かせるはずです。だから、それを、何というか、もっと具体的にリアルに活かす仕組みをつくってあげないことにはもったいない気がするのですが、いかがか尋ねました。","respondent":"黒田人事課長","answer":"いわゆる窮状という意味で、区民の方と接するのとは違う状況というのを見聞きしているということは、私もヒアリングの中で聞いております。新たな政策としてそういった職員が何か発信できないかということについては、今後検討していきたいと考えています。","id":"exchange-107"},{"speaker":"伊藤委員","kind":"質問","question":"３・１１震災の語り部がいらっしゃいます。品川区の行政の中に十二分に活かすシステムを構築すべきではないでしょうかということをあえて質問しますので、答弁を。","respondent":"黒田人事課長","answer":"さまざま今、委員からご指摘がありましたような情報共有につきましては、職員のほうに共有できるような体制をつくってまいりたいと思います。そういった貴重な体験を共有できるような体制については今後も検討してまいりたいと考えています。","id":"exchange-108"},{"speaker":"伊藤委員","kind":"質問","question":"ここで、「確定しない」と出ているわけですが、このケースはどういうふうに考えればいいのでしょうかということをお伺いしたいです。いかがか尋ねました。","respondent":"久保田区議会事務局長","answer":"これにつきましては、決算上は特に問題がないということでございまして、政務活動費に関しましては四半期ごとに支給しているというものです。もしそれが、修正等があって戻入されるということであれば、平成２９年度の雑入として取り扱うということを確認しています。","id":"exchange-109"},{"speaker":"伊藤委員","kind":"確認","question":"確認ですけれど、円単位で出ている決算書なのです。だから、成果報告書１０７ページにある政務活動の金額はこれでいいのでしょうかという確認と、どういう会計処理がなされるのでしょうかということ。","respondent":"久保田区議会事務局長","answer":"それ以外の会派の方々の金額を確定して報告しているということが１点あります。戻入がございませんので、そこに差額はないとして、支出した金額をこちらに計上させていただいているというものです。","id":"exchange-110"},{"speaker":"伊藤委員","kind":"確認","question":"つまり、成果報告書１０７ページにあるこの数字については、そういうことも踏まえた上で編成されたものであるということの確認でよろしいか尋ねました。","respondent":"久保田区議会事務局長","answer":"現時点としては、この数字が正しいものです。私どもも、今、当該の方といろいろと話をして、報告書の修正等をお願いしているという状況です。","id":"exchange-111"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"８６ページの国庫負担金と、それから９２ページの都負担金で、ともに国民健康保険について伺いたいと思います。お願いします。","respondent":"三ッ橋国保医療年金課長","answer":"そちらを被保険者数で割りますと、１人平均では約２,０００円となっております。差し押さえ件数ですけれども、約８３０件となっております。","id":"exchange-112"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"国から出されている１,７００億円の保険者支援金というのは、そのまま出ることになるのか、その見通しについてもお聞かせほしいと求めました。その分の値上げ額というのは１人平均幾らになるのかについてもお聞かせほしいと求めました。","respondent":"三ッ橋国保医療年金課長","answer":"今のところの見通しですが、こちらはそのままの予定と見通されてあります。国や都の動向を踏まえながら検討してまいりますが、できる限り保険料が上昇しないように、区といたしましても検討してまいります。","id":"exchange-113"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"４,８００円、一気にぼんと上がってしまうわけですから、これもそのまま続けていただきたいということを強く要望したいと思います。","respondent":"三ッ橋国保医療年金課長","answer":"法定外繰入金につきましては、今、品川区では、統一保険料方式を用いておりますので、そちらも２３区、特別区全体として考えてまいりたいと思います。滞納世帯数ですが、今、平成２８年度末で１万１,０００世帯となっております。","id":"exchange-114"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は子どもの保険証は無条件に支給していただきたいと思っているのですけれども、窓口にとめ置きという状況になっていると思うのです。子どもはやはりいつ病気になるかわからないので、ぜひそれを、無条件で送っていただきたいと思うのですけれど、いかがか尋ねました。","respondent":"三ッ橋国保医療年金課長","answer":"今現在のところ、短期証ですけれども、そちらはまずはご病気のお子さんに関してはすぐに出すようにはしております。しかしながら、収納、全体の中で考えますと、なかなか難しい部分があります。","id":"exchange-115"},{"speaker":"若林委員","kind":"質問・要望","question":"９８ページの、都の補助金になりますが、空き家利活用等区市町村支援事業補助金をお聞きしたいと思います。これについて、決算金額の内訳とともにお教えほしいと求めました。","respondent":"長尾住宅課長","answer":"空き家利活用の補助金の件です。こちら、国の補助金について公的な利活用を想定しまして、２件分、予定していたものになっております。","id":"exchange-116"},{"speaker":"若林委員","kind":"質問","question":"そこで、国のほうの法律では、「空家等対策の推進に関する特別措置法」が平成２７年に施行されました。国において、この大きな２つの法律がある中で、都の要綱との関係というのはどういうふうになっているのかということもお聞きしておきたいと思います。","respondent":"長尾住宅課長","answer":"こちらにつきましては、住宅セーフティネット法の中でも、空き家の利活用というところは１つの方策として挙げられております。共通する部分もあると考えていますので、２つの法律については両方、検討しています。","id":"exchange-117"},{"speaker":"若林委員","kind":"質問・要望","question":"今回平成２８年度で実施された事業としては空き家相談体制整備という項目になるのかというのを１つ確認と、５つ目に老朽空き家除去等。なぜ今回、その他の５つについて補助を申請しなかったのかという理由を１つお聞きするのと、その流れについて今後も含めてお聞きします。","respondent":"長尾住宅課長","answer":"実態調査につきましては、平成２６年度、平成２８年度と、過去２回実施しており、こちらの補助も受けているところです。現段階では事業として実施しておりませんが、今後の対策計画の策定の中でも必要性等を検討していきたいと考えております。","id":"exchange-118"},{"speaker":"若林委員","kind":"質問・要望","question":"最後に、今、課長からもありました空き家等対策計画、これは平成２９年度中に策定予定というふうに既に説明があります。見通しが立たれているのか、今後のスケジュールにつきましても、順に教えてほしいと求めました。","respondent":"長尾住宅課長","answer":"こちらは今までの取り組みの内容につきまして、わかりやすくご理解いただくためのツールとしても使えるように作成を進めているところです。今後の進捗を見まして、必要に応じて計画の改訂なども行いながら、盛り込むことも検討してまいりたいと考えています。","id":"exchange-119"},{"speaker":"本多委員","kind":"質問","question":"成果報告書８９ページ、再開発によってエリア周辺地域が発展されることを望み、質問いたします。この竣工について、全体についてどう捉えているのか、現況を示すよう求めました。","respondent":"稲田都市開発課長","answer":"これが予定より遅れておりまして、平成３４年２月に仮に開通できるのではないかというところで、進めております。約４年１カ月強の遅れで、建物の完成後になってしまうという状況です。","id":"exchange-120"},{"speaker":"本多委員","kind":"質問","question":"今、答弁いただいた補助１６３号線の新幹線などのガード下、狭隘部分にトンネルをつくる予定でした。そもそもの最初の竣工の予定と、今のお答えいただいた竣工の予定でどのぐらいの差があるのか、詳しく教えてほしいと求めました。","respondent":"稲田都市開発課長","answer":"補助１６３号線の拡幅工事ですが、これは当初の予定では、あわせてこの道路も完了していくというところで進めておりました。当初の予定では、見込みですけれども、２年ぐらいで完成するのではないかという見解がございました。","id":"exchange-121"},{"speaker":"本多委員","kind":"質問・要望","question":"大幅に遅れてしまうということなのですが、電気等が生きたまま移設するのでしょうか。その辺を少し教えていただきたいのと、どうしても重なってしまうので、その辺だけの説明を求めました。","respondent":"稲田都市開発課長","answer":"そういう中におきまして、バックヤードの件については、再開発組合とＪＲが、工事施工ヤードについては協議してきました。ただ、工期を縮めるというところにおきましては、区も、このヤードの使い方をもっと効率的にできないかなどの指導はしてまいったところです。","id":"exchange-122"},{"speaker":"本多委員","kind":"質問・要望","question":"電気が生きたままというのは、電車がとまっている時間しか工事をする時間がないという理解でいいのでしょうか。車の動線と、２つに分けて課題があるかと思うのですが、その辺はどういうふうに捉えているのか尋ねました。","respondent":"稲田都市開発課長","answer":"そういうところにおいては率先してやっていこうというところで、現在、調整等を進めております。地域の皆様にはご迷惑をかけるということで、今後も沿道の方々にはご理解いただけるようなお話し合いをしながら進めてまいりたいと思います。","id":"exchange-123"},{"speaker":"本多委員","kind":"質問・要望","question":"今のご答弁は、別の動線として、補助１６３号線に並行した、１本中に入った道の活用で、そちらを歩いてくださいということなのでしょうか。百反坂下の歩道橋みたいなデッキ等をスピーディーにつくれないかという要望も出ておりますが、人の動線、その点はいかがか尋ねました。","respondent":"稲田都市開発課長","answer":"今後もよりよい対策がとれる方法を見つけながらやっていきたいとは考えております。そういうところも今、検討しているというところでございまして、何らか、区も入りながら、よりよい対策を考えていきたいと考えております。","id":"exchange-124"},{"speaker":"本多委員","kind":"質問・要望","question":"何かいい方法がないか、今考えていますので、一緒に考えていってほしいと求めました。今は亡き金丸衆議院議員や地元の国会議員が最終的に動いて決定づけたということも伺っておりますので、ＪＲ相手に難しいというのは十分わかりますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-125"},{"speaker":"高橋（し）委員","kind":"意見","question":"先に１０１ページの基金の繰り入れのほうをお尋ねします。インフラの対策として経費が毎年どれぐらい必要になるのかということが計画等で算出されていると思うのですが、その点、お尋ねいたしますとの意見を述べました。","respondent":"秋山財政課長","answer":"１点目、公共施設の整備基金ですけれども、一応、施設の耐用年数等を踏まえて、毎年の改築の必要額が合計で、２０年間で３５０億円程度と見込んでございましたので、１年にすると大体１８億円ぐらいですか、そういうふうに見込んでおったところです。","id":"exchange-126"},{"speaker":"高橋（し）委員","kind":"確認","question":"十数億円ということですから、義務教育施設の基金で、この基金で果たして対応しているかどうかというお話になるわけです。これは４１.１％ということで、約４割が老朽化ということなのですが、これは幾らになるのか尋ねました。","respondent":"秋山財政課長","answer":"平成２７年度の決算の中の減価償却累計額です。１,６６９億２,５１７万５,０００円という形で、これが老朽度をあらわすということで、資産老朽化比率の計算のもとになっている数字です。","id":"exchange-127"},{"speaker":"高橋（し）委員","kind":"質問","question":"そこで新公会計制度を導入して、減価償却累計額は算出されていくのですが、今の数字よりももっと多くなっていくのでしょうか。そして、その金額と、基金、インフラ整備との関係について、私は簿記についてほとんど素人ですので、わかりやすくご説明ほしいと求めました。","respondent":"秋山財政課長","answer":"今まさにつくっているところですけれども、更新していきますと、この１,６７０億円余の額が基本的には増えると考えています。これをしっかり確保していくことが、財政運営上、必要なことではないかと考えています。","id":"exchange-128"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"先ほどの減価償却費の本来数字も出てくるということで、適切な基金の積み立てと運用をし、インフラに結びつけていってほしいと求めました。この点についてはいかがか尋ねました。","respondent":"秋山財政課長","answer":"財源の構成として特定財源等が充てられる部分があるかと思いますので、全額が一般財源負担ということではないとは考えてあります。そこはしっかり考えながら、将来のそういう負担についてしっかりと応えられていくような財政運営を今後していかなければいけないと考えております。","id":"exchange-129"},{"speaker":"高橋（し）委員","kind":"意見","question":"今お話しいただきましたが、将来の負担については、本当に十分検討していかなければいけないということですので、ぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-130"},{"speaker":"石田（し）委員","kind":"質問","question":"それと２３７ページ、総務管理費の一般管理費について、９６ページの就業機会拡大支援事業補助金についてお伺いします。それと、就業機会拡大支援事業補助金ですが、これはどのような事業を行っているのかの説明を求めました。","respondent":"矢木生活福祉課長、米田危機管理室長、山崎商業・ものづくり課長","answer":"生活保護費の減の主な理由ですが、こちらにつきましては、扶助費の減が主な理由になっております。災害支援の対策本部等に照らして、見舞金を贈呈するのにふさわしいかというようなことを決定し、支給しているものです。就業機会拡大支援事業につきましては、あるいはシルバー人材センターで確保する企業に働きかけ、支援するという目的で補助金があります。","id":"exchange-131"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"どのぐらいの金額等を出すのかというのも含めて、一定の基準を持つべきかと思うのですが、その考え方を持っていらっしゃるかどうかお知らせください。そういった支援をぜひ行っていただきたいと思うのですが、その点、どのように考えているかの説明を求めました。","respondent":"矢木生活福祉課長、米田危機管理室長、山崎商業・ものづくり課長","answer":"高校３年生までの就学支援ということで、塾代の支援と、あと高校３年生の受験料の支援ということを。被害の状況ですとか、あるいは区と今どれぐらいの関係があるのかというようなことに照らして支出しているものです。就業機会の拡大につきましては、区の就業センター、これはもともと国の機関のハローワークと連携しながら対応しております。","id":"exchange-132"},{"speaker":"石田（し）委員","kind":"質問","question":"いわゆる保護世帯の大学の進学率が１９％、これは全体の５２％を大きく下回るわけで、改めて品川区としてどのように考えているのか。どうやって大学に進学し、大人になったときにしっかり働くことができるのかというのを、どのように考えているのか再度の説明を求めました。","respondent":"矢木生活福祉課長","answer":"国全体で、大学に進学するのが全てのお子さんに対して一般的であると認識される段階になりますれば。ただし、今後の国等の推移を見守ってまいりたいと思います。","id":"exchange-133"},{"speaker":"安藤委員","kind":"質問","question":"一方で、傾斜型家賃形態をとっているのは５棟ですけれども、それぞれの入居率を伺います。あわせまして、売払収入のほうですけれども、この不動産売払収入７,３６７万円の内訳は何かも伺います。","respondent":"長尾住宅課長、立川経理課長","answer":"ファミーユ小山が７３％、ファミーユ大井が５３％、ファミーユ旗の台が約７０％という数字になります。普通財産の売り払いですけれども、全部で１５件ございまして、主なものといたしましては、西五反田五丁目の寄附物件、その他、大崎二丁目の旧水路敷地等です。","id":"exchange-134"},{"speaker":"安藤委員","kind":"質問","question":"区民住宅のほうですけれども、傾斜型住宅の入居率が少し低いと思うのですけれども、区は低いとお考えでしょうか。ファミーユ南大井だけ入居率が高くなっている理由は何か伺います。","respondent":"長尾住宅課長","answer":"は区営住宅の建て替えに伴う仮移転の方を除いた数値で見ますと、ファミーユ西品川につきましては、数値としては低いかと考えています。ファミーユ南大井につきましては、一部まだ家賃助成が残っている点もあり、入居率９１.１％ということで高いと捉えております。","id":"exchange-135"},{"speaker":"安藤委員","kind":"質問","question":"傾斜型というのは２０年で毎年３％上がり、フラット型は１５年後に一気に家賃助成が終了すると。フラット型の家賃助成が終了すれば、転出者も出てしまうということになるのではないかということについて、伺いたいと思います。","respondent":"長尾住宅課長","answer":"入居率につきましては、家賃助成の有無だけではなく、立地であるとか、あと広さ、間取りといったものを含めまして変動してくるものと考えておりますので、必ずしも家賃助成が終わったからといって入居率が落ちてくるとは考えておりません。","id":"exchange-136"},{"speaker":"安藤委員","kind":"質問","question":"１２万９,０００円からいきなり１７万１,０００円と毎月なったら、これは退去というか、もう住みかえるしかないと考えると思うのです。","respondent":"長尾住宅課長","answer":"こちらは委員のおっしゃるように、家賃助成を受けている世帯の中には家賃が最大で４万円強の上昇が見込まれる世帯もあります。皆様にご説明しながらご入居していただいているところですので、ご理解いただいているものと考えております。","id":"exchange-137"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いたいのは、どんな協議をしているのか伺いたいというのが１点。仮に売り払うとしたら、およそ売払収入は幾らになると見込んでいるのか伺います。","respondent":"柏原企画調整課長","answer":"その細かい部分につきましては、この場で詳細の部分を答えることはできないですけれども、流れとしてはそれが普通の流れと考えています。スケジュール感等々につきましても、そういったところの流れの中で、今後、内容というのが見えてくるのだろうと思ってあります。","id":"exchange-138"},{"speaker":"安藤委員","kind":"質問","question":"２つお伺いします。ではなくて、もう区有地を道路のために売るという考えがあるのか、ないのか、お伺いします。","respondent":"柏原企画調整課長","answer":"場所がどこというよりは、区としても事業に対して、打診があった際には協力を考えていきたいというお話をしたものです。それで交渉して、実際に物件に対してどういう話になってくるかというのは、今後、交渉の流れの中で見えてくるのだろうと思ってあります。","id":"exchange-139"},{"speaker":"安藤委員","kind":"質問","question":"その当時のやりとりの中に大崎図書館という名称は一切出てこなかったということなのでしょうか。そこをはっきり、答えるよう求めました。","respondent":"柏原企画調整課長","answer":"繰り返しのご答弁になりますけれども、当時は、補助２９号線道路の事業に対して協力をいただけないかということで、区有地も含めて、協力できるところについては協議しながら協力したいと申し上げたところです。","id":"exchange-140"},{"speaker":"こんの委員","kind":"確認","question":"８１ページ、１０２ページの諸収入の歩行喫煙防止過料に関連して、この２点からお伺いしたいと思います。まずその確認が１点と、もう一つ確認で、そのグループホームの支援事業の目的を確認したいと求めました。","respondent":"中山障害者福祉課長","answer":"グループホームの運営者への支援というところでは、平成２７年度に行いました、そういったことが区の支援としてあるところです。その目的ですが、やはりグループホームを区内にもう少しつくっていきたいということで、そうした事業者への支援も行っているところです。","id":"exchange-141"},{"speaker":"こんの委員","kind":"意見","question":"そうすると、現状、この利用者の方々に助成が行われていると思いますが、収入によって助成額が違うと思います。その助成額の内訳をお願いしたいと思いますとの意見を述べました。","respondent":"中山障害者福祉課長","answer":"家賃助成というところでは、国の補足給付で月１万円というものがあります。それから７万３,０００円から９万７,０００円の所得の方であれば２,０００円の補助ということで、３段階の補助をしています。","id":"exchange-142"},{"speaker":"こんの委員","kind":"質問","question":"今まで国と都の補助金が入っていると理解していたのですが、そうではなく区の単費で、独自で補助金を出しているということなのですか。そこをもう一度お願いします。","respondent":"中山障害者福祉課長","answer":"国の１万円というのは、国の負担になります。１万４,０００円と２,０００円という、所得に応じて２段階の補助金は区の単独ということで、どこからも特定財源は入っていないものです。","id":"exchange-143"},{"speaker":"こんの委員","kind":"質問","question":"いわゆる家賃に対して、そしてご自分で生活をしていくという、非常になかなか厳しい現状の中でやりくりをされているというお声も伺っています。品川区は入れていないというお話もあったものですから、区の単費で入っていて、都の助成金は使っていないということなのか尋ねました。","respondent":"中山障害者福祉課長","answer":"多分、区の制度が平成１６年度にできていますが、そのときに都の制度から区の制度に変わっているのではないかと思います。以前は国の制度と東京都の制度だったものが、現在は都の制度ではなく、区のほうで単独の補助をしています。","id":"exchange-144"},{"speaker":"こんの委員","kind":"質問","question":"わかりました。このような、私が申し上げた区民の方の声がありますが、そのことについてはどのようにお考えになりますか尋ねました。","respondent":"中山障害者福祉課長","answer":"やはりなかなか、福祉的な就労ですと、収入を得ることが難しいという方もいらっしゃいます。お一人お一人のお声を聞きながら、どういった支援ができるのかというのは、総合的な視点から考えていきたいと考えております。","id":"exchange-145"},{"speaker":"こんの委員","kind":"質問","question":"どうか、あそこには設置しないでほしいという声も具体的に出ておりまして、場所を考えていただくというのが１つあろうかと思います。公園内ということが条例でうたわれている中ですので、どうかご検討をお願いしたいと思います。","respondent":"溝口公園課長","answer":"公園利用者の方はさまざまおります。そういった、さまざまな意見を聞きながら、今後の公園のあり方というのを考えていきたいと思っているものです。","id":"exchange-146"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私からは、８７ページ、国庫補助金、９３ページ、都補助金、宝くじの助成金等、補助金や助成金に関連してお伺いしたいと思います。直接、こういうことを行っていこうとして補助金等を申請しているという団体等を把握されていると思うのだけど、その辺を教えていただきたい。","respondent":"鈴木文化観光課長","answer":"団体からする場合に、地元の自治体の政策との整合性ということで、推薦なり同意書なりというのを添付するケースが多くなっております。その場合に、同意なり推薦なりの書類をお渡しするということで、その場面で把握できている事業が数事業あります。","id":"exchange-147"},{"speaker":"石田（秀）委員","kind":"意見","question":"その９団体の方々が、目的は１つで、一応はまとまった。そういうことができた中で、ではこれを行ったことは評価としてどうでしたかというところでとめますとの意見を述べました。","respondent":"鈴木文化観光課長","answer":"私も２日間、会場を拝見しましたが、何よりも一番よかったのは、地域の方が主体になって、また複数の団体が連携して実施していただいたです。","id":"exchange-148"},{"speaker":"石田（秀）委員","kind":"意見","question":"ぜひ区も一緒になってやっていただければ、１０年後、２０年後にいい組織になっていく。９団体の方などと真面目に話をして議論しているわけで、その継続の部分をぜひ改めてお願いしたいのですが、との意見を述べました。","respondent":"鈴木文化観光課長","answer":"今ご指摘のあったように、都のこれまでの観光事業支援については、地域の皆様からの支援の課題や希望について伺ってきたところです。今年度開始しました観光支援事業については、継続して、今後も地域のさまざまな取組みを継続して支援するということで。","id":"exchange-149"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"東京都、それから国の補助金があるのかどうか、その辺のところも含めて一緒にやっていただきたいというのが１点です。ではこういう部分は変えていこうというような話を、品川区発信でやっていただきたいと思っているのですが、その部分についても。","respondent":"今井土木管理課長","answer":"そういうものを地上に出すものの活用などを、今、上野公園で社会実験的にやっていると聞いております。今後、屋外広告物条例の第３０条の特例許可などを活用しながら、地域の声を聞きながら進めていきたいと考えています。","id":"exchange-150"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"我々も全力で努力しますので、区の皆様も、それをぜひよろしくお願いします。これは要望で終わります。","respondent":"鈴木（真）委員長","answer":"以上をもちまして、本日予定の審査は全て終了いたしました。","id":"exchange-151"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/392487?Template=document&Id=1436#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":116025,"voices":361}},{"id":"h29-20171003-4","meetingId":"h29-c-settlement","date":"2017年10月3日","dateIso":"2017-10-03","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時１５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を153件整理しています。","topics":[{"id":"topic-01","title":"◯鈴木（真）委員長 ただいまより、決算特別委員会を開きます。 それでは、平成２８年度品川区一般会計歳入歳出決算","agenda":"◯鈴木（真）委員長 ただいまより、決算特別委員会を開きます。 それでは、平成２８年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"横山委員","kind":"質問・要望","question":"ギャラリーなどの情報をさらに充実させ、１つの周遊コースとして位置づけるなどを進めていただきたいと考えますが、いかがか尋ねました。","respondent":"鈴木文化観光課長、仁平情報推進課長、木村報道・プロモーション担当課長、遠藤協働・国際担当課長","answer":"さまざまな区の魅力を発信していただいているのは非常によい事業だというふうに考えておりまして、区としても支援をしています。区のイベント情報を提供することによって、区民の方がそのデータを使いやすいような形、こういう形には持っていきたいと考えています。今、情報推進課長からもございましたように、ある意味、ホームページは、いわゆるオープンデータの固まりです。イベント情報につきましては、基本的に各団体が入力することで、新着情報なり、カレンダーなりという形で表示されることになっております。","id":"exchange-001"},{"speaker":"横山委員","kind":"質問・要望","question":"平成２８年第１回定例会の一般質問で、花火大会の実施を要望しておりましたが、大変うれしく思っております。訪れた方々にも、そういった水辺の観光フェスタをぜひ今後も続けていただきたいと思いまして、４つのポイントについて区のお考えの説明を求めました。","respondent":"鈴木文化観光課長","answer":"それから２点目の五反田などの各エリアをつなぐ手段ですが、地域の皆さんと一緒に考えていきたいというふうに考えております。それと４点目の高齢者の方や障害のある方への配慮、そのための支援、その辺で協力をしていきたいというふうに考えております。","id":"exchange-002"},{"speaker":"横山委員","kind":"質問・要望","question":"区民の皆様にとって有益な情報を確実に届けるために、広報紙、区報の発信力を強化していく段階にあるのではないでしょうか。広く情報を掲載するために、発信すべき情報量、現在の発行数、ページ数の適正化について、区のお考えの説明を求めました。","respondent":"中元広報広聴課長","answer":"確かにバリアフリー法に対応いたしまして、やはり紙面上、ちょっとそろそろ物理的な難しさも出ているところです。今後に向けましては、少し検討していく時期に来ているのかと考えています。","id":"exchange-003"},{"speaker":"横山委員","kind":"質問・要望","question":"そういった要望などもお聞きしておりますので、ぜひ柔軟に対応して検討を進めてほしいと求めました。そういったような視点でお考えいただきたいと思っているのですけれども、品川区の行政サービスのブランディングの考え方についての説明を求めました。","respondent":"中元広報広聴課長","answer":"品川区では、各課における行政サービスを区民の皆様にわかりやすくお伝えをしていくということで取り組んでおります。一段とそれを前に進めて、見る方のお気持ちを考えながら、これからも工夫をしていくように広報広聴課からも各課に啓発をしてまいりたいと思います。","id":"exchange-004"},{"speaker":"横山委員","kind":"意見","question":"これは私でも受けていいサービスなのだというような形で受け取りやすい、イメージアップの推進、これからも進めていただけたらと思います。最後に一言お願いしますとの意見を述べました。","respondent":"中元広報広聴課長","answer":"従来から、基本デザインアドバイス事業なども行っておりますので、今後もそのような専門家のアドバイザーの力等もかりながら、職員のそのようなデザインの力というもの、情報発信力を高めていくように周知啓発等に努めてまいりたいと思います。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問","question":"２点目に、マンションへの加入促進はどのようにされて、どういう成果があったのかお伺いいたします。３点目に、若い世代の加入促進において取り組まれたことは何か伺います。","respondent":"伊崎地域活動課長","answer":"なかなか１年で数字が明確に出るということは難しいと考えておりまして、おっしゃるとおり、長期的なスパンで考えております。それから、例えば、若い方々向けのものをやっていただくということを区民まつりなどを通じてご案内いただくなどということで進めております。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問","question":"大阪の松原市では、この自治会に加入をしやすいようにということで、４コマ漫画で町会の加入を呼びかけております。子どもへの意識啓発、そして親子で語れる町会・自治会ということで活用されてはと思いますが、いかがか尋ねました。","respondent":"伊崎地域活動課長","answer":"失礼いたしました。それを通じて町会・自治会を知っていただくということも働きかけておりますので、ご意見を参考にしながら、ますます進めていきたいと思います。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"続いて、選挙費について伺います。今後も継続してアトレで行うのか、また、この直近で衆議院選挙がありますけれども、衆議院選挙での考え方も教えてほしいと求めました。","respondent":"安井選挙管理委員会事務局長","answer":"先方でも検討していただいたのですけれども、今回につきましては難しいということで、開設は見送ったところです。逆に、ほかの期日前投票所を紹介していただくような案内を立てていただくとか、そういうことで協力はするというふうにお話を伺っているところです。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"もう１点、選挙に関して伺います。「点字用の候補者一覧がありますか」と確認をしたところ、３０分待たされた上に、そういう返答だったそうであります。","respondent":"安井選挙管理委員会事務局長","answer":"地域センターでの対応をこの場でお詫び申し上げます。でき上がり次第、我々の職員がそのまま持って帰ってくるというような形で、より時間を縮めて早期に対応できるようにしているというのが実態です。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"丁寧に確認をされた上で、このことも含めて、対応をしっかりと短時間で確認ができるような体制もしっかり整えてほしいと求めました。ここら辺の考え方とか、また、助成を拡大をしていただくとか、こういうお願いをできるのか伺いたいと思います。","respondent":"菅生活安全担当課長","answer":"例えば電柱の無電柱化とか、あるいは道路の拡幅工事など、これは１件当たり１０万円を上限として助成するというような制度があります。地元の皆様のご意見をいただきながら、区として何かできるかどうか、調査研究をしてまいりたいというふうに考えております。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"確認をしましたら４０枚ぐらいありました。一言、「大事なお知らせが入っています」ということをぜひご案内いただきたいと思うのですが、いかがか尋ねました。","respondent":"米田総務課長","answer":"成人式実行委員が選定した記念品については説明があったかと思いますが、あわせて他の配布物についても案内するように実行委員会で確認していきたいと思います。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"私からは、成果報告書１１０ページの人権啓発費より、男女共同参画社会についてお伺いしたいと思います。そして、その実現のためには、特にセクシャルマイノリティにかかわって何が大事なのかお伺いしたいと思います。","respondent":"島袋人権啓発課長","answer":"男女共同参画センターにおきましては、そのようなマイノリティの方たちを含めたカウンセリング相談等も既存の相談事業の中で行っております。こちらの広報をしっかりとやってまいりたいと思っているところです。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"本当にそのとおりだと思います。まだまだそうなっていないというところで、セクシャルマイノリティの方がなぜこんなに社会で生きづらいのか、品川区の見解を伺いたいと思います。","respondent":"島袋人権啓発課長","answer":"職場や学校で性的少数者について差別的発言を聞いたことがあるという方は、かなりのパーセントでおられるという現実もあるようです。そのような方々も来ていいのだ、安心してこういったところで相談ができる場所があるのだというところを広めてまいりたいと考えているところです。","id":"exchange-013"},{"speaker":"中塚委員","kind":"提案","question":"世田谷区では、これも参考にアンケート調査を検討してほしいと求めましたけれども、１点伺いたいと思います。このセクシャルマイノリティにかかわる相談件数について、近年では何件ぐらいあるのか、どのように周知を行っているのかお伺いしたいと思いますとの意見を述べました。","respondent":"島袋人権啓発課長","answer":"なお一層の広報活動を進めてまいりたいと思っているところと、区民の皆様の交流室を通じての環境整備等も考えていくことが重要なのかと考えています。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"そろそろ４色刷りにして、内容も見やすさも充実してほしいと求めましたけれども、この点を伺いたいと思います。他区の事例も参考にしながら、品川区でも作成を進めてほしいと求めましたが、いかがか尋ねました。","respondent":"島袋人権啓発課長","answer":"確かに来年度に、内容の検討等をこちらも考えているところなので、参考にさせていただきたいと思います。こちらも第５次の行動計画、あるいは協議会の中でのご提案を受けつつ、反映していけるように検討してまいりたいと考えているところです。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"例えば品川区のツイッターなどを使って、また、この点はいかがでしょうか。このセクシャルマイノリティの事業が男女共同参画センターにあることそのものを知らない人がまだ多いですから、例えば、いかがか尋ねました。","respondent":"島袋人権啓発課長","answer":"私どもも男女共同参画月間が６月に開催されておりますので、それをまず今年は知っていただくために、ホームページ上でもお知らせしたところです。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"支援の実施を位置づけてほしいと求めましたが、この点伺いたいと思います。支援の強化、こうした方向性をしっかり改定の中で明記してほしいと求めましたが、あわせていかがか尋ねました。","respondent":"島袋人権啓発課長、柏原企画調整課長","answer":"第５次の検討に入るというところで、多様性を尊重するという章を１つ起こすことによって、いろいろな方々が含まれるかと思います。その中での対応が重要かと思いますので、検討していきたいと思っているところです。次にどうやって進めるかの検証を行うべきもの、今後、検討していきたいというふうに思ってあります。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"さまざまな理解促進や支援の方向性、そこをしっかりと改定の中で位置づけていただきたいと思うのですけれども、その方向はあるのでしょうか。お伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"行政の中ではさまざまな課題等々があります。そういった中で、今、検証作業を行っている中で、さまざまな課題に対して検証しながら、新しい計画に向けて検討を進めていきたいというものです。","id":"exchange-018"},{"speaker":"木村委員","kind":"質問","question":"私からは、１０９ページの下から５行目、国際交流推進事業、９,２６６万円余からお伺いします。質問ですけれども、学校や日常生活での成長、また変化を感じるようなことがあるかどうかの説明を求めました。","respondent":"遠藤協働・国際担当課長","answer":"国際交流事業についての子どもたちの考えといいますか、対応というところなのですけれども、交流事業をさせていただいているところです。３都市全てに中学生、いろいろな話をいただいているところですので、大変重要だったかというふうに考えております。","id":"exchange-019"},{"speaker":"木村委員","kind":"意見","question":"ニュージーランドのオークランド市、そして教育交流都市の中国のハルビン市と、本区では４カ国との交流があるということであります。姉妹都市や友好都市、そして教育都市など、これからも増える可能性があるのかどうかについての説明を求めました。","respondent":"遠藤協働・国際担当課長","answer":"それからジュネーブ市とオークランド市について友好都市という形で進めさせていただきまして、現在、特におつき合いがないような状況です。","id":"exchange-020"},{"speaker":"木村委員","kind":"質問","question":"３４６万円余からですけれども、区民一人ひとりの心に平和の芽が根づいていくことを願っています」と平和の花壇に込めた思いを述べられています。","respondent":"米田総務課長","answer":"５年に一度は周年の記念の事業ということで、もう少し規模を広げてということで、平和事業に取り組んでいるものです。今後もこの非核平和都市品川宣言に基づいて、品川区としての草の根の非核平和の思いを今後も推進してまいりたい、このように考えてあります。","id":"exchange-021"},{"speaker":"木村委員","kind":"質問・要望","question":"高齢者が生きがいを求め、充実感のある人生を過ごしたい、残りの人生を裕福な心で過ごしたいと入学するということを聞いております。お聞きいたしますけれども、そして数年後の卒業生の調査に対しては、区として何か行っているのかどうかもの説明を求めました。","respondent":"鈴木文化観光課長","answer":"加入をいただくことで、継続した地域での活動、それからシルバー大学での講座のスタッフとしてのお手伝いなどをいただいているところです。その中でいろいろな活躍なり、役割を担っていただいていることから、特に調査などは行っていないというのが現状です。","id":"exchange-022"},{"speaker":"木村委員","kind":"質問・要望","question":"逆に、そのような知識は大変大事なことであるということで、またいろいろとこの事業が進むことを願っております。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"藤原委員","kind":"質問","question":"１０８ページの職員の給与でまずお伺いしますが、再任用の制度について教えてください。１０９ページ、文書関係事務費とは何なのですかというのと、平塚二丁目の物件の改修費がなぜここに出てくるのか教えていただけますか。","respondent":"黒田人事課長、米田総務課長","answer":"私から、再任用の制度についてご説明いたします。２３区の職員が加入しています特別区の互助会のほうで、結婚相談という事業を互助会の事業として行っているもので、職員の制度としてあるものです。平塚二丁目でいただいた物件を文書倉庫として整備する際に、文書棚を購入して、その経費をこちらのほうに計上させていただいているものです。","id":"exchange-024"},{"speaker":"藤原委員","kind":"質問・要望","question":"管理職の方と一般職員の方で再任用は制度的に違うのか教えていただきたいのと、２３区は、前にありましたよね。２３区などと難しいことを言っていないで、それは産経費のところに出てきますと言ってくだされば、そこに続くので、その辺についてお伺いします。","respondent":"黒田人事課長、伊崎地域活動課長","answer":"婚活のほうですが、先ほど申し上げたのは、職員の福利厚生事業として行っているものをご紹介したものです。婚活事業ですけれども、ページにいたしまして１６２ページの産経費、勤労者共済会運営補助のほうで昨年度まで実施をしていたものと聞いております。","id":"exchange-025"},{"speaker":"藤原委員","kind":"質問・要望","question":"これ、聞かないとならないテーマなので、させてほしいと求めました。よく伺うのは、給料が下がるというふうに伺っているのですけれども、減りましたか。","respondent":"黒田人事課長","answer":"そういった意味では、一般職員も管理職員も、この再任用制度の中で雇用されているというものです。","id":"exchange-026"},{"speaker":"藤原委員","kind":"質問","question":"「変わっていません」と答弁してくれればいいのですから。では、松代部長、どうか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"私が聞きたいのは、いわゆる再任用という制度があって、そして同一労働同一賃金というのがあって、そこを伺いたいのです。一人ひとりの職員の方も多分いろいろお考えが、そういう意味でお伺いしたいのですけれども、いかがか尋ねました。","respondent":"黒田人事課長","answer":"再任用職員の給与につきましては、特別区ですと、特別区人事委員会のほうで給与表として再任用の給与を定めて勧告しているというものです。基本的に民間との均衡ですとか、そういった意味で、公務員の再任用の賃金は決まっているというものです。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"次へ行きます。１１１ページで、駐車場を管理している業者が変わったというふうに伺ったのですけれども、どういう形に変わってきたか教えていただけますか。","respondent":"立川経理課長","answer":"庁舎と中小企業センターについて、これまでの事業者の契約満了に伴い入札を実施いたしました。競争入札を今回実施いたしまして、タイムズ２４株式会社が、年間に直しますと、約２,７００万円ぐらいの金額で落札した。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"毎回伺っていますが、今までのことはやってくださっているのですかというのが２点あって、これについてはいかがか尋ねました。","respondent":"立川経理課長","answer":"１階の部分、そちらのほうに約１５０台分確保しておりまして、職員についてはそちらに誘導しています。必要な工事については実施していくという考えですけれども、その辺を勘案しまして、今後どうしていくかということは検討していくところです。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"庁舎の改修のときに便所を直していくということですか。正確に、計画があって、こういうふうにしていくのだということがあったら、具体的にぜひ教えていただけますか。","respondent":"立川経理課長","answer":"ただいまの発言の趣旨ですけれども、いつになるかわからないですけれども、将来的に新しい庁舎を建てなければならない時期が来ますので、そのときにトイレにつきましては最新の快適なトイレを設置したいというふうに考えているところです。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問・要望","question":"防犯カメラのことについてお伺いしたいのですけれども、ぜひぜひ推奨していっていただきたいと思っておるのですが、どういう利点があったか。警部補のほうが多いと思うのですけれども、警視であったからこそよかったこととか、その辺について教えていただけますか。","respondent":"菅生活安全担当課長","answer":"委員会といいますか、課長として来なければなかなかできないことでありますし、非常に貴重な経験だというふうに感じております。これから予算の関係とか、いわゆる警察官としての視点も少し考えながらできるということは、非常に貴重なことだというふうに感じているところです。","id":"exchange-032"},{"speaker":"田中委員","kind":"提案","question":"１２３ページ、２項４目防災対策費について伺います。区として内容を確認し、具体的な事例を地域の方に提案するなど、マニュアル作成には区のアドバイスも必要だと考えますとの意見を述べました。","respondent":"古巻防災課長","answer":"町会に加入されていない方も当然避難をしてくるということが考えられますので、今ご指摘いただいた点を参考にはさせていただきたいと思います。","id":"exchange-033"},{"speaker":"田中委員","kind":"確認","question":"子どもの勉強スペースの確保を避難所運営マニュアルに記している地域があることも確認していますが、走り回ることができ。地域が自主的に地域に合ったマニュアルを作成するべきであることはそのとおりですが、区の見解を示すよう求めました。","respondent":"古巻防災課長","answer":"先ほどの続きという形にはなろうかと思いますけれども、今後の充実に関しましては、区としましても課題というふうに認識をしております。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"聴覚、精神など、それぞれの障害のある方たちに区は聞き取りを行っているのでしょうか。伺います。","respondent":"古巻防災課長","answer":"障害のある方への対応ですけれども、そういった方々への配慮をしていくということは、区として必要なことであるというふうに認識をしております。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問","question":"品川区では、車中泊やテント泊などの避難所の外にいる人へ食事などの支給はされるのでしょうか。その方たちにも支援がされるのかということを伺います。","respondent":"古巻防災課長","answer":"全ての避難者に対して支援をするということが国の定めでもありますので、区としても同様な形で支援をしていくということを考えております。そうした方への対応についても、把握をして、対策をとれるようなことを考えていかなければいけないというふうには考えております。","id":"exchange-036"},{"speaker":"田中委員","kind":"確認","question":"監査報告書の処理経過が正確に実行されたかどうかは、どこの責任で確認がされるのでしょうか。学校の場合は教育委員会だと思うのですが、地域センターなどのほかの施設の処理経過の確認はどこが行うのか尋ねました。","respondent":"江部監査委員事務局長","answer":"それを区長部局ないしは教育委員会にお返しをし、結果については、措置結果はこういうふうに対応しましたということで報告を受けているものです。達成されたかということにつきましては、各行政委員会、各部課所管のところで対応していただくものだと認識しております。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"なので、ぜひホームページへ公表されることと、その措置報告も議員に配付されることを要望したいです。そして、地域センターなどのほかの施設での処理経過の確認はどこが行うのかということもの説明を求めました。","respondent":"江部監査委員事務局長","answer":"地域センター等の処理経過の確認というお話です。これについては、地域振興部の中でチェックをしていただいているものと認識しております。","id":"exchange-038"},{"speaker":"田中委員","kind":"質問・要望","question":"なので、その後のことがわからないので、ぜひもっとわかりやすいところに公表がされることを要望いたします。２０１５年で指摘がされたときに、教育委員会では、ほかの学校へ注意を促すことが必要だったと考えますが、区の見解を伺います。","respondent":"大関教育総合支援センター長","answer":"教育総合支援センターより学校担当の指導主事が、月２回、学校訪問をした際に確認をしています。今後とも徹底してまいります。","id":"exchange-039"},{"speaker":"田中委員","kind":"質問・要望","question":"重大な事故につながる可能性があった本当に重大な報告だったと感じています。これからはしっかり対応がされることを強く要望しますとともに、ぜひ検討してほしいのですけれども、答弁をいただくよう求めました。","respondent":"江部監査委員事務局長","answer":"監査結果につきましての公表・報告というのは、地方自治法上、議会にも報告すること、それから、公表するという形になっております。今後、どのようにするかということについては、監査委員協議会に諮るということで進めてまいることになると思います。","id":"exchange-040"},{"speaker":"田中委員","kind":"質問・要望","question":"しかし、今回のような突然の解散の場合、障害者への移動支援や同行援護の給付は、その分、きちんと保障されるのでしょうか。伺います。","respondent":"中山障害者福祉課長","answer":"それぞれ移動支援にしましても、同行援護にしましても、個別給付ということで支給決定しておりますので、事業所と連携して対応をとっていく予定です。","id":"exchange-041"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"平成３０年度以降は近隣地区との相互乗り入れが予定されているというところで、そしてお台場地区のところにビーチバレー競技会場があります。三カ所検討の余地も入れてほしいと求めましたけれども、改めてもう１回、答弁を。","respondent":"中村都市計画課長","answer":"可能かどうか、こういったものは組織委員会の輸送計画が固まった段階で、さらに足りないというような場合に協議をするようなことになるかと思います。したがいまして、必要に応じて検討することが考えられます。","id":"exchange-042"},{"speaker":"高橋（伸）委員","kind":"質問","question":"２年半あると言っても、やはり運行にあたっての調査とか、いろいろ検討しなければいけない段階があると思うのです。その返事は大体いつごろになるのか、最後にの説明を求めました。","respondent":"中村都市計画課長","answer":"輸送計画の調整会議が開催される予定になっておりますけれども、これも今まで２回ほど開催されまして、まだ決定をしておりません。そして、それがいつ決定するかについては、まだ区のほうも把握していないのですが、これはまだ未定です。","id":"exchange-043"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、１２４ページ、災害時応急物資確保費に関連して、受援体制についてお伺いさせてほしいと求めました。品川区地域防災計画が大規模な策定、修正をしているところだと思いますけれども、今わかっている段階でお話をほしいと求めました。","respondent":"古巻防災課長","answer":"今ご質問ありました全国的な組織からの支援に対する受援のあり方ですけれども。さらに具体的にしていくような形で進めていきたいというふうに、今、考えているところです。","id":"exchange-044"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今、想定している中というか、お考えになっている物流拠点の場所がわかればお知らせほしいと求めました。","respondent":"古巻防災課長","answer":"具体的に拠点を定めるというのが、少し変更するのは難しい面があるかと思いますけれども、より物流の拠点としてふさわしい場所をさらに検討を進めていきたいというふうに考えております。","id":"exchange-045"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"時間がないので、また改めてこれは土木費のところで、もう１回質問させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"あくつ委員","kind":"質問","question":"時間があれば、１１９ページ、地域スポーツ等推進経費、マラソンのことについて伺いたいと思います。１点目、町会名簿の取扱いについて伺いたいと思います。","respondent":"伊崎地域活動課長","answer":"中身といたしましては、すなわち自治会や同窓会等の非営利組織もここに該当するということが大きな改正点というふうに把握しております。区の条例ですけれども、町会および自治会の活動活性化の推進に関する条例につきましては、特に影響してくるものではございません。","id":"exchange-047"},{"speaker":"あくつ委員","kind":"質問・要望","question":"自治会、町会を含む全ての事業者は、この個人情報保護法のルールにのっとった取扱いが求められる。ちょっと今聞いてしまいましたけれども、罰則があるのですが、どんな罰則なのかの説明を求めました。","respondent":"伊崎地域活動課長","answer":"ただし、現在、取得している個人情報については、適切に取り扱うことで、改めて取り直す必要はないということも定められております。申し訳ございませんが、手元に資料がございませんが、個人情報保護法上の罰則が適用されるというふうに認識をしております。","id":"exchange-048"},{"speaker":"あくつ委員","kind":"質問","question":"何が言いたいかというと、これは２年前に決まったことで、今年の５月から施行されたのですが、みんな知らないということです。かなりこれは該当してしまうものですから、周知しなければいけないと思うのですけれども、いかがか尋ねました。","respondent":"伊崎地域活動課長","answer":"今ご指摘のとおり、第三者の不正な利益を図る目的で提供、盗用したときは、１年以下の懲役又は５０万円以下の罰金に処せられるということがあります。１０月、今月早々に皆様に改めて周知をする予定でおりましたので、その旨ご報告します。","id":"exchange-049"},{"speaker":"あくつ委員","kind":"確認","question":"続きまして、防災対策費、１２３ページ、避難所運営マニュアルについて伺います。もう１回確認なのですが、幾つの学校避難所があって、そのうち幾つの学校が運営マニュアルを整備されているのかの説明を求めました。","respondent":"古巻防災課長","answer":"避難所ですけれども、数については５２カ所を指定しております。そのうち、現在４７カ所の避難所におきましてマニュアルの整備が進んでいるという状況です。","id":"exchange-050"},{"speaker":"あくつ委員","kind":"確認","question":"もちろん定期的に開催されています避難所連絡会議とか防災訓練では確認をされているとは思うのですけれども、これは実状だと思います。実際、公開する自治体もどんどん増えていますけれども、もし問題があるのであればの説明を求めました。","respondent":"古巻防災課長","answer":"５２カ所中４７カ所というふうにお答えをさせていただきましたけれども、さまざまな、鍵の取扱いですとかということをまとめているところもあります。","id":"exchange-051"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ここについては、それを見ても本当にあるのかどうかはわからないと思いますので、そこのところはちょっと私の質問の趣旨とは異なるのかと。","respondent":"古巻防災課長","answer":"避難所運営マニュアル等における避難の考え方につきましての周知については、今ご指摘いただいた点を踏まえまして、さまざま考えていきたいというふうに思います。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１人平均年間３６１時間の超過勤務、最大の方は１,５１０時間、現場の実態をお伺いいたします。この１,０００時間を超えている人数と、どこの課なのか教えてほしいと求めました。","respondent":"黒田人事課長","answer":"平成２８年度につきましては、１人当たり年間１５１.３時間ということで、１人当たり１２.６時間というような時間です。１,０００時間を超えている職員がいる職場ですが、先ほど申し上げました保育課ですとか、教育委員会です。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もう１つ聞こえなかったのと、課ごとにわかったら教えていただきたいのと、１,０００時間を超えているのが教育委員会と保育課ですか。この辺、何人いるのか、どこの職場なのかと聞いたので、正確に答えるよう求めました。","respondent":"黒田人事課長","answer":"１人当たり年７２５時間でございまして、本会議でもご答弁申し上げましたが、１人当たり年３６１時間です。防災課につきましては、年４９９時間といった時間が超勤の時間です。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問","question":"別々に聞いたので、１,０００時間を超えているところの人数と職場と言って、人数の説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問","question":"年次有給休暇の取得についてお伺いしたいと思います。一般質問で、保育園保育士の有給休暇が年間８日間と少ないことがわかりましたけれども、何点かお伺いします。","respondent":"黒田人事課長","answer":"学校などということで、担任を持っているような職場につきましては、取得日数が少ないのかというふうに考えてあります。大体３０人程度ということでございまして、人数の内訳が手元にございませんが、その中の半数ぐらいではないかと認識しています。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"具合が悪くなったときに投票に行けなかったら困ると、大事な１票なので、ぜひ投票したいという相談を受けました。この方の相談に対して、指定病院による不在者投票と、とりあえず郵便等による不在者投票について教えてほしいと求めました。","respondent":"黒田人事課長、安井選挙管理委員会事務局長","answer":"忙しい職場というところで、必要なところには職員を配置しておりまして、そういった意味では仕事の量を見ながら職員配置については、適正に配置しているというふうに認識しています。あるいは要介護５以上の方については、こちらへ送っていただいて、それを不在者投票として扱うという場合があります。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これはどこでも共通なのですか。品川区で工夫できるのかどうか、そこもお伺いしたいと思います。","respondent":"黒田人事課長、安井選挙管理委員会事務局長","answer":"１人当たりの平均を先ほども申し上げましたが、基本的には分散をして仕事をしていきたいというふうに考えておりまして、なるべく分散するようにということでやっていきたいと考えています。現在、要介護５の基準については、これを引き下げて、研究会のほうでは３ぐらいまでいくのではないかということで、法改正のほうへ結びつけられるような話になっていると聞いてあります。","id":"exchange-058"},{"speaker":"松永委員","kind":"質問・要望","question":"この差について伺いたいと思うのですが、富岡町に１名ということはわかったのですけれども、ちょっと詳しく教えてほしいと求めました。前年度と派遣費を比べしますと、約３０万円増ということになっておりますが、その内容についても伺いたいと思います。","respondent":"黒田人事課長","answer":"歳出のほうのこの被災地支援職員派遣費ですが、平成２８年度ですと、熊本地震の職員派遣を行った旅費が含まれているものです。熊本地震につきましては、２０名の職員を延べ１３０日派遣いたしましたので、そういった旅費についてこちらで支出しているものです。","id":"exchange-059"},{"speaker":"松永委員","kind":"質問","question":"これは毎年１年交代で職員をかえるような形なのかと思うのですけれども、どのような形で選ばれているのかということをひとつ伺いたいと思います。先ほどの質問とかぶるかもしれませんが、どういったものに主に使われたのか、改めて伺いたいと思います。","respondent":"黒田人事課長、伊崎地域活動課長","answer":"おおむね２年から３年というスパンで派遣しておりまして、そういった中で被災地の状況等も考えまして、どの程度派遣するかというところを毎年度決定しています。お尋ねの町会・自治会への新規事業応援助成です。件数が２７件、２７町会・自治会が補助対象となっておりまして、親睦のレクリエーションなどが多くなっております。","id":"exchange-060"},{"speaker":"松永委員","kind":"質問","question":"品川区には２０３町会・自治会ありますけれども、その町会・自治会に改めて周知というか、活用してもらうための周知はとても大事であると思います。ですので、今後そうした町会・自治会の周知方法について、改めてどのように行っていかれるのか伺いたいと思います。","respondent":"伊崎地域活動課長","answer":"これにつきまして、今年度の年初めの町会長会議で、また再度になりましたが、詳しくご説明をさせていただいているところです。今年度まだ９月ですが、既に２７町会からお申し出をいただいておりますので、こういった形での周知にまた努めていきたいと考えています。","id":"exchange-061"},{"speaker":"松永委員","kind":"質問","question":"今度は、１２３ページの区民斎場運営費について伺いたいと思います。差が約１,７００万円ということなのですけれども、区として、この差についてどのようにお考えになっているのか伺いたいと思います。","respondent":"提坂戸籍住民課長、伊崎地域活動課長","answer":"改定を予定しているところでありますので、今後、検討をしていく課題の１つだと考えています。本年度申込みをいただいていますところは、この事業は３年間引き続き新規事業としての申込みができますので、そういった昨年から引き続きのところもありますが、何町会かは新しく申込みをいただいているところです。","id":"exchange-062"},{"speaker":"松永委員","kind":"質問","question":"最後の区民斎場運営費で、区民斎場におかれまして、これ、今後検討していくということなのですけれども、今後どのような形で検討されていくのか、もしよかったら最後に伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"まだ具体的なプランは定まってございませんけれども、やはり２３区の状況ですとか、利用者の方のご意見とか、その辺を踏まえながら検討していきたいと考えています。","id":"exchange-063"},{"speaker":"筒井委員","kind":"質問","question":"１２３ページ、１１０ページ、これは時間があればお聞きしたいと考えております。アドバイスの範囲、そして今までの開催状況と、引き続きこのような区政アドバイザー会議を開催する予定はあるのかということをまずお聞きします。","respondent":"柏原企画調整課長","answer":"開催状況につきましては、最近のところでは、年間１回程度行うというのがここ何年かの状況です。いろいろな施策につなげていきたいというところで、今後もこういった形での会議は続けていきたいというふうに思ってあります。","id":"exchange-064"},{"speaker":"筒井委員","kind":"質問","question":"こうした有識者の方などをお呼びした、外部の方のご意見、アドバイスを聞くということは、私も非常にいいことだろうと考えております。","respondent":"柏原企画調整課長","answer":"お話を聞きたいというところがありますので、会議の内容そのものを公開するという趣旨のものではないというふうに捉えてあります。ただし、こういったものはどういった方でお示しができるかというのは、今後検討したいというふうには思ってあります。","id":"exchange-065"},{"speaker":"筒井委員","kind":"質問","question":"その発言された方のお名前を伏せて、その発言内容だけを公開するなど、適宜こうした会議は公開の方向へ進めていってほしいと考えております。当然、行政課題や行政需要を考慮して、不要なものは見直していくというお考えでよろしいのかということをお聞きいたします。","respondent":"柏原企画調整課長","answer":"公共施設の検討の部分ですけれども、基本的なスタンスとしては、全施設が対象と考えています。行政ニーズといったところを考えた場合に、見直しをしなくてはいけない部分もあると思いますので、両面で考えていくという内容のものです。","id":"exchange-066"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひとも必要なものは必要でいいのですけれども、見直すべきものはしっかり見直していっていただきたいと考えております。ということで、この品川荘の売却などの検討、そうしたお考えはあるのかどうかお聞きしたいと思います。","respondent":"伊崎地域活動課長","answer":"室数の利用率につきましても、昨年度で５６.２％ということで、多くの区民の方たちにご利用いただいているという実績があります。旅館が３９.７％ということですので、区民の方からのニーズに対応して、現在のところは売却をするという考えはございません。","id":"exchange-067"},{"speaker":"筒井委員","kind":"質問・要望","question":"当然、伊東市周辺にも民間宿泊施設もあることですから、ぜひとも検討をしていっていただきたいと考えております。今、管理職の方お一人の体制で対応をしっかりできるのかどうかということを、区のご見解をお聞きいたします。","respondent":"米田危機管理室長","answer":"危機管理宿日直は危機管理室で所管しておりまして、ミサイル等に関しては、基本的には国民保護計画に基づいてということで防災課の所管になります。対応にあたる必要があるだろうということで、定めて、初動対応にあたっているというふうにご理解いただければと思います。","id":"exchange-068"},{"speaker":"筒井委員","kind":"質問・要望","question":"いち早く区民の方の不安を払拭していただくために、しっかりと対応をぜひともしていっていただきたいと考えております。よろしくお願い申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"大沢委員","kind":"質問","question":"最初に１２５ページのほうからお伺いいたしますが、ここに記載があります本団３つ、１７分団、３少年団ということであります。","respondent":"川部防災安全担当課長","answer":"３消防団ありますけれども、それぞれの消防団長の任命権者になっている、こういうことです。","id":"exchange-070"},{"speaker":"大沢委員","kind":"確認","question":"今の質問につきましては、法律で決まっているということで、区長が任命その他の事務についての権限をお持ちであるということで確認をさせていただいてよろしいか尋ねました。","respondent":"川部防災安全担当課長","answer":"任命権は区長にあるのですけれども、それぞれの事務の内容につきましては、これは特別区の消防団設置等に関する条例の中で決められております。これは東京都の条例です。","id":"exchange-071"},{"speaker":"大沢委員","kind":"意見","question":"２０２０年のオリンピック・パラリンピックに向けて、インバウンドの方たちをお迎えすべく、さまざまなご苦労をされていると思います。いろいろなご感想があると思うのですけれども、その辺りのところ、把握をしているようであればお教えくださいとの意見を述べました。","respondent":"遠藤協働・国際担当課長","answer":"英語少し通じます商店街につきましては、既に平成２６年度から７回、５３店舗で実施していただいております。おもてなしで伝わるのだということで、非常に気持ち的に楽になったとか、そういう話は伺っております。","id":"exchange-072"},{"speaker":"大沢委員","kind":"意見","question":"全国だと１,２００弱、インド料理があるそうです。ここらを１つの社会資源、それについてご感想の説明を求めました。","respondent":"遠藤協働・国際担当課長","answer":"外国人の方、既に日本に来ていらっしゃる方を、料理店等で働いている方をうまく活用してということかと思います。そのようなご意見をいただいたものを参考に、今後、検討していければというふうに考えております。","id":"exchange-073"},{"speaker":"大沢委員","kind":"質問・要望","question":"東京都で６５０店舗弱ということでインド料理の話をお話ししましたけれども、これは多分、数がおわかりになったら教えてほしいと求めました。ぜひともせっかくあるものの、お考えの中に入れていただいて、この交流事業をより実のあるものにしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"塚本委員","kind":"質問","question":"それから、１２６ページ、戸籍及び住民基本台帳費でいいのかどうか、住民票の発行事務について、この２点をお伺いしたいと思います。平成２８年度、これの結果をお伺いしたいのと、品川区に採用された方がいらっしゃるのかというところでの結果をお伺いしたいと思います。","respondent":"黒田人事課長","answer":"平成２８年度の障害者採用の件ですが、申し訳ございません、特別区の採用の状況については、今、手元に資料がございませんが、品川区では、昨年度、採用試験で障害者選考で需要数を出したのですが、最後に辞退がありまして採用に至っていないです。","id":"exchange-075"},{"speaker":"塚本委員","kind":"質問・要望","question":"その理由について伺えればと思いますけれども、精神障害と発達障害の方も採用対象として、含めるということになったということでお伺いしました。","respondent":"黒田人事課長","answer":"平成３０年４月からの採用については、平成３０年に実施する採用試験から、ただいま検討しているというような状況です。ですので、平成３１年４月からの採用については、東京都と同様な形で採用が行われるのではないかというふうに考えているところです。","id":"exchange-076"},{"speaker":"塚本委員","kind":"質問","question":"平成３１年度の４月から働くということで今ご説明がありましたけれども、職場の理解が非常に大切になってくる、重要になってくると思います。こういうことについて、今現在、どのようなことで取組みをされようと思っているのかお伺いしたいと思います。","respondent":"黒田人事課長","answer":"基本的に、東京都が１年先行しているというところもありますので、特別区全体として考えていかなければならないというふうに認識しています。こういった情報も注視しながら、また人事委員会とも情報をとりながら検討してまいりたいというふうに考えてあります。","id":"exchange-077"},{"speaker":"塚本委員","kind":"質問","question":"来年からの採用に向けて、しっかりと対応をお願いしたいと思います。１２６ページのほうですけれども、この５年が経過したものについては、どのような扱いになっているのかお伺いいたします。","respondent":"提坂戸籍住民課長","answer":"そういう事由で住民票を消された方については、住民基本台帳法施行令の第３４条に基づいて、５年間の保存義務があります。それを過ぎたものについては、データの有効活用ということで、年度単位で切っているのですが、消除をしています。","id":"exchange-078"},{"speaker":"塚本委員","kind":"質問・要望","question":"データの有効活用で消除ということは、とっておくと何か不具合があるという、どこかにしわ寄せが行くとかという意味でしょうか。もう１回詳しくお聞かせいただきたいのと、義務としては５年ではあるけれども、いかがでございましょうか。","respondent":"提坂戸籍住民課長","answer":"その方が即５年で消除になるということではございませんので、その辺はご理解願いたいところです。司法書士からの要望は具体的には把握してございませんけれども、今後の検討課題ということにさせていただきたいと思います。","id":"exchange-079"},{"speaker":"塚本委員","kind":"質問","question":"今、それはもしかしたら可能になるというようなところもあるのではないかと思うので、そこについては今後とも検討をよろしくお願いしたいと思います。こういったことについて、今、どのようになっているのか最後にお伺いいたします。","respondent":"提坂戸籍住民課長","answer":"幸い品川区には請求はなされませんでした。","id":"exchange-080"},{"speaker":"のだて委員","kind":"質問","question":"私からは、１１０ページの非核平和都市品川宣言事業にかかわって、核兵器廃絶について伺います。政府に条約批准を申し入れて、北朝鮮を含め全世界に核兵器廃絶を訴えるべきだと思いますが、いかがか尋ねました。","respondent":"米田総務課長","answer":"周年事業等でレベルアップしたものを何年かに１回やるというようなことで、事業名にもこの宣言名を冠し、実施しているものです。こういったことをこれからも、今後、品川区としてできることを精一杯、草の根の事業ということで行っていくというようなことで考えているところです。","id":"exchange-081"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういったことも草の根の運動はとても重要だと思います。私が求めたのは、宣言を行っている自治体ですから、ぜひ求めていただきたい。","respondent":"米田総務課長","answer":"国のやっていることに対して、区として、自治体として、意見を申し上げるということは考えてございません。非核平和都市品川宣言に基づき、これらの事業の創意工夫を重ねた取組みをどんどん進めていくことによって、このように考えているところです。","id":"exchange-082"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり非核平和都市宣言を行っている、だからこそ行動をさらに一歩踏み出して行っていただきたいと思うのです。今の緊張の高まりを核兵器使用の危機だと思っているのか伺いたいと思います。","respondent":"米田総務課長","answer":"非核ということで事業を実施しておりますことから、９月４日、速やかに区長名で北朝鮮に向けて抗議の文書を送付したというようなことです。","id":"exchange-083"},{"speaker":"のだて委員","kind":"質問・要望","question":"国際社会の平和と安全に対する重大な脅威として、恒久平和の実現を、ということで求めているのです。日本政府に求めていかないというのはどういったことなのか、同じ外交・防衛ではないのか伺いたいと思います。","respondent":"米田総務課長","answer":"非核平和都市品川宣言ということで、核兵器廃絶ということを前面に打ち出して、これは昭和６０年からずっと品川区としてはアピールをしています。今、こちらについては、その役割を果たすべき国等が第一義的に対応するものというふうに考えてあります。","id":"exchange-084"},{"speaker":"のだて委員","kind":"質問","question":"私が聞いたのは核兵器使用の危機になっているのではないかということをお聞きしたのです。コメントしないで、なぜ実現に寄与できるのか、ここのところを伺いたいと思います。","respondent":"米田総務課長","answer":"繰り返しになりますが、昭和６０年からずっとこれを継続的に外に向けて発出しているということでご理解いただければと思います。","id":"exchange-085"},{"speaker":"のだて委員","kind":"質問・要望","question":"核兵器の使用の危機だと私は思っているのです。政府へ核兵器禁止条約を批准してほしいと求めることこそ、宣言文に沿った行動だと思うのですけれども、いかがか尋ねました。","respondent":"米田総務課長","answer":"その中で非核平和都市品川宣言に基づいた事業を行い、また、核実験等があれば、それに対しての抗議文を送っているところです。どうぞご理解ください。","id":"exchange-086"},{"speaker":"のだて委員","kind":"質問","question":"世界にも核兵器廃絶と恒久平和を呼びかけているわけです。そこで伺いたいのですけれども、区の考える恒久平和とは何か、どういう状態を言うのか伺います。","respondent":"米田総務課長","answer":"恒久ですから、永遠に、先に至るまで世界の人々が平和に暮らし続けられる、ひいては区民の方が平和で安全に争いのない世界で暮らし続けられるということと理解しております。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問","question":"今の世界状況、状態は区の言う永遠に平和である、暮らし続けられる、こういった状況なのでしょうか。恒久平和に対する危機ではないのか伺います。","respondent":"米田総務課長","answer":"長崎等へ青少年を派遣して、品川区民の中で平和の意識の醸成ということを絶えず行っており、それはこの宣言に基づいて実施しておるものです。","id":"exchange-088"},{"speaker":"のだて委員","kind":"質問","question":"やはり黙っていて恒久平和がつくれるのでしょうか。この危機に対して恒久平和をどうやってつくるのか伺います。","respondent":"米田総務課長","answer":"そういったことをまさしく調整するのが国の役割だというふうに思っているところです。思想、恒久平和が続くようにというような取組みを絶えず区民に向け、特に若い世代に向け発信し続けているということで事業を行っているものです。","id":"exchange-089"},{"speaker":"のだて委員","kind":"質問・要望","question":"地域として７,４５３都市、国内では１,６８７都市と、国内で９割以上の都市が加盟しているという状況です。今回ここに参加したということで、参加を機に核兵器廃絶へ品川区の積極的な役割発揮を求めたいと思いますが、いかがか尋ねました。","respondent":"米田総務課長","answer":"世界の都市と連帯し、核兵器廃絶と世界恒久平和の実現を訴え続けるという会議体の趣旨に鑑み、加盟の手続を行ったものです。その中では、平和教育実施のための活動の企画と推進を意欲的に進め、都市はそれぞれの政策の中で平和文化を実践することができるというようなことで。","id":"exchange-090"},{"speaker":"本多委員","kind":"質問","question":"１１３ページの財政管理費、契約関係事務費について伺います。最初に、平成２８年度について、契約関係事務が円滑に行われたのか、実績など総括的にの説明を求めました。","respondent":"立川経理課長","answer":"契約事務全般ですけれども、平成２７年度に比べまして、不調の件数が減りまして、おおむね順調に契約事務は実施されていると考えております。","id":"exchange-091"},{"speaker":"本多委員","kind":"質問","question":"工事について伺っていきますが、くじ引きにより落札者の決定が発生し、工事の品質低下や労働者へのしわ寄せなどが懸念されています。今、東京都が導入した取組みを、品川区としては同意しないほうがいいと私は思うのですが、見解の説明を求めました。","respondent":"立川経理課長","answer":"ちょっと説明しますと、東京都はこれまで予定価格を事前公表していたところ、事後公表にしたというのがまず第１点です。これまでの運用については、やはり何ら問題点をこちらとしては認識しておりませんので、これまでどおり実施していきたいと考えているところです。","id":"exchange-092"},{"speaker":"本多委員","kind":"質問","question":"一部だけ述べますと、企業の施工能力と、企業の社会性、信頼性と大きく２つに分かれております。社会的にもメリットがあるというのでしょうか、そのような視点も必要かと思うのですが、そのような点についてはいかがか尋ねました。","respondent":"立川経理課長","answer":"災害等の防災協定とか、防災等の活動実績等、その辺を評価してやっていくところです。その辺につきましては、いろいろ研究して、適切に評価していく必要があるのかというふうに考えているところです。","id":"exchange-093"},{"speaker":"本多委員","kind":"質問・要望","question":"次の質問なのですが、これ、管理がしやすいからそういう方法をとっているのでしょうか。その辺を教えていただきたいのと、あと、分離発注の考え方です。","respondent":"立川経理課長","answer":"建築で発注したものを、そこから専門の業者に下請けを出していただいているということは、こちらも認識しています。考え方としましては、やはり地域の建設業者の受注機会を確保する観点から、なるべく分離分割で発注するのが重要であるということは認識しています。","id":"exchange-094"},{"speaker":"本多委員","kind":"質問・要望","question":"その辺を改めて教えていただきたいのと、非常に先走った質問になるのですが、いつも仕上げを見て思うのです。その辺はいかがか尋ねました。","respondent":"立川経理課長","answer":"企画力であるとか独自性、そういったものを踏まえて発注するということになりますと、さまざま事務手間等も増える。どういった工夫ができるかについては、工事発注課といろいろ研究していきたいというふうに考えているところです。","id":"exchange-095"},{"speaker":"本多委員","kind":"質問・要望","question":"独自性だったり、企画力だったり、考えてほしいと求めました。発注者側としてもう少し配慮できないものか、限度額の引き上げ等できないものか、最後にそこだけ聞いて終わります。","respondent":"立川経理課長","answer":"トップ５には入る金額です。例えば３０億円、４０億円の工事では、適切に検討をしていきたいというふうに考えているところです。","id":"exchange-096"},{"speaker":"浅野委員","kind":"質問・要望","question":"最初に文化センター経費ですけれども、この文化センター５館で、非構造部材耐震化設計委託、こちら約３５０万円ということで出ておりました。","respondent":"鈴木文化観光課長","answer":"平成２８年度につきましては、旗の台文化センターで非構造部材の工事を行ったところです。それから、残り４館のうち３館は、今年度、平成２９年度で工事に取り組んでいるところです。","id":"exchange-097"},{"speaker":"浅野委員","kind":"質問","question":"見方が非常に難しかったので、どう解釈していいか、この決算書から見るとわかりにくかったのですけれども、了解いたしました。ぜひともこの耐震化については、このように思いますので、この点についてもどのような体制で臨むのか教えてほしいと求めました。","respondent":"鈴木文化観光課長","answer":"文化センターは、ご指摘のように、非構造部材、照明であったり、それから天井、またはスポーツ室などは高所の天井があります。必要なところは非構造部材の耐震化工事を行うということで、今、計画的に進めているところです。","id":"exchange-098"},{"speaker":"浅野委員","kind":"質問・要望","question":"次に、１０９ページのしながわＷｉ－Ｆｉスポット事業について伺います。オリ・パラに向けまして、今後Ｗｉ－Ｆｉの設置場所の拡大計画などございましたら、教えてほしいと求めました。","respondent":"仁平情報推進課長","answer":"フリーＷｉ－Ｆｉは２４時間利用可能になっておりまして、Ａさん、Ｂさんが何時間ぐらい使ったかまでは分析できないような形になっております。","id":"exchange-099"},{"speaker":"浅野委員","kind":"質問","question":"かなりの場所に設置をされていくということを伺いました。そこら辺がよくわからないところもあったのですけれども、協力店舗になるための条件ですとか、メリットなどを教えてほしいと求めました。","respondent":"仁平情報推進課長","answer":"ただ、ここに参加するためには、別の通信事業者が提供している通信回線ですと参加できないという形になってしまいます。同じサービスを提供している店であれば、区のＩＤに参加できる、そういう形になっております。","id":"exchange-100"},{"speaker":"浅野委員","kind":"意見","question":"品川区以外のところでもかなりの自治体等で設置をしているわけでありますので、品川区もそれに負けじとこれからもやっていただけるかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-101"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ぜひこの辺に関しては、時代の流れの中でどんどんハイブリッドにぜひ変えていっていただきたいと思うのですが、いかがでしょうか。せっかく資格があるのに７０歳で定年を、ぜひ今度は区に貢献をしていただくような仕組みをつくっていただきたいのですが、いかがか尋ねました。","respondent":"立川経理課長、伊崎地域活動課長、川部防災安全担当課長","answer":"庁有自動車の運行管理についてご説明いたします。過去、その前５年以内に板面取替えを行った掲示板が、過去１０年以内に立て替えた掲示板を除く３６９基につきましては立替えを終了しております。体制ですが、運転手が現在６名おりまして、免許証につきましては、基本的には大型のバスが運転できる免許を持っている者がほとんどです。いろいろな訓練に参加して、引退してもなお、まちの方々をご指導されているというような状況はよく認識しています。","id":"exchange-102"},{"speaker":"いながわ委員","kind":"質問・要望","question":"この６名の方の運転の質といいますか、急ブレーキを踏んだ、ノッキングしたとかという、その評価は誰がどういう形でしているのか。おそらく委託をしているわけですから、そのまま運転手が来て運転をしている。","respondent":"立川経理課長","answer":"もちろん区長の運転手につきましても、区長からご意見をいただく機会があります。そういうこともあろうかと思いますので、どのように評価していくかについては、今後検討していきたいと考えております。","id":"exchange-103"},{"speaker":"いながわ委員","kind":"質問・要望","question":"実際にマイクロバスでノッキングをする、前に進まなければいけないのにバックに入ってしまうというケースが本当にあるのです。お金を払って管理をしてもらっているので、そこはしっかりとやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-104"},{"speaker":"西本委員","kind":"質問","question":"私、監査報告に対しての対応、その対応をどうされたのかというところまでのしっかりした経過報告がなされていないという指摘をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"},{"speaker":"西本委員","kind":"質問","question":"先ほどの答弁の中では、駅には何カ所も設置するという方向なのですが、これはなぜ商店街等はやらないのでしょうか。すぐ使えるような商店街もあると聞いておりますので、そこを改装していってはいかがでしょうか、答えるよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"},{"speaker":"西本委員","kind":"質問・要望","question":"それをどういう形で解消した、どういう処理をして、どういう結果になってというところまできっちりと報告をすべきだと思います。そこはせっかく監査で指摘されたものに対して真摯に受けとめてほしいと求めましたが、そのご答弁をお願いいたします。","respondent":"江部監査委員事務局長","answer":"いずれにいたしましても、こちらの件につきましては、監査委員の協議会での検討となろうかと思いますので、これについては代表監査にお伝えいたします。","id":"exchange-107"},{"speaker":"たけうち委員","kind":"質問・要望","question":"私は、１０９ページの国際交流推進事業、それから１１９ページのオリンピック・パラリンピック開催周知事業に関連してお伺いします。また今年の２月には、品川区との交流に対して非常に強い思いを持っていらっしゃるということを伺っております。","respondent":"遠藤協働・国際担当課長","answer":"２５周年ということで、公式訪問団を派遣するという形で行ってまいりまして、向こうでも多くのおもてなしをいただいたというふうに聞いております。","id":"exchange-108"},{"speaker":"たけうち委員","kind":"質問・要望","question":"オリンピック・パラリンピックが３年後に控える中で、やはり向こうからそういう要望があるという、これをしっかり生かしていく。もちろん要望があるからには、もちろんそれも大事だと思うのですが、やはりそれにこたえていく。","respondent":"遠藤協働・国際担当課長","answer":"３年後に迎えます２０２０年、ホームステイでいらした方に対して何かできないかというようなお話かと思います。２０２０年の開催期間に当たっているところがありますので、その辺につきましては、今後検討していければというふうに考えております。","id":"exchange-109"},{"speaker":"たけうち委員","kind":"質問・要望","question":"このオリンピック・パラリンピック、東日本大震災から復興のオリンピックという、こういう意義もあるというように伺っております。ＰＲしていくということもオリンピック・パラリンピックの意義があるというように伺っておりますので、また福島県富岡町、いかがか尋ねました。","respondent":"遠藤協働・国際担当課長","answer":"オリンピックに際しまして、いろいろな関係者の招待ですが、私の所管としましては、オリンピック・パラリンピック担当や、あるいは国際友好協会などと、そういう部分がありますので、一緒になって連携しながら検討していければというふうに思っております。","id":"exchange-110"},{"speaker":"伊藤委員","kind":"質問","question":"それから、１２４ページ、全国瞬時警報システムに関連して質問いたします。全て成り立つわけであるから、やはりそれはぜひ進めるべきだと思うのですが、いかがか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"品川区を発信していくために、「品川」という名前を使うということは大変な有用な策だと区としても受けとめているところです。機会がありましたら、また区民にとって還元されることであるならば、必要に応じてそういった働きかけもしてまいりたいと考えているところです。","id":"exchange-111"},{"speaker":"伊藤委員","kind":"意見","question":"駒沢オリンピック公園という名前が５６年たっても使われているわけであって、その場所でオリンピックが開催されたとすぐわかるわけですとの意見を述べました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"品川区といたしましても、「品川」という名前を使っていただけるのであれば、これは本当に発信力になるというふうに考えておりまして、そういったことは東京都あるいは組織委員会のほうにも働きかけていきたいと考えているところです。","id":"exchange-112"},{"speaker":"伊藤委員","kind":"質問","question":"品川区はもちろんなのですけれども、できればほかの自治体にも声かけをしていただいて、同じことがいえるわけではないですか。同じことが３年後、２０２０年オリンピックにいえるわけだから、もう１回答弁をお願いします。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"「品川」という名前を発信することと、あとはレガシーとして残っていくというとこにつきましては、品川区としても積極的に取り組んでまいります。","id":"exchange-113"},{"speaker":"伊藤委員","kind":"確認","question":"それによれば、弾道ミサイル攻撃時は、区長の避難実施要領策定が明記されているということは確認できました。例えば大井町駅とか、大井町アトレとか、民間と連携した具体的な訓練を実施したことはあるのでしょうかということの確認をお願いいたします。","respondent":"古巻防災課長","answer":"Ｊアラートに関しまして、それに対応する訓練ということで申し上げますと、まだ具体的な訓練は実施されていないと認識しております。区としましては、前回の一般質問でもお答えしたとおり、そういったことを周知していくことが優先事項であるというふうに捉えております。","id":"exchange-114"},{"speaker":"伊藤委員","kind":"質問","question":"何となくそれでいいのでしょうか。というか、はっきりとそれでいいのか尋ねました。","respondent":"古巻防災課長","answer":"ただ、実施の仕方でありますとか、そういったことにつきましては、今後少し考えていかなければいけないのかというふうに思います。機会を捉えて、自主的な訓練という形をとれるというようなことも検討しておりまして、それを含めまして対策を進めていきたいと考えております。","id":"exchange-115"},{"speaker":"伊藤委員","kind":"質問","question":"でも、それこそ短時間でできるだけ多くの方々の安全を守り抜いていくということは、これは品川区の最も大切な仕事ではないでしょうか。これはしっかりと研究をして、具体的な計画を立案していかないといけないと思うのですが、いかがか尋ねました。","respondent":"古巻防災課長","answer":"具体的にＪアラートが発令された場合の対応も定めておりますし、また、そういった体制も整えております。区民一人ひとりが認識できるような形で、今後も周知、それから折りを捉えた対策を進めていきたいと考えております。","id":"exchange-116"},{"speaker":"安藤委員","kind":"質問","question":"２つ伺いますけれども、本体ＴＯＣビルのテナントは、ここに何軒入っているのか伺いたいと思います。最後ですが、計画が固まってから事業完了までには、おおよそどれぐらい年月がかかるものなのか伺いたいと思います。","respondent":"柏原企画調整課長、中村都市計画課長","answer":"ＴＯＣメッセのほうには、そのテナントという形では、現在、私の記憶によりますと入っていないと記憶しています。稼働率につきましては、詳細のところは、申し訳ございませんが、こちらでは把握はしてございません。これにつきましては、おおよそ１年ぐらいの期間が通常かかるかと思われます。工事の完成までということになりますと、これは建物の規模によりますので、これはそれぞれの建物の工期は規模によるということになります。","id":"exchange-117"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺った話だと、月に１回ぐらいしか稼働していないのではないかということなので、区としてもしっかり把握してほしいと求めました。直ちに返還を求めて、切実な区民要望、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"会合であったりとか、そういったところで使っているということで、今おっしゃられた月１回ということはないというふうに認識しています。その中で、意思はあるというのは話は聞いているところですが、その時期については明確なところは現段階で言えないという状況のようです。","id":"exchange-118"},{"speaker":"安藤委員","kind":"質問・要望","question":"直ちに返還を求める考えはあるのかないのかということでしたけれども、直ちに返還を求めるつもりはないということでよろしいのかどうか１点伺います。","respondent":"柏原企画調整課長","answer":"そういったところの意図から考えますと、この貸付の理由の部分について、完全にＴＯＣが放棄しているところではありません。こういったところも含めて、ＴＯＣにはいろいろ強い形でのお話はさせていただきたいというふうに思ってあります。","id":"exchange-119"},{"speaker":"安藤委員","kind":"質問・要望","question":"直ちに返還してほしいと求めましたけれども、もう一度いかがでしょうかということ。それと、先ほど伺ったように、少なくとも平成３２年９月６日には返還を求める考えがあるのかどうか伺ったので、答えてほしいと求めました。","respondent":"柏原企画調整課長","answer":"これ、貸付を永続的にということでは全くありません。ですので、どういう形になっても１０年が１つリミットというところがありますので、区もその後の考え方は今も整理していくです。","id":"exchange-120"},{"speaker":"安藤委員","kind":"質問・要望","question":"そして議会にも説明しているわけですから、平成３２年９月６日には返還を求める考えがあるのですかということを伺ったので、伺いたいと思います。今回の修正案で、なぜ航空機事故の項目を加えたのか伺います。","respondent":"柏原企画調整課長、古巻防災課長","answer":"平成３２年９月というお話がありました。当初のそういう話の部分はありますので、今後もそれについては一定のラインがあるということはお話をするつもりでおります。自動車の事故を含めまして、大規模火災でありますとか、そういったこと全体を大規模事故として捉えて地域防災計画に加えるです。","id":"exchange-121"},{"speaker":"安藤委員","kind":"質問","question":"国が想定している事象は幾つかあるけれども、あえて区は、今回、航空機事故は選んだということです。その理由を、なぜ今回新たに加えたのか伺ったので、はっきりと、答えるよう求めました。","respondent":"古巻防災課長","answer":"はっきり申し上げておりますが、国の防災基本計画にあるものを、そういった類型を加えているですので、それ以上でもそれ以下でもございません。","id":"exchange-122"},{"speaker":"安藤委員","kind":"意見","question":"なぜその中から選んだのかということが全くお答えがありませんがとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-123"},{"speaker":"若林委員","kind":"質問・要望","question":"１１０ページの人権啓発費について伺います。それ以外のいわゆる通常の年のイベント、講演会等、これはどういう違いがあるのか教えてほしいと求めました。","respondent":"島袋人権啓発課長","answer":"荏原文化センターで実施することになるのですけれども、それをきゅりあんで実施する等々のものがございまして、レベルアップをします。内容的にはほぼ同じような形で実施しています。","id":"exchange-124"},{"speaker":"若林委員","kind":"質問・要望","question":"最後の３つ目には、部落差別解消推進法も施行されました。品川としては初めての人権尊重都市宣言の周年となる２５周年ということで、啓発に取り組んでいただきたい、いかがか尋ねました。","respondent":"島袋人権啓発課長","answer":"「ヘイトスピーチ許さない」という懸垂幕を今年の４月に、そちらのほうにも掲出させていただいたという経緯があります。あるいはもう１つ、品川保健センターにも掲出する予定ですので、今後もそのように啓発に努めてまいりたいと思っているところです。","id":"exchange-125"},{"speaker":"若林委員","kind":"質問・要望","question":"１１３ページの区民相談に関連をして伺いたいと思います。ばらばらで所管所管でやっているのか、そこら辺も含めてお聞かせほしいと求めました。","respondent":"中元広報広聴課長","answer":"区民相談室における士業の方々へのお支払いの根拠ですが、区民相談室の事業の運営要綱でそれぞれ決めさせていただいてあります。行政書士の方が７,０００円、社会保険労務士の方もそれぞれ７,０００円ということで、このような金額を決めさせていただいているところです。","id":"exchange-126"},{"speaker":"若林委員","kind":"意見","question":"そういう何かの拍子で士業の方たちが授業中に何かの事故に巻き込まれたり、また、地震があったりとかするかもしれないとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-127"},{"speaker":"高橋（し）委員","kind":"質問","question":"総務費で人事行政全般についてお尋ねします。区職員の方のうち、非常勤職員の方は何人いて、その方々の人件費は、まとめると幾らぐらいになるのか尋ねました。","respondent":"黒田人事課長","answer":"平成２９年４月１日現在で、正規職員数が２,５８３人おりまして、そのほかに非常勤職員が１,３０２人おります。非常勤職員の人件費ですが、こちらは平成２８年度の実績で、１８億２,０００万円余というような額になっているものです。","id":"exchange-128"},{"speaker":"高橋（し）委員","kind":"質問","question":"１,３０２名の方で、約１８億円と。その方々は、特別職非常勤職員と、一般職非常勤職員のどちらになるのか尋ねました。","respondent":"黒田人事課長","answer":"品川区で雇用しております非常勤職員につきましては、地方公務員法上では特別職の職員と位置づけられるものです。","id":"exchange-129"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今年の５月、地方公務員法と地方自治法の一部が改正されました。この法改正の概要、ポイントをご説明ほしいと求めました。","respondent":"黒田人事課長","answer":"この法改正により、平成３２年４月より、会計年度任用職員という形で今の非常勤職員の制度を移行するというような法改正が行われたものです。この中では、あわせて会計年度任用職員について、期末手当の支給を可能とするというような法改正も行われているというものです。","id":"exchange-130"},{"speaker":"高橋（し）委員","kind":"質問","question":"今、お話があった見直しは、東京都では既に平成２７年から導入し、現在、今お話があった特別職非常勤職員から一般職非常勤職員へ移行しております。では、なぜ品川区では今のお話にあるような見直し、移行をしていないのか尋ねました。","respondent":"黒田人事課長","answer":"こういった任用につきまして、こちらにつきましては平成３２年４月から、全国の自治体が一律制度を移行するです。そういった意味では、人事委員会の関与が出てまいりますので、平成３２年４月へ向けて法の整備を図ってまいりたいというふうに考えているものです。","id":"exchange-131"},{"speaker":"高橋（し）委員","kind":"意見","question":"平成３２年と言わず、大阪府では平成２８年、昨年度からやっております。そういったことも含めて、今後の見通しをもう一度お願いしますとの意見を述べました。","respondent":"黒田人事課長","answer":"人事委員会を設置している自治体においては、当然、給与水準というところもあろうかと思います。一定程度、そういった中で期末手当の水準も含めて、そういったとこの人件費のところも課題としてあるのかというふうに思ってあります。","id":"exchange-132"},{"speaker":"高橋（し）委員","kind":"質問","question":"自治体の財政負担が重くなるということで、これは２３区ではありませんけれども、地方交付税に上乗せをするかというようなことも検討すると。２３区で今みたいな見直しを行うとすると、いわゆる財調やそういったことで、どのような対応が予想されるのか尋ねました。","respondent":"黒田人事課長","answer":"地方については地方交付税で対応するというような方針が国から出されているところですが、２３区におきましては、どのような対応が図られるかというところも今後の検討課題です。","id":"exchange-133"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"先ほど、再任用のお話がありましたけれども、退職後のスキルやノウハウを持った職員を有効活用するためにも、この見直しは大変重要だと思っています。平成３２年の施行を待たずに、できるだけ早く調整して見直しをしていただくことを要望して終わりにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-134"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これは今どうなっているかということをよくお聞きをほしいと求めました。私は早急に打ち合わせというか、そういう体制整備を図る話し合いを行うべきと思うので、この見解の説明を求めました。","respondent":"古巻防災課長、立川経理課長","answer":"全国的な組織からの支援ですけれども、一義的には東京都のほうで受けてということで整理をすることかとは考えております。いわゆるＣ工程についての内装を重点的に分離発注できないかというご質問だと思います。この辺につきましては、まだ区のほうでノウハウ等ございませんので、今後、調査研究に努めてまいります。","id":"exchange-135"},{"speaker":"石田（秀）委員","kind":"提案","question":"それぐらいのことはやはり区として、東京都より先んじてやるべき、それはぜひお願いしたいと考えていますので、これは要望しておきます。私は必ずやってほしいと思いますが、そこら辺についてのお考えの説明を求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"大変厳しい状況にあるということは、リオの視察に行ってまいりましたので、そういったことは十分把握しています。プロポーザルの提案等もございましたけれども、そういった具体的な手法につきましては検討させていただきたいと思います。","id":"exchange-136"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"こういうことぐらいは発言できると思うのだけれども、ここら辺のところについて考えていただきたいのと、新規の部分があります。そこら辺のところも踏まえて、私はもっともっと増やしていくべきだろうと考えていますが、その辺の点についてのお考えの説明を求めました。","respondent":"小川オリンピック・パラリンピック準備課長、伊崎地域活動課長、柏原企画調整課長","answer":"委員ご指摘の趣旨も踏まえまして、さまざまな手法をこちらとしても調査研究いたしながら検討してまいりたいと考えています。時代の流れとともに変えていくべきではないかというところは区としても考えておりまして、運営費は区と山北町と半額の負担にもう既になっております。１つ大きいのは、やはり全国連携プロジェクトという特別区の全体の動きがあります。","id":"exchange-137"},{"speaker":"石田（秀）委員","kind":"意見","question":"丹沢湖の花火大会だとか、さまざま、ここについてもどういう形で支援をしていくかという部分が非常にあると思います。あそこの土地をどういうふうにしていくかということを、どこかが判断をしていって、最後にそこら辺のところだけもう一度ご答弁くださいとの意見を述べました。","respondent":"伊崎地域活動課長","answer":"ご利用者につきましては、新しい方々もお使いいただくようになってきておりますし、ひだまりの里については、今、さまざまな活用も検討しています。しかしながら、委員ご指摘の点も含めまして、今後また山北町と協議していきたいと考えております。","id":"exchange-138"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"１１５ページ、１１９ページ、オリンピック・パラリンピック開催周知事業についてお伺いします。１１９ページのオリ・パラ周知ですが、区民にとってもいい周知の方法かというふうに思いますが、その点どのように考えるかの説明を求めました。","respondent":"中元広報広聴課長、鈴木文化観光課長、伊崎地域活動課長、小川オリンピック・パラリンピック準備課長","answer":"次の航空写真の活用ですが、こちらは昭和４７年より継続してやっておりまして、隔年ごとに区の全景および指定したポイントの撮影を行っております。皆さんに見ていただいています品川区を外国人の方が紹介する動画ですが、これは今年度、観光の目的で製作した作品になります。それに対して、まず新しい、まず事業の支援をしてきているところです。今回、具体的に選手のインタビューというご提案ですけれども、大変有用なことだと思います。","id":"exchange-139"},{"speaker":"石田（し）委員","kind":"提案","question":"以前も提案をさせていただきましたが、区の庁舎の３階の入口の部分のところの床に、そういった活用もしてほしいと求めました。これは要望で終わりますとの意見を述べました。","respondent":"鈴木文化観光課長","answer":"区のホームページのYouTubeチャンネルでご覧いただくのは日本人の方ということで、英語の音声に日本語のテロップをつけたものです。海外で放映されるものは、英語の音声と英語のテロップということで、バージョンを使い分けて使用しております。","id":"exchange-140"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"２階の食堂前のコンビニなのですけれども、クーラーが壊れていて、整備されたのかということを１点だけ確認させてください。それから１人、こんなに少ない理由をどう考えられているのか、区としてこの数字をどう捉えておられるのかということについてお伺いしたいと思いますとの意見を述べました。","respondent":"中山障害者福祉課長、中元広報広聴課長","answer":"ふれあい売店のクーラーの件です。チョコレートが溶けてしまったりということがありましたが、９月に無事工事を終了しておりまして、現在はクーラーが稼働している状況です。きちんと資料等も提示をしていますし、そこのところはご理解をいただけたのかというふうに解釈をするしかないかと考えています。","id":"exchange-141"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そして区民からの意見を受けて、そういう姿勢をぜひとっていただきたいと思っているのですけれども、その点についてはいかがでしょうか。その説明責任を果たすという、基本的に区民説明会を位置づけてほしいと思うのですけれども、いかがか尋ねました。","respondent":"中元広報広聴課長","answer":"窓口等でも、カウンター等でもということで、あらゆる方の生活スタイルに対応している合理的な手法であると考えております。説明会となりますと、場所と時間が限られます。","id":"exchange-142"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"どこの区でもホームページにも公開していますし、あらゆる区の施設のところにもそういうふうな計画が区民の目に触れるような形で提供されております。それを反映させていきたいという、そういう姿勢についてはどうですかとお伺いしたのですけれども、いかがか尋ねました。","respondent":"中元広報広聴課長","answer":"繰り返しになりますが、意見をどんどん出していただきたいという姿勢は、区としても持っているところです。現在、区のホームページで公表させていただいたり、区の窓口での閲覧ということで対応させていただいているところです。","id":"exchange-143"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうふうなところでは、ぜひ説明をする機会を、区民も求めておりますので、つくっていただきたいということを強く要望しておきたいと思います。","respondent":"中元広報広聴課長","answer":"考え方としましては、最大３０日間を確保させていただければ、意見を整理していただくことが可能かと考えています。最長で３０日ということで、制度の形骸化を防ぐためにも最短でも１４日を確保することという考えです。","id":"exchange-144"},{"speaker":"こんの委員","kind":"質問","question":"最初に、防犯設備整備助成金ですけれども、町会内に設置をする街頭の防犯カメラについてお聞きしたいと考えています。設置ができるようになって、そして助成金を交付されるという形だと思うのですが、簡単にその流れを説明するよう求めました。","respondent":"菅生活安全担当課長","answer":"私からは、街頭防犯カメラの関係につきましてご説明をします。実際に町会で設置する費用につきましては、そして区の助成金をお支払いすると、そういった流れになっております。","id":"exchange-145"},{"speaker":"こんの委員","kind":"質問","question":"その交付金のことはあとでまた質問したいのですけれども、その場合、町内会に例えば区の区有施設があります。こうしたところは、区行政で区有施設あるいは公園周辺につけるという考え方があるかと思いますが、この点についてはいかがか尋ねました。","respondent":"菅生活安全担当課長","answer":"そもそも街頭防犯カメラを設置する目的は、これらが一体となって、こうした犯罪抑止対策に取り組んでいくということが目的です。街頭防犯カメラにつきましては、引き続き町会等をはじめとする地域の皆様方に設置していただきたいというふうに考えております。","id":"exchange-146"},{"speaker":"こんの委員","kind":"質問","question":"区の施設ですから、公園の周りの防犯カメラ、あるいは区有施設の防犯という対策は必要であるというふうに考えられると思うのです。そして町会もともにまちの防犯対策をとっていただく、こうした考え方が必要かと思いますが、もう一度ご答弁をお願いいたします。","respondent":"柏原企画調整課長","answer":"区全体としての防犯、安全というところの考え方であろうかと思います。全体の安全安心というところを考えたときに、区の施設も有効活用できる部分については検討していきたいというふうに思っております。","id":"exchange-147"},{"speaker":"こんの委員","kind":"質問・要望","question":"確かにそうだというところで今回は質問させていただいたのですが、今ご答弁をいただきましたので、ぜひ前向きに検討をしてほしいと求めました。","respondent":"菅生活安全担当課長","answer":"確かに委員ご指摘のとおり、高額ですと、町会の負担も非常に大きいかというふうには感じております。ただ、それに合わせるという形になってしまいますので、その点はご了承いただきたいと感じております。","id":"exchange-148"},{"speaker":"こんの委員","kind":"質問・要望","question":"確かに、都に申請をして、一定の流れがあるのは理解できますけれども、それでもやはりこうした予算の確保ができないという町会もあろうかと思いますので、そうしたところを踏まえて、今後、こうした町会への支援のことを考えていただきたいと要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-149"},{"speaker":"渡部委員","kind":"質問・要望","question":"たしか２分の１、３分の１の６分の５で、６分の１を町会が負担するのでよかったか教えてほしい。何商店街ぐらいに払われているのか教えていただきたいのと、たしか、それが徐々にいろいろ変わってきたのかと思うのです。","respondent":"菅生活安全担当課長","answer":"これは平成２８年度から助成を開始したものです。今後、調査研究いたしまして、他の自治体等の動向も踏まえながら検討してまいりたいというふうに考えております。","id":"exchange-150"},{"speaker":"渡部委員","kind":"質問・要望","question":"答弁を伺っていますと、ＩＯＣでしょうか、ＪＯＣのほうでしょうか。オリンピックの期間、例えばそこがバスの発着場所になってきますと、どうでしょう、すごく人が来るのではないか尋ねました。","respondent":"菅生活安全担当課長、小川オリンピック・パラリンピック準備課長、中村都市計画課長","answer":"設置につきましては、先ほどもご説明したとおり、まず皆様方の設置時の費用負担について軽減を図っているところです。ブラインドサッカー、天王洲公園での事前キャンプ等を目指していますので、引き続き活動してまいります。いずれにいたしましても、組織委員会の計画などの動向を注視していく必要があると思います。それをもって今後、区としても検討してまいりたいと思います。","id":"exchange-151"},{"speaker":"渡部委員","kind":"質問・要望","question":"どんたく通りもありますというような勝手な思いで言っておりますので、何とかそこを酌んで一声かけていただければと思うのですが、いかがでしょうか。４７カ所で出来てきたとか、どの単位で動いていくかと言ったら、やはりどう考えてもこれは町会しかないと思うわけです。","respondent":"中村都市計画課長、古巻防災課長","answer":"これは組織委員会のほうで検討するですけれども、区といたしましては、区としても意見を言っていくことはこれは自由です。その辺は強く組織委員会のほうへ申し上げてまいります。町会単位で部屋の割り振りをしたりということ、それについて何かルールを崩すという意図はございません。ここはちょっと答弁が紛らわしかったというふうに思っております。","id":"exchange-152"},{"speaker":"渡部委員","kind":"質問","question":"その入場する際、避難所に入る際も、どういうふうに受け付けしようかとかまで町会の方が実は考えてくださってやっているわけです。うまくいっているわけですから、しっかりこれからも運営していければいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-153"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/392487?Template=document&Id=1438#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":111422,"voices":372}}]);
